  // ΓöÇΓöÇ Fetchers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const fetchUnclaimedKupons = useCallback(async () => {
    const supabase = createClient();
    const { data, error } = await supabase.rpc("admin_get_unclaimed_kupons");
    if (!error && data) setUnclaimedKupons(data as UnclaimedKupon[]);
  }, []);

  const fetchGigs = useCallback(async () => {
    const supabase = createClient();
    const { data } = await supabase
      .from("volunteer_gigs")
      .select("id, title, gig_date, start_time, end_time, is_completed, is_cancelled, completed_at, gig_claims(count)")
      .order("gig_date", { ascending: false });

    if (data) {
      const mapped = data.map((row: any) => ({
        ...row,
        participant_count: row.gig_claims?.[0]?.count ?? 0
      }));
      setGigs(mapped);
    }
  }, []);

  const fetchPrograms = useCallback(async () => {
    const supabase = createClient();
    const { data } = await supabase
      .from("mosque_programs")
      .select("*")
      .order("program_date", { ascending: true })
      .order("start_time", { ascending: true });
    if (data) setPrograms(data as MosqueProgram[]);
  }, []);

  const fetchBroadcasts = useCallback(async () => {
    const supabase = createClient();
    const { data } = await supabase
      .from("system_broadcasts")
      .select("id, message, is_active, created_at")
      .order("created_at", { ascending: false })
      .limit(20);
    if (data) {
      const seen = new Set<string>();
      setBroadcasts(
        data
          .filter((b) => {
            if (seen.has(b.message)) return false;
            seen.add(b.message);
            return true;
          })
          .slice(0, 10)
      );
    }
  }, []);

  // ΓöÇΓöÇ Guard: redirect non-admins ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  useEffect(() => {
    if (!isLoading && !isAdmin) {
      toast.error("Access Denied: Admin Privileges Required");
      router.push("/");
    }
  }, [isLoading, isAdmin, router]);

  // ΓöÇΓöÇ Initial fetch + real-time subscriptions ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  useEffect(() => {
    if (!isAdmin) return;
    fetchUnclaimedKupons();
    fetchGigs();
    fetchBroadcasts();
    fetchPrograms();

    const supabase = createClient();

    // Kupons: re-fetch when any claim is inserted, updated, or deleted
    const kuponChannel = supabase
      .channel("admin-kupon-claims")
      .on("postgres_changes", { event: "*", schema: "public", table: "kupon_claims" }, fetchUnclaimedKupons)
      .on("postgres_changes", { event: "*", schema: "public", table: "food_events" }, fetchUnclaimedKupons)
      .subscribe();

    // Gigs: re-fetch on any volunteer_gigs change
    const gigsChannel = supabase
      .channel("admin-volunteer-gigs")
      .on("postgres_changes", { event: "*", schema: "public", table: "volunteer_gigs" }, fetchGigs)
      .subscribe();

    // Broadcasts: re-fetch on any system_broadcasts change
    const broadcastChannel = supabase
      .channel("admin-system-broadcasts")
      .on("postgres_changes", { event: "*", schema: "public", table: "system_broadcasts" }, fetchBroadcasts)
      .subscribe();

    // Programs: re-fetch on mosque_programs change
    const programsChannel = supabase
      .channel("admin-mosque-programs")
      .on("postgres_changes", { event: "*", schema: "public", table: "mosque_programs" }, fetchPrograms)
      .subscribe();

    return () => {
      supabase.removeChannel(kuponChannel);
      supabase.removeChannel(gigsChannel);
      supabase.removeChannel(broadcastChannel);
      supabase.removeChannel(programsChannel);
    };
  }, [fetchUnclaimedKupons, fetchGigs, fetchBroadcasts, fetchPrograms]);

  useEffect(() => {
    async function fetchUsers() {
      const supabase = createClient();
      const { data, error } = await supabase.rpc("admin_get_all_users");
      if (!error) setUsersList(data ?? []);
      else console.error("admin_get_all_users error:", error.message);
    }
    fetchUsers();
  }, [usersRefreshKey]);

  if (isLoading || !isAdmin) {
    return (
      <div className="flex items-center justify-center min-h-[50vh] gap-3 text-text-muted">
        <Loader2 className="animate-spin" size={24} />
        <span>Verifying access...</span>
      </div>
    );
  }

  const latestBroadcast = broadcasts.find((b) => b.is_active)?.message ?? "";

  return (
    <div className="min-h-screen">
      {latestBroadcast && <BroadcastTicker message={latestBroadcast} />}

      <div className="container mx-auto px-4 py-8 max-w-5xl">
        <div className="flex items-center gap-3 mb-8">
          <div className="icon-box icon-box-primary"><Shield size={22} /></div>
          <div>
            <h1 className="text-2xl font-bold text-text">{t.adminTitle}</h1>
            <p className="text-sm text-text-muted">{t.adminSubtitle}</p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <FinancialsCard />
          <BroadcastCard
            broadcasts={broadcasts}
            onRefresh={fetchBroadcasts}
          />
          <KuponScannerCard
            unclaimedKupons={unclaimedKupons}
            onRefresh={fetchUnclaimedKupons}
          />
          {/* ΓöÇΓöÇ Facility Booking Scanner quick-link ΓöÇΓöÇ */}
          <div className="card p-5 flex flex-col gap-4">
            <div className="flex items-center gap-3">
              <div className="icon-box icon-box-primary"><ScanLine size={18} /></div>
              <div>
                <h2 className="text-base font-bold text-text">{t.scanBookingTitle}</h2>
                <p className="text-xs text-text-muted">{t.scanBookingSubtitle}</p>
              </div>
            </div>
            <Link
              href="/admin/scan-booking"
              className="mt-auto w-full py-2.5 px-4 rounded-xl bg-primary hover:bg-primary-dark text-white font-semibold text-sm text-center transition-all shadow-md"
            >
              {t.scanBookingTitle}
            </Link>
          </div>
          <GigCompletionCard
            gigs={gigs}
            onRefresh={fetchGigs}
          />
          <ProgramsManagementCard
            programs={programs}
            onRefresh={fetchPrograms}
          />
          <PushNotificationTestCard />
        </div>

        <div className="mt-6">
          <UserManagementSection
            users={usersList}
            onRefresh={() => setUsersRefreshKey((k) => k + 1)}
            currentUserEmail={user?.email}
          />
        </div>

        <div className="mt-6">
          <SystemSettingsEditor
            initialName={settings.system_name ?? ""}
            initialDesc={settings.system_desc ?? ""}
          />
        </div>

        <div className="mt-6">
          <SkrinMasjidEditor />
        </div>
      </div>
    </div>
  );
}

import { NextResponse } from "next/server";
import Stripe from "stripe";
import { createClient } from "@supabase/supabase-js";

// Initialize Stripe lazily to prevent build-time crashes if keys are missing
let stripeInstance: Stripe | null = null;
const getStripe = () => {
  if (!stripeInstance) {
    if (!process.env.STRIPE_SECRET_KEY) {
      throw new Error("STRIPE_SECRET_KEY is missing");
    }
    stripeInstance = new Stripe(process.env.STRIPE_SECRET_KEY, {
      apiVersion: "2023-10-16" as any, // Standard stable version
    });
  }
  return stripeInstance;
};

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const { campaignId, amount, donorName, donorEmail } = body;

    if (!campaignId || !amount || amount <= 0) {
      return NextResponse.json({ error: "Missing required fields" }, { status: 400 });
    }

    if (amount > 100000) {
      return NextResponse.json({ error: "Donation amount cannot exceed RM100,000" }, { status: 400 });
    }

    // 1. Fetch campaign details
    const { data: campaign, error: campaignError } = await supabaseAdmin
      .from("crowdfund_campaigns")
      .select("title")
      .eq("id", campaignId)
      .single();

    if (campaignError || !campaign) {
      return NextResponse.json({ error: "Campaign not found" }, { status: 404 });
    }

    // 2. Create a pending donation record
    const { data: donation, error: donationError } = await supabaseAdmin
      .from("donations")
      .insert({
        campaign_id: campaignId,
        amount,
        donor_name: donorName || "Anonymous",
        donor_email: donorEmail || null,
        status: "pending",
        payment_gateway: "stripe",
      })
      .select()
      .single();

    if (donationError || !donation) {
      console.error("Failed to create donation:", donationError);
      return NextResponse.json({ error: "Failed to create donation record" }, { status: 500 });
    }

    const appUrl = process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000";

    // 3. Create Stripe Checkout Session (test mode ΓÇö no real charges)
    const session = await getStripe().checkout.sessions.create({
      mode: "payment",
      payment_method_types: ["card"],
      line_items: [
        {
          price_data: {
            currency: "myr",
            unit_amount: Math.round(amount * 100), // Stripe amounts are in cents
            product_data: {
              name: `Donation ΓÇö ${campaign.title}`,
              description: `Thank you for supporting ${campaign.title}`,
            },
          },
          quantity: 1,
        },
      ],
      customer_email: donorEmail || undefined,
      metadata: {
        donation_id: donation.id,
        campaign_id: campaignId,
      },
      success_url: `${appUrl}/crowdfunding?payment=success&donation_id=${donation.id}`,
      cancel_url: `${appUrl}/crowdfunding?payment=cancelled`,
    });

    // 4. Store the Stripe session ID on the donation row
    await supabaseAdmin
      .from("donations")
      .update({ stripe_session_id: session.id })
      .eq("id", donation.id);

    return NextResponse.json({ url: session.url, sessionId: session.id });
  } catch (error) {
    console.error("Stripe checkout error:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";

const PRAYER_LABELS: Record<string, { ms: string; en: string }> = {
  fajr:    { ms: "Subuh", en: "Fajr" },
  syuruk:  { ms: "Syuruk", en: "Syuruk" },
  dhuhr:   { ms: "Zohor", en: "Dhuhr" },
  asr:     { ms: "Asar", en: "Asr" },
  maghrib: { ms: "Maghrib", en: "Maghrib" },
  isha:    { ms: "Isyak", en: "Isha" },
};

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!,
);

export async function POST(req: NextRequest) {
  try {
    const { prayerKey } = await req.json();

    if (!prayerKey || !PRAYER_LABELS[prayerKey]) {
      return NextResponse.json({ error: "Invalid prayerKey" }, { status: 400 });
    }

    // Fetch all FCM tokens from profiles (bypass RLS via service role)
    const { data: profiles, error } = await supabaseAdmin
      .from("profiles")
      .select("fcm_tokens")
      .not("fcm_tokens", "is", null);

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    const tokens: string[] = (profiles ?? [])
      .flatMap((p: { fcm_tokens: string[] | null }) => p.fcm_tokens ?? [])
      .filter(Boolean);

    if (tokens.length === 0) {
      return NextResponse.json({ success: true, sent: 0 });
    }

    const label = PRAYER_LABELS[prayerKey];
    const title = `≡ƒòî Waktu ${label.ms}`;
    const body = `Telah masuk waktu solat ${label.ms}. Segera berwudhu.`;

    // Delegate to the existing push route which handles firebase-admin
    const baseUrl = process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000";
    const pushRes = await fetch(`${baseUrl}/api/notifications/push`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ tokens, title, body, data: { type: "azan", prayerKey } }),
    });

    const pushJson = await pushRes.json();
    if (!pushRes.ok) {
      return NextResponse.json({ error: pushJson.error || "Push failed" }, { status: 500 });
    }

    return NextResponse.json({ success: true, sent: pushJson.successCount ?? tokens.length });
  } catch (err: any) {
    console.error("[azan push]", err);
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import * as admin from "firebase-admin";

// Initialize Firebase Admin SDK
const initializeFirebaseAdmin = () => {
  if (admin.apps.length > 0) return admin.app();

  // We expect the private key to be structured as a JSON string in environment variable
  const serviceAccountStr = process.env.FIREBASE_ADMIN_SDK_JSON;
  
  if (!serviceAccountStr) {
    console.error("FIREBASE_ADMIN_SDK_JSON is missing");
    return null;
  }

  try {
    const serviceAccount = JSON.parse(serviceAccountStr);
    return admin.initializeApp({
      credential: admin.credential.cert(serviceAccount),
    });
  } catch (error) {
    console.error("Error parsing FIREBASE_ADMIN_SDK_JSON:", error);
    return null;
  }
};

export async function POST(req: NextRequest) {
  try {
    const app = initializeFirebaseAdmin();
    if (!app) {
      return NextResponse.json({ error: "Push service not configured" }, { status: 500 });
    }

    const { tokens, title, body, data } = await req.json();

    if (!tokens || !Array.isArray(tokens) || tokens.length === 0) {
      return NextResponse.json({ error: "At least one token is required" }, { status: 400 });
    }

    // FCM Multicast allows sending to multiple tokens at once (max 500)
    const message = {
      notification: {
        title,
        body,
      },
      data: data || {},
      tokens: tokens,
    };

    const response = await admin.messaging().sendEachForMulticast(message);

    return NextResponse.json({
      success: true,
      successCount: response.successCount,
      failureCount: response.failureCount,
    });

  } catch (error: any) {
    console.error("Error sending push notification:", error);
    return NextResponse.json({ error: error.message || "Failed to send notification" }, { status: 500 });
  }
}

import { NextResponse, type NextRequest } from "next/server";
import Stripe from "stripe";
import { createClient } from "@supabase/supabase-js";

// Initialize Stripe lazily to prevent build-time crashes if keys are missing
let stripeInstance: Stripe | null = null;
const getStripe = () => {
  if (!stripeInstance) {
    if (!process.env.STRIPE_SECRET_KEY) {
      throw new Error("STRIPE_SECRET_KEY is missing");
    }
    stripeInstance = new Stripe(process.env.STRIPE_SECRET_KEY, {
      apiVersion: "2023-10-16" as any,
    });
  }
  return stripeInstance;
};

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

export async function POST(req: NextRequest) {
  const rawBody = await req.text();
  const sig = req.headers.get("stripe-signature");
  const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;

  if (!webhookSecret) {
    console.error("STRIPE_WEBHOOK_SECRET is not set");
    return NextResponse.json({ error: "Webhook not configured" }, { status: 500 });
  }

  // Verify the event came from Stripe
  let event: Stripe.Event;
  try {
    event = getStripe().webhooks.constructEvent(rawBody, sig ?? "", webhookSecret);
  } catch (err) {
    console.warn("Stripe webhook signature verification failed:", err);
    return NextResponse.json({ error: "Invalid signature" }, { status: 400 });
  }

  try {
    if (event.type === "checkout.session.completed") {
      const session = event.data.object as Stripe.Checkout.Session;
      const donationId = session.metadata?.donation_id;

      if (!donationId) {
        console.warn("Webhook: no donation_id in session metadata");
        return NextResponse.json({ received: true });
      }

      // Fetch the donation
      const { data: donation, error } = await supabaseAdmin
        .from("donations")
        .select("id, status, campaign_id, amount")
        .eq("id", donationId)
        .single();

      if (error || !donation) {
        console.error("Webhook: donation not found:", donationId);
        return NextResponse.json({ error: "Donation not found" }, { status: 404 });
      }

      // Idempotency ΓÇö skip if already completed
      if (donation.status === "completed") {
        return NextResponse.json({ received: true });
      }

      // Mark donation as completed
      const { error: updateError } = await supabaseAdmin
        .from("donations")
        .update({
          status: "completed",
          payment_intent_id: session.payment_intent as string ?? session.id,
          updated_at: new Date().toISOString(),
        })
        .eq("id", donationId)
        .neq("status", "completed");

      if (updateError) {
        console.error(`Webhook error updating donation ${donationId}:`, updateError.message);
        return NextResponse.json({ error: "Failed to update donation status" }, { status: 500 });
      }

      console.log(`Webhook SUCCESS: donation ${donationId} marked COMPLETED`);
    }

    if (event.type === "checkout.session.expired") {
      const session = event.data.object as Stripe.Checkout.Session;
      const donationId = session.metadata?.donation_id;
      if (donationId) {
        await supabaseAdmin
          .from("donations")
          .update({ status: "failed", updated_at: new Date().toISOString() })
          .eq("id", donationId)
          .eq("status", "pending");
        console.log(`Webhook: donation ${donationId} expired`);
      }
    }

    return NextResponse.json({ received: true });
  } catch (err) {
    console.error("Webhook processing error:", err);
    return NextResponse.json({ error: "Webhook handler failed" }, { status: 500 });
  }
}

"use client";

import { useState, useEffect } from "react";
import { HandHeart, X, Heart, Plus, Pencil, Trash2, AlertTriangle, Loader2, Download } from "lucide-react";
import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/components/providers/AuthContext";
import { toast } from "react-hot-toast";
import { useLanguage } from "@/components/providers/LanguageContext";
import Pagination from "@/components/ui/Pagination";
import DonationReceiptModal from "@/components/modals/DonationReceiptModal";

type Campaign = {
  id: string;
  title: string;
  description: string;
  target_amount: number;
  current_amount: number;
  donor_count: number;
  images: string[];
  completed_at: string | null;
};

// timeout helper
function waitMs(ms: number): Promise<null> {
  return new Promise((r) => setTimeout(() => r(null), ms));
}

export default function CrowdfundingPage() {
  const { isAdmin, user } = useAuth();
  const { t, language } = useLanguage();
  const [campaigns, setCampaigns] = useState<Campaign[]>([]);
  const [loading, setLoading] = useState(true);
  const [fetchError, setFetchError] = useState<string | null>(null);

  const [donateModal, setDonateModal] = useState<string | null>(null);
  const [donationAmount, setDonationAmount] = useState<number>(50);
  const [donorName, setDonorName] = useState("");
  const [donorEmail, setDonorEmail] = useState("");
  const [donorPhone, setDonorPhone] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);

  const [showAddModal, setShowAddModal] = useState(false);
  const [editingCampaign, setEditingCampaign] = useState<Campaign | null>(null);
  const [deletingCampaign, setDeletingCampaign] = useState<Campaign | null>(null);
  const [showSuccessModal, setShowSuccessModal] = useState<{ id: string, amount: number } | null>(null);
  const [showReceiptModal, setShowReceiptModal] = useState<string | null>(null);
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const CAMPAIGNS_PER_PAGE = 4;
  const [campaignsPage, setCampaignsPage] = useState(1);

  const fetchCampaigns = async () => {
    try {
      const supabase = createClient();
      const { data, error } = await supabase
        .from("crowdfund_campaigns")
        .select("*")
        .order("created_at", { ascending: false });

      if (error) {
        console.error("Crowdfunding fetch error:", error);
        setFetchError(error.message);
      } else {
        setFetchError(null);
        setCampaigns(data || []);
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCampaigns();

    const supabase = createClient();
    const channel = supabase
      .channel("crowdfund_campaigns_realtime")
      .on(
        "postgres_changes",
        { event: "UPDATE", schema: "public", table: "crowdfund_campaigns" },
        (payload) => {
          setCampaigns((current) =>
            current.map((c) =>
              c.id === payload.new.id ? { ...c, ...payload.new } : c
            )
          );
        }
      )
      .on(
        "postgres_changes",
        { event: "INSERT", schema: "public", table: "crowdfund_campaigns" },
        fetchCampaigns
      )
      .on(
        "postgres_changes",
        { event: "DELETE", schema: "public", table: "crowdfund_campaigns" },
        fetchCampaigns
      )
      .subscribe();

    // Check for payment success in URL
    const urlParams = new URLSearchParams(window.location.search);
    const paymentStatus = urlParams.get('payment');
    const donationId = urlParams.get('donation_id');

    if (paymentStatus === 'success') {
      console.log("SUCESS: Triggering modal for donation:", donationId);
      setShowSuccessModal({ id: donationId || "", amount: 0 });
    } else if (paymentStatus === 'failed') {
      toast.error(t.donationFailed);
      window.history.replaceState({}, document.title, window.location.pathname);
    }

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  const activeCampaign = campaigns.find((c) => c.id === donateModal);

  // Autofill donor info from logged-in user
  useEffect(() => {
    if (!donateModal || !user) return;
    setDonorEmail(user.email || "");
    const supabase = createClient();
    supabase.from("profiles").select("display_name, phone").eq("id", user.id).single()
      .then(({ data }) => {
        if (data?.display_name) setDonorName(data.display_name);
        if (data?.phone) setDonorPhone(data.phone);
      });
  }, [donateModal, user?.id]);

  const handleDonate = async () => {
    if (!activeCampaign || !donationAmount) return;
    setIsProcessing(true);
    try {
      // Save phone number for future autofill if user is logged in
      if (user && donorPhone.trim()) {
        const supabase = createClient();
        supabase.from("profiles").update({ phone: donorPhone.trim() }).eq("id", user.id);
      }

      const response = await fetch("/api/checkout/stripe", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          campaignId: activeCampaign.id,
          amount: donationAmount,
          donorName: donorName || "Anonymous",
          donorEmail: donorEmail || "",
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Failed to initiate payment");
      }

      if (data.url) {
        window.location.href = data.url;
      } else {
        throw new Error("No payment URL received");
      }
    } catch (error: any) {
      console.error("Donation error:", error);
      toast.error(error.message || "Failed to process donation. Please try again.");
      setIsProcessing(false);
    }
  };

  return (
    <div className="container mx-auto px-4 py-8 max-w-2xl">
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-3">
          <div className="text-primary">
            <HandHeart size={28} strokeWidth={2.5} />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-text">{t.crowdfundTitle}</h1>
            <p className="text-sm text-text-muted">{t.crowdfundSubtitle}</p>
          </div>
        </div>
        {isAdmin && (
          <button
            onClick={() => setShowAddModal(true)}
            className="btn-primary py-2 px-4 shadow-md rounded-xl text-sm flex items-center gap-2"
          >
            <Plus size={16} /> <span className="hidden sm:inline">{language === 'ms' ? 'Tambah Kempen' : 'Add Campaign'}</span>
          </button>
        )}
      </div>

      <div className="space-y-4">
        {loading ? (
          <div className="text-center py-10 text-text-muted">{t.loading}</div>
        ) : fetchError ? (
          <div className="card p-8 text-center">
            <div className="text-red-500 dark:text-red-400 text-sm mb-3">{fetchError}</div>
            <button onClick={fetchCampaigns} className="px-5 py-2 btn-primary text-sm">{t.retry ?? "Retry"}</button>
          </div>
        ) : campaigns.length === 0 ? (
          <div className="text-center py-10 bg-surface rounded-2xl border border-border shadow-sm">
            <HandHeart size={48} className="mx-auto text-text-muted opacity-30 mb-4" />
            <h3 className="text-text font-bold text-lg">No Campaigns</h3>
            <p className="text-text-secondary text-sm mt-1">{t.noCampaigns}</p>
          </div>
        ) : (
          campaigns
            .filter(c => {
              if (!c.completed_at) return true;
              const completedTime = new Date(c.completed_at).getTime();
              const thirtyMinutes = 30 * 60 * 1000;
              return currentTime.getTime() - completedTime < thirtyMinutes;
            })
            .slice((campaignsPage - 1) * CAMPAIGNS_PER_PAGE, campaignsPage * CAMPAIGNS_PER_PAGE)
            .map((c) => {
              const pct = Math.min(100, Math.round((c.current_amount / c.target_amount) * 100));
              const donorsCount = c.donor_count || 0;
              const isGoalReached = c.current_amount >= c.target_amount;

              let countdownText = null;
              if (c.completed_at) {
                const remainingMs = (new Date(c.completed_at).getTime() + 30 * 60 * 1000) - currentTime.getTime();
                if (remainingMs > 0) {
                  const mins = Math.floor(remainingMs / 60000);
                  const secs = Math.floor((remainingMs % 60000) / 1000);
                  countdownText = `${mins}:${secs.toString().padStart(2, '0')}`;
                }
              }

              return (
                <div key={c.id} className={`card p-6 relative overflow-hidden ${isGoalReached ? 'grayscale-[0.4] bg-primary-50/10' : ''}`}>
                  {isGoalReached && (
                    <div className="absolute top-0 left-0 right-0 bg-primary/95 text-white text-[10px] font-bold uppercase tracking-widest py-1 text-center z-10">
                      Goal Reached {countdownText && `ΓÇö Delisting in ${countdownText}`}
                    </div>
                  )}
                  <div className="flex items-start justify-between mb-2 mt-2">
                    <h3 className="font-bold text-lg text-text pr-2">{c.title}</h3>
                    <div className="flex items-center gap-2 shrink-0">
                      <span className="badge bg-gold-light/20 text-gold">
                        <Heart size={10} /> {donorsCount} donors
                      </span>
                      {isAdmin && (
                        <>
                          <button
                            onClick={() => setEditingCampaign(c)}
                            className="w-7 h-7 rounded bg-background border border-border flex items-center justify-center text-text-secondary hover:bg-primary-50 hover:text-primary"
                          >
                            <Pencil size={12} />
                          </button>
                          <button
                            onClick={() => setDeletingCampaign(c)}
                            className="w-7 h-7 rounded bg-background border border-border flex items-center justify-center text-text-secondary hover:bg-red-50 hover:text-red-500"
                          >
                            <Trash2 size={12} />
                          </button>
                        </>
                      )}
                    </div>
                  </div>
                  <p className="text-sm text-text-secondary mb-4">{c.description}</p>

                  {c.images && c.images.length > 0 && (
                    <div className="flex gap-2 mb-4 overflow-x-auto pb-2 snap-x hide-scrollbar">
                      {c.images.map((img, idx) => (
                        <img
                          key={idx}
                          src={img}
                          alt="Campaign"
                          className="h-20 w-auto max-w-[120px] rounded-lg object-cover snap-start border border-border"
                          onError={(e) => { (e.target as HTMLImageElement).style.display = 'none'; }}
                        />
                      ))}
                    </div>
                  )}

                  <div className="flex justify-between text-sm mb-2 font-medium">
                    <span className={`font-bold text-lg ${isGoalReached ? 'text-primary' : 'text-primary'}`}>
                      RM{c.current_amount.toLocaleString()}
                    </span>
                    <span className="text-text-muted">of RM{c.target_amount.toLocaleString()}</span>
                  </div>
                  <div className="progress-bar mb-1">
                    <div className="progress-fill" style={{ width: `${pct}%` }} />
                  </div>
                  <p className="text-xs text-text-muted mb-5 text-right">{t.progressLabel(pct)}</p>

                  <button
                    onClick={() => !isGoalReached && setDonateModal(c.id)}
                    disabled={isGoalReached}
                    className={`w-full py-3 text-sm flex justify-center items-center gap-2 rounded-xl font-bold transition-all ${isGoalReached
                        ? "bg-text-muted/20 text-text-muted border border-border cursor-not-allowed"
                        : "btn-primary"
                      }`}
                  >
                    <HandHeart size={16} />
                    {isGoalReached ? "Goal Reached" : t.donateNow}
                  </button>
                </div>
              );
            })
        )}
        <Pagination
          page={campaignsPage}
          total={campaigns.length}
          perPage={CAMPAIGNS_PER_PAGE}
          onChange={setCampaignsPage}
        />
      </div>

      {/* Donate Modal */}
      {donateModal && activeCampaign && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4" onClick={() => setDonateModal(null)}>
          <div className="bg-surface rounded-2xl w-full max-w-md shadow-2xl relative" onClick={(e) => e.stopPropagation()}>
            <button onClick={() => setDonateModal(null)} className="absolute top-4 right-4 z-20 text-white/50 hover:text-white transition bg-black/20 rounded-full p-1">
              <X size={20} />
            </button>
            <div className="hero-gradient p-6 text-white overflow-hidden rounded-t-2xl relative">
              <div className="absolute top-0 right-0 w-32 h-32 bg-surface/5 rounded-full -mt-16 -mr-16 blur-2xl" />
              <p className="text-sm text-white/60 relative z-10">Donate to</p>
              <h2 className="text-lg font-bold mt-1 relative z-10">{activeCampaign.title}</h2>
            </div>
            <div className="p-6">
              <p className="text-xs font-bold uppercase tracking-widest text-text-muted mb-3">Select Amount</p>
              <div className="grid grid-cols-3 gap-3 mb-4">
                {[20, 50, 100].map((amt) => (
                  <button
                    key={amt}
                    onClick={() => setDonationAmount(amt)}
                    className={`py-3 font-bold text-sm rounded-xl border transition-colors ${donationAmount === amt
                        ? "bg-primary text-white border-primary"
                        : "bg-background text-primary border-primary hover:bg-primary-50"
                      }`}
                  >
                    RM{amt}
                  </button>
                ))}
              </div>

              <div className="mb-4">
                <label className="text-xs font-semibold text-text-secondary uppercase mb-1.5 block">Custom Amount (RM)</label>
                <input
                  type="number"
                  value={donationAmount}
                  onChange={(e) => setDonationAmount(Number(e.target.value))}
                  className={`w-full px-3 py-2 border rounded-xl text-sm outline-none bg-background focus:ring-2 ${donationAmount > 100000 ? "border-red-500 focus:ring-red-500/20" : "border-border focus:border-primary focus:ring-primary/20"
                    }`}
                  min="1"
                  max="100000"
                />
                {donationAmount > 100000 && (
                  <p className="text-xs text-red-500 mt-1">Maximum donation amount is RM100,000</p>
                )}
              </div>

              <div className="space-y-3 mb-6">
                <div>
                  <label className="text-xs font-semibold text-text-secondary uppercase mb-1.5 block">Name (Optional)</label>
                  <input
                    type="text"
                    value={donorName}
                    onChange={(e) => setDonorName(e.target.value)}
                    placeholder="Anonymous"
                    className="w-full px-3 py-2 border border-border rounded-xl text-sm outline-none focus:border-primary bg-background"
                  />
                </div>
                <div>
                  <label className="text-xs font-semibold text-text-secondary uppercase mb-1.5 block">Email (Optional)</label>
                  <input
                    type="email"
                    value={donorEmail}
                    onChange={(e) => setDonorEmail(e.target.value)}
                    placeholder="For receipt"
                    className="w-full px-3 py-2 border border-border rounded-xl text-sm outline-none focus:border-primary bg-background"
                  />
                </div>
                <div>
                  <label className="text-xs font-semibold text-text-secondary uppercase mb-1.5 block">Phone (Optional)</label>
                  <input
                    type="tel"
                    value={donorPhone}
                    onChange={(e) => setDonorPhone(e.target.value)}
                    placeholder="0123456789"
                    maxLength={15}
                    className="w-full px-3 py-2 border border-border rounded-xl text-sm outline-none focus:border-primary bg-background"
                  />
                </div>
              </div>

              <button
                onClick={handleDonate}
                disabled={isProcessing || !donationAmount || donationAmount <= 0 || donationAmount > 100000}
                className="w-full py-3.5 btn-primary text-sm flex justify-center items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isProcessing ? (
                  <><Loader2 size={16} className="animate-spin" /> Processing...</>
                ) : (
                  `Proceed to Pay RM${donationAmount}`
                )}
              </button>
              <p className="text-xs text-text-muted text-center mt-3">Secure payment via Stripe (Test Mode)</p>
            </div>
          </div>
        </div>
      )}

      {/* Admin Modals */}
      {showAddModal && (
        <CampaignFormModal
          mode="add"
          onClose={() => setShowAddModal(false)}
          onSave={(c) => { setCampaigns([c, ...campaigns]); fetchCampaigns(); }}
        />
      )}
      {editingCampaign && (
        <CampaignFormModal
          mode="edit"
          campaign={editingCampaign}
          onClose={() => setEditingCampaign(null)}
          onSave={(c) => { setCampaigns(campaigns.map(camp => camp.id === c.id ? c : camp)); fetchCampaigns(); }}
        />
      )}
      {deletingCampaign && (
        <DeleteCampaignModal
          campaign={deletingCampaign}
          onClose={() => setDeletingCampaign(null)}
          onDelete={(id) => { setCampaigns(campaigns.filter(c => c.id !== id)); }}
        />
      )}

      {/* Success Modal */}
      {showSuccessModal && (
        <DonationSuccessModal
          donationId={showSuccessModal.id}
          onClose={() => {
            setShowSuccessModal(null);
            // Clean up URL only when modal is closed
            window.history.replaceState({}, document.title, window.location.pathname);
          }}
          onShowReceipt={(id) => setShowReceiptModal(id)}
        />
      )}

      {/* Receipt Modal */}
      {showReceiptModal && (
        <DonationReceiptModal
          donationId={showReceiptModal}
          onClose={() => setShowReceiptModal(null)}
        />
      )}
    </div>
  );
}

