function DonationSuccessModal({ onClose, donationId, onShowReceipt }: { onClose: () => void, donationId: string, onShowReceipt: (id: string) => void }) {
  const { t } = useLanguage();

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[200] flex items-center justify-center p-4 animate-in fade-in duration-300" onClick={onClose}>
      <div className="bg-surface rounded-3xl w-full max-w-sm shadow-[0_0_50px_rgba(0,0,0,0.3)] relative overflow-hidden text-center scale-up-center" onClick={(e) => e.stopPropagation()}>
        <div className="hero-gradient py-12 px-6 text-white relative">
          <div className="absolute top-0 right-0 w-40 h-40 bg-white/10 rounded-full -mt-20 -mr-20 blur-3xl animate-pulse" />
          <div className="absolute bottom-0 left-0 w-32 h-32 bg-primary-light/20 rounded-full -mb-16 -ml-16 blur-2xl" />

          <div className="w-20 h-20 bg-white rounded-full mx-auto flex items-center justify-center text-primary shadow-xl mb-6 relative z-10 bounce-in">
            <HandHeart size={40} strokeWidth={2.5} />
          </div>

          <h2 className="text-2xl font-black mb-2 tracking-tight relative z-10">{t.donationSuccess}</h2>
          <p className="text-white/80 text-sm font-medium relative z-10">Your contribution makes a huge difference!</p>
        </div>

        <div className="p-8">
          <p className="text-text-secondary text-sm leading-relaxed mb-8">
            Thank you for your generous donation. A receipt and confirmation has been sent to your email.
          </p>

          <div className="flex flex-col gap-3">
            <button
              onClick={onClose}
              className="w-full py-4 bg-primary hover:bg-primary-dark text-white rounded-2xl font-bold shadow-lg shadow-primary/20 transition-all hover:scale-[1.02] active:scale-[0.98]"
            >
              Done
            </button>
            <button
              onClick={() => onShowReceipt(donationId)}
              className="w-full py-3 bg-surface-alt border border-border hover:bg-primary/5 hover:border-primary/30 rounded-xl text-xs font-bold text-text-secondary hover:text-primary transition-all flex items-center justify-center gap-2"
            >
              <Download size={14} />
              View Receipt
            </button>
          </div>

          <p className="text-[10px] text-text-muted mt-4 uppercase tracking-widest font-bold">Project Makmur Crowdfunding</p>
        </div>
      </div>
    </div>
  );
}

// -------------------------------------------------------------------------------------------------
// Admin CRUD Components
// -------------------------------------------------------------------------------------------------

function CampaignFormModal({ mode, campaign, onClose, onSave }: { mode: "add" | "edit", campaign?: Campaign, onClose: () => void, onSave: (c: Campaign) => void }) {
  const isEdit = mode === "edit";
  const { t } = useLanguage();
  const [title, setTitle] = useState(campaign?.title || "");
  const [description, setDescription] = useState(campaign?.description || "");
  const [target, setTarget] = useState(String(campaign?.target_amount || "10000"));
  const [current, setCurrent] = useState(String(campaign?.current_amount || "0"));
  const [images, setImages] = useState(campaign?.images || []);
  const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
  const [saving, setSaving] = useState(false);

  const handleSave = async () => {
    if (!title.trim() || !target) return;
    setSaving(true);
    const supabase = createClient();

    try {
      let uploadedUrls: string[] = [];

      // Upload selected files if any
      if (selectedFiles.length > 0) {
        for (const file of selectedFiles) {
          const fileExt = file.name.split('.').pop();
          const fileName = `${Date.now()}-${crypto.randomUUID()}.${fileExt}`;
          const { data: uploadData, error: uploadError } = await supabase
            .storage
            .from('campaigns')
            .upload(fileName, file);

          if (!uploadError && uploadData) {
            const { data: { publicUrl } } = supabase
              .storage
              .from('campaigns')
              .getPublicUrl(fileName);
            uploadedUrls.push(publicUrl);
          }
        }
      }

      // Keep existing images plus newly uploaded ones, limited to 4
      const finalImages = [...(Array.isArray(images) ? images : []), ...uploadedUrls].slice(0, 4);

      const payload = {
        title: title.trim(),
        description: description.trim(),
        target_amount: parseFloat(target) || 0,
        current_amount: parseFloat(current) || 0,
        images: finalImages
      };

      if (isEdit && campaign) {
        await Promise.race([
          supabase.from("crowdfund_campaigns").update(payload).eq("id", campaign.id),
          waitMs(5000)
        ]);
        onSave({ ...campaign, ...payload });
        toast.success("Campaign updated!");
      } else {
        const { data } = await Promise.race([
          supabase.from("crowdfund_campaigns").insert(payload).select().single(),
          waitMs(5000)
        ]) as any;

        if (data) {
          // ΓöÇΓöÇ Native Push Notification for New Campaign ΓöÇΓöÇ
          try {
            const { data: profiles } = await supabase
              .from("profiles")
              .select("fcm_tokens")
              .not("fcm_tokens", "is", null);

            if (profiles) {
              const allTokens = profiles.flatMap(p => p.fcm_tokens || []).filter(Boolean);
              if (allTokens.length > 0) {
                await fetch("/api/notifications/push", {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({
                    tokens: allTokens,
                    title: "New Fundraiser Launched!",
                    body: `Support our latest cause: "${title.trim()}". RM${target.toLocaleString()} target.`,
                    data: { url: "/crowdfunding" }
                  }),
                });
              }
            }
          } catch (pushErr) {
            console.error("Campaign push failed:", pushErr);
          }
        }

        // if timeout, provide a fallback visual update
        onSave(data || { id: crypto.randomUUID(), ...payload });
        toast.success("Campaign created!");
      }
      onClose();
    } catch {
      toast.error("Failed to save campaign.");
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-surface rounded-2xl w-full max-w-md relative" onClick={(e) => e.stopPropagation()}>
        <button onClick={onClose} className="absolute top-4 right-4 z-20 text-white/50 hover:text-white transition bg-black/20 rounded-full p-1">
          <X size={20} />
        </button>
        <div className="hero-gradient p-5 text-white overflow-hidden rounded-t-2xl relative">
          <div className="absolute top-0 right-0 w-32 h-32 bg-surface/5 rounded-full -mt-16 -mr-16 blur-2xl" />
          <h2 className="text-lg font-bold relative z-10">{isEdit ? t.campaignEditTitle : t.campaignAddTitle}</h2>
        </div>
        <div className="p-6 space-y-4">
          <div>
            <label className="text-xs font-semibold text-text-secondary uppercase mb-1.5 block">{t.campaignFieldTitle}</label>
            <input type="text" value={title} onChange={e => setTitle(e.target.value)} className="w-full px-3 py-2 border border-border rounded-xl text-sm outline-none focus:border-primary bg-background" />
          </div>
          <div>
            <label className="text-xs font-semibold text-text-secondary uppercase mb-1.5 block">{t.campaignFieldDesc}</label>
            <textarea value={description} onChange={e => setDescription(e.target.value)} rows={3} className="w-full px-3 py-2 border border-border rounded-xl text-sm outline-none focus:border-primary bg-background" />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-xs font-semibold text-text-secondary uppercase mb-1.5 block">{t.campaignFieldTarget}</label>
              <input type="number" value={target} onChange={e => setTarget(e.target.value)} className="w-full px-3 py-2 border border-border rounded-xl text-sm outline-none focus:border-primary bg-background" />
            </div>
            <div>
              <label className="text-xs font-semibold text-text-secondary uppercase mb-1.5 block">{t.campaignFieldCurrent}</label>
              <input type="number" value={current} onChange={e => setCurrent(e.target.value)} className="w-full px-3 py-2 border border-border rounded-xl text-sm outline-none focus:border-primary bg-background" />
            </div>
          </div>
          <div>
            <label className="text-xs font-semibold text-text-secondary uppercase mb-1.5 block">{t.campaignFieldImages}</label>
            <input
              type="file"
              accept="image/*"
              multiple
              onChange={(e) => {
                const files = Array.from(e.target.files || []);
                const currentSlots = Array.isArray(images) ? images.length : 0;
                const allowedNew = 4 - currentSlots;
                setSelectedFiles(files.slice(0, allowedNew));
              }}
              disabled={Array.isArray(images) && images.length >= 4}
              className="w-full text-sm text-text-secondary file:mr-4 file:py-2 file:px-4 file:rounded-xl file:border-0 file:text-sm file:font-bold file:bg-primary-50 file:text-primary hover:file:bg-[#D5F5E3] cursor-pointer"
            />
            {selectedFiles.length > 0 && (
              <p className="text-xs text-text-muted mt-1">{t.campaignFilesSelected(selectedFiles.length)}</p>
            )}
            {Array.isArray(images) && images.length > 0 && (
              <div className="flex gap-2 mt-2">
                {images.map((img, i) => (
                  <div key={i} className="relative">
                    <img src={img} className="h-10 w-10 object-cover rounded shadow-sm border border-border" />
                    <button title="Remove image" onClick={() => setImages(images.filter((_, idx) => idx !== i))} className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full p-0.5">
                      <X size={10} />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
          <button onClick={handleSave} disabled={saving || !title.trim()} className="w-full py-3.5 btn-primary text-sm mt-2 flex justify-center gap-2">
            {saving && <Loader2 size={16} className="animate-spin" />} {saving ? t.campaignSaving : t.campaignSaveBtn}
          </button>
        </div>
      </div>
    </div>
  );
}

function DeleteCampaignModal({ campaign, onClose, onDelete }: { campaign: Campaign, onClose: () => void, onDelete: (id: string) => void }) {
  const [deleting, setDeleting] = useState(false);
  const { t } = useLanguage();

  const handleDelete = async () => {
    setDeleting(true);
    const supabase = createClient();
    await Promise.race([
      supabase.from("crowdfund_campaigns").delete().eq("id", campaign.id),
      waitMs(5000)
    ]);
    toast.success("Campaign deleted.");
    onDelete(campaign.id);
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-surface rounded-2xl w-full max-w-sm overflow-hidden" onClick={e => e.stopPropagation()}>
        <div className="bg-red-50 dark:bg-red-950 p-5 flex items-center justify-between border-b border-red-100 dark:border-red-900">
          <div className="flex gap-3 items-center">
            <AlertTriangle className="text-red-500" />
            <h2 className="font-bold text-red-900 dark:text-red-200">{t.campaignDeleteTitle}</h2>
          </div>
          <button onClick={onClose} className="text-red-500 hover:text-red-700 bg-red-100 p-1 rounded-md"><X size={18} /></button>
        </div>
        <div className="p-6">
          <p className="text-sm text-text-secondary mb-4">Are you sure you want to delete "{campaign.title}"?</p>
          <button onClick={handleDelete} disabled={deleting} className="w-full py-3 bg-red-500 text-white rounded-xl font-bold flex justify-center gap-2">
            {deleting && <Loader2 size={16} className="animate-spin" />} {deleting ? t.campaignDeleting : t.campaignDeleteBtn}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Cloud, TrendingUp, BarChart3, Zap, Loader2 } from "lucide-react";
import { createClient } from "@/lib/supabase/client";
import { getAiCrowdPrediction, CrowdPrediction } from "@/lib/ai/getAiPrediction";
import { useLanguage } from "@/components/providers/LanguageContext";
import BroadcastTicker from "@/components/layout/BroadcastTicker";

const attendanceData = [
  { day: "Mon", value: 320 },
  { day: "Tue", value: 210 },
  { day: "Wed", value: 480 },
  { day: "Thu", value: 390 },
  { day: "Fri", value: 1100 },
  { day: "Sat", value: 720 },
  { day: "Sun", value: 680 },
];

export default function DashboardPage() {
  const { t } = useLanguage();
  const [selectedDate, setSelectedDate] = useState(() => new Date().toISOString().split("T")[0]);
  const isWeekend = ["0", "6"].includes(String(new Date(selectedDate).getDay()));
  
  const [weatherData, setWeatherData] = useState<{ temp: number; code: number; desc: string } | null>(null);
  const [prediction, setPrediction] = useState<CrowdPrediction | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Fetch latest broadcast from DB + subscribe to real-time updates
  const [latestBroadcast, setLatestBroadcast] = useState<string>("");
  useEffect(() => {
    const supabase = createClient();
    async function fetchBroadcast() {
      const { data } = await supabase
        .from('system_broadcasts')
        .select('message')
        .eq('is_active', true)
        .order('created_at', { ascending: false })
        .limit(1)
        .single();
      if (data) setLatestBroadcast(data.message);
    }
    fetchBroadcast();

    const channel = supabase
      .channel("dashboard-broadcasts")
      .on("postgres_changes", { event: "*", schema: "public", table: "system_broadcasts" }, fetchBroadcast)
      .subscribe();

    const onBroadcastSent = () => fetchBroadcast();
    window.addEventListener("makmur:broadcast-sent", onBroadcastSent);

    return () => {
      supabase.removeChannel(channel);
      window.removeEventListener("makmur:broadcast-sent", onBroadcastSent);
    };
  }, []);

  // Fetch Weather and AI Prediction when date changes
  useEffect(() => {
    async function fetchPredictionData() {
      setIsLoading(true);
      setError(null);
      try {
        // 1. Fetch Weather from Open-Meteo (Kuala Lumpur coordinates)
        // Using forecast for future dates, or current weather for today
        const lat = 3.1390;
        const lon = 101.6869;
        
        // Calculate days difference to see if we need forecast or historical
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const target = new Date(selectedDate);
        target.setHours(0, 0, 0, 0);
        const diffTime = Math.abs(target.getTime() - today.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        let weatherCode = 0; // Default clear sky
        let temp = 28;
        let desc = "Clear";

        // Open-Meteo only provides 16 days forecast for free
        // DISABLED WEATHER API TO AVOID USAGE LIMITS
        /*
        if (diffDays <= 16 && target >= today) {
          const weatherRes = await fetch(
            `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&daily=weather_code,temperature_2m_max&timezone=Asia%2FSingapore&start_date=${selectedDate}&end_date=${selectedDate}`
          );
          
          if (weatherRes.ok) {
            const wData = await weatherRes.json();
            if (wData.daily && wData.daily.weather_code && wData.daily.weather_code.length > 0) {
              weatherCode = wData.daily.weather_code[0];
              temp = Math.round(wData.daily.temperature_2m_max[0]);
              
              // Simple WMO code mapping
              if (weatherCode <= 3) desc = "Clear/Cloudy";
              else if (weatherCode <= 49) desc = "Fog/Mist";
              else if (weatherCode <= 69) desc = "Rain";
              else if (weatherCode <= 79) desc = "Snow";
              else desc = "Storm";
            }
          }
        }
        */

        setWeatherData({ temp, code: weatherCode, desc });

        // 2. Call AI Predictor
        const aiResult = await getAiCrowdPrediction(selectedDate, weatherCode, isWeekend);
        setPrediction(aiResult);

      } catch (err: any) {
        console.error("Failed to fetch prediction data:", err);
        setError(err.message || "Failed to load prediction");
      } finally {
        setIsLoading(false);
      }
    }

    fetchPredictionData();
  }, [selectedDate, isWeekend]);

  return (
    <div className="min-h-screen">
      {/* Broadcast Banner */}
      {latestBroadcast && <BroadcastTicker message={latestBroadcast} />}

      <div className="container mx-auto px-4 py-8 max-w-6xl">
        <div className="flex items-center gap-3 mb-8">
          <div className="icon-box icon-box-primary"><BarChart3 size={22} /></div>
          <div>
            <h1 className="text-2xl font-bold text-text">{t.dashboardTitle}</h1>
            <p className="text-sm text-text-muted">{t.dashboardSubtitle}</p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
          {/* Select Date */}
          <div className="card p-6">
            <h2 className="font-bold text-lg text-text mb-5">{t.dashboardSelectDate}</h2>
            <input
              type="date"
              value={selectedDate}
              onChange={(e) => setSelectedDate(e.target.value)}
              className="w-full px-4 py-3 border border-border rounded-xl text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none bg-background"
            />
            <div className="mt-6 space-y-3">
              <p className="text-xs font-bold uppercase tracking-widest text-gold mb-1">{t.dashboardModelInputs}</p>
              {[
                [t.dashboardDayOfRamadan, t.dashboardAutoCalc],
                [t.dashboardIsWeekend, isWeekend ? t.yes : t.no],
                [t.dashboardWeatherAPI, weatherData ? `${weatherData.desc} (${weatherData.temp}┬░C)` : t.loading],
              ].map(([label, val]) => (
                <div key={label} className="flex justify-between text-sm py-1.5 border-b border-dashed border-border last:border-0">
                  <span className="text-text-secondary">{label}</span>
                  <span className={`font-semibold ${val === "Connected" || val?.includes("┬░C") ? "text-primary" : "text-text"}`}>{val}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Prediction Results */}
          <div className="card p-6 relative">
            {isLoading && (
              <div className="absolute inset-0 bg-surface/80 backdrop-blur-sm z-10 flex items-center justify-center rounded-2xl">
                <Loader2 className="animate-spin text-primary" size={32} />
              </div>
            )}
            <h2 className="font-bold text-lg text-text mb-5">{t.dashboardPredictionResults}</h2>
            
            {error ? (
              <div className="bg-red-50 text-red-600 p-4 rounded-xl text-sm border border-red-100">
                <p className="font-bold mb-1">{t.dashboardPredictionError}</p>
                <p>{error}</p>
                <p className="mt-2 text-xs opacity-80">{t.dashboardPredictorHint}</p>
              </div>
            ) : (
              <>
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-6">
                  {[
                    { label: t.dashboardTier, value: prediction ? String(prediction.predicted_tier) : "-" },
                    { label: t.dashboardCrowd, value: prediction ? `${prediction.recommended_food_packs - 50}-${prediction.recommended_food_packs + 50}` : "-" },
                    { label: t.dashboardWeather, value: weatherData ? `${weatherData.temp}┬░C` : "-", icon: true },
                    { label: t.dashboardConfidence, value: "87%", highlight: true },
                  ].map((item) => (
                    <div key={item.label} className="bg-background border border-border rounded-xl p-3.5 text-center">
                      <p className="text-[10px] font-bold uppercase tracking-wider text-text-muted mb-1.5">{item.label}</p>
                      <p className={`text-xl font-bold ${item.highlight ? "text-primary" : "text-text"} flex items-center justify-center gap-1`}>
                        {item.icon && <Cloud size={16} className="text-text-muted" />}
                        {item.value}
                      </p>
                    </div>
                  ))}
                </div>

                <div className="bg-primary-50 border border-[#D5F5E3] rounded-xl p-4 flex items-start gap-3">
                  <div className="text-gold shrink-0 mt-0.5"><Zap size={22} /></div>
                  <div>
                    <p className="font-bold text-sm text-text">{t.dashboardAiReco}</p>
                    <p className="text-sm text-text-secondary mt-0.5">
                      {prediction ? prediction.recommendation : t.dashboardLoadingReco}
                    </p>
                  </div>
                </div>
              </>
            )}
          </div>
        </div>

        {/* Historical Attendance ΓÇö FIXED: using inline pixel heights for bars */}
        <div className="card p-6">
          <div className="flex items-center justify-between mb-8">
            <div>
              <h2 className="font-bold text-lg text-text">{t.dashboardHistorical}</h2>
              <p className="text-sm text-text-muted">{t.dashboardLast7Days}</p>
            </div>
            <div className="icon-box icon-box-primary w-10 h-10"><TrendingUp size={18} /></div>
          </div>

          {/* Chart */}
          <div className="flex gap-1">
            {/* Y axis */}
            <div className="flex flex-col justify-between text-xs text-text-muted pr-3 font-medium" style={{ height: 240 }}>
              {[1200, 900, 600, 300, 0].map((v) => <span key={v}>{v}</span>)}
            </div>

            {/* Bars container */}
            <div className="flex-1 border-l border-b border-border pl-3 pb-1">
              <div className="flex items-end justify-around gap-3" style={{ height: 240 }}>
                {attendanceData.map((d) => {
                  const barHeight = Math.round((d.value / 1200) * 220);
                  return (
                    <div key={d.day} className="flex flex-col items-center flex-1 justify-end group" style={{ height: 240 }}>
                      <div className="relative w-full flex justify-center" style={{ height: 220, display: 'flex', alignItems: 'flex-end' }}>
                        {/* Tooltip */}
                        <div className="absolute left-1/2 -translate-x-1/2 bg-surface border border-border text-text shadow-md text-xs px-2 py-1 rounded-md opacity-0 group-hover:opacity-100 transition whitespace-nowrap font-medium z-10" style={{ top: 220 - barHeight - 28 }}>
                          {d.value}
                        </div>
                        <div
                          className="rounded-t-lg cursor-pointer hero-gradient transition-opacity group-hover:opacity-80"
                          style={{ width: '60%', maxWidth: 48, height: barHeight }}
                        />
                      </div>
                      <span className="text-xs text-text-muted mt-2 font-medium">{d.day}</span>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

