"use client";

import { useAuth } from "@/components/providers/AuthContext";
import { useLiveFoodEvents } from "@/hooks/useLiveFoodEvents";
import { claimKupon } from "@/lib/mutations/claims";
import { createClient } from "@/lib/supabase/client";
import { useState, useEffect } from "react";
import QRCode from "react-qr-code";
import {
  Utensils, Clock, MapPin, CheckCircle, AlertCircle, Ticket,
  Plus, X, CalendarPlus, Pencil, Trash2, AlertTriangle, Loader2,
  ChevronDown, ChevronUp,
} from "lucide-react";
import Pagination from "@/components/ui/Pagination";
import { toast } from "react-hot-toast";
import { useLanguage } from "@/components/providers/LanguageContext";

// timeout helper
function waitMs(ms: number): Promise<null> {
  return new Promise((r) => setTimeout(() => r(null), ms));
}

export default function EKuponPage() {
  const { user, isAdmin, isAnonymous, isLoading: authLoading } = useAuth();
  const { events, isLoading: eventsLoading } = useLiveFoodEvents();
  const { t } = useLanguage();
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingEvent, setEditingEvent] = useState<any | null>(null);
  const [deletingEvent, setDeletingEvent] = useState<any | null>(null);
  const [claimedIds, setClaimedIds] = useState<Set<string>>(new Set());
  const [scannedIds, setScannedIds] = useState<Set<string>>(new Set());
  const [claimMap, setClaimMap] = useState<Map<string, string>>(new Map());

  const EVENTS_PER_PAGE = 4;
  const [eventsPage, setEventsPage] = useState(1);

  // Fetch user's existing kupon claims
  const fetchMyClaims = async (userId: string) => {
    try {
      const supabase = createClient();
      // Ensure session is active before querying so RLS auth.uid() resolves correctly
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) return;

      const { data, error } = await supabase
        .from("kupon_claims")
        .select("id, event_id, is_scanned")
        .eq("guest_uuid", userId);

      if (error) {
        console.warn("fetchMyClaims error:", error.message);
        return;
      }

      if (data) {
        setClaimedIds(new Set(data.map((r: any) => r.event_id)));
        setScannedIds(new Set(data.filter((r: any) => r.is_scanned).map((r: any) => r.event_id)));
        const newMap = new Map<string, string>();
        data.forEach((r: any) => newMap.set(r.event_id, r.id));
        setClaimMap(newMap);
      }
    } catch {
      // ignore
    }
  };

  useEffect(() => {
    if (user) {
      fetchMyClaims(user.id);

      // Setup a background poll to check for scan status changes
      const scanPollInterval = setInterval(() => {
        fetchMyClaims(user.id);
      }, 5000);

      return () => clearInterval(scanPollInterval);
    }
  }, [user]);

  // For guests (no session), restore claims immediately from localStorage,
  // then sync with the DB via RPC to catch scanned status updates.
  useEffect(() => {
    if (authLoading || user) return;

    // 1. Instant restore from localStorage (survives refresh with zero network call)
    try {
      const stored = localStorage.getItem("makmur_guest_claims");
      if (stored) {
        const parsed: Record<string, string> = JSON.parse(stored); // { [eventId]: claimId }
        const entries = Object.entries(parsed);
        if (entries.length > 0) {
          setClaimedIds(new Set(entries.map(([eid]) => eid)));
          const newMap = new Map<string, string>();
          entries.forEach(([eid, cid]) => newMap.set(eid, cid));
          setClaimMap(newMap);
        }
      }
    } catch { /* ignore parse errors */ }

    // 2. Sync scan status from DB (RPC ΓÇö SECURITY DEFINER, no auth needed)
    const deviceUuid = typeof window !== "undefined"
      ? localStorage.getItem("makmur_guest_uuid")
      : null;
    if (!deviceUuid) return;

    const supabase = createClient();
    supabase.rpc("get_kupon_claims_by_device", { p_device_uuid: deviceUuid })
      .then(({ data, error }) => {
        if (error) { console.warn("get_kupon_claims_by_device:", error.message); return; }
        if (!data?.length) return;
        // Merge: DB is authoritative for scan status; localStorage is authoritative for claim IDs
        setClaimedIds(new Set(data.map((r: any) => r.event_id)));
        setScannedIds(new Set(data.filter((r: any) => r.is_scanned).map((r: any) => r.event_id)));
        const newMap = new Map<string, string>();
        data.forEach((r: any) => newMap.set(r.event_id, r.id));
        setClaimMap(newMap);
        // Keep localStorage in sync with canonical DB claim IDs
        const updated: Record<string, string> = {};
        data.forEach((r: any) => { updated[r.event_id] = r.id; });
        localStorage.setItem("makmur_guest_claims", JSON.stringify(updated));
      });
  }, [authLoading, user]);


  // Local copy of events so edits/deletes reflect instantly
  const [localEvents, setLocalEvents] = useState<any[]>([]);
  useEffect(() => {
    // Everyone sees only active/scheduled ΓÇö expired events are hidden.
    // Sort: active events first, then scheduled (by soonest date).
    const statusOrder: Record<string, number> = { active: 0, scheduled: 1 };
    const visible = events
      .filter(e => e.status !== "expired")
      .sort((a, b) => {
        const sa = statusOrder[a.status ?? "scheduled"] ?? 1;
        const sb = statusOrder[b.status ?? "scheduled"] ?? 1;
        if (sa !== sb) return sa - sb;
        return a.event_date.localeCompare(b.event_date);
      });
    setLocalEvents(visible);
    setEventsPage(1); // reset to first page when events change
  }, [events, isAdmin]);

  const isLoading = eventsLoading;

  const handleEventUpdated = (updated: any) => {
    setLocalEvents((prev) => prev.map((e) => e.id === updated.id ? { ...e, ...updated } : e));
  };

  const handleEventDeleted = (deletedId: string) => {
    setLocalEvents((prev) => prev.filter((e) => e.id !== deletedId));
  };

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8 max-w-2xl animate-pulse">
        <div className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 bg-surface-muted dark:bg-surface rounded-xl" />
            <div className="space-y-2">
              <div className="w-32 h-6 bg-surface-muted dark:bg-surface rounded-lg" />
              <div className="w-48 h-4 bg-surface-muted dark:bg-surface rounded-lg" />
            </div>
          </div>
        </div>
        <div className="card overflow-hidden">
          <div className="h-28 bg-surface-muted dark:bg-surface" />
          <div className="p-6 space-y-4">
            <div className="w-full h-8 bg-surface-alt dark:bg-surface-muted rounded" />
            <div className="w-full h-12 bg-surface-alt dark:bg-surface-muted rounded-xl mt-4" />
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-8 max-w-2xl">
      {/* Header */}
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-3">
          <div className="text-primary"><Ticket size={28} strokeWidth={2.5} /></div>
          <div>
              <h1 className="text-2xl font-bold text-text">{t.ekuponTitle}</h1>
              <p className="text-sm text-text-muted">{t.ekuponSubtitle}</p>
            </div>
          </div>
        {isAdmin && (
          <button
            onClick={() => setShowAddModal(true)}
            className="bg-primary hover:bg-primary-dark text-white px-4 py-2.5 rounded-xl font-semibold text-sm transition-all shadow-md hover:shadow-lg flex items-center gap-2"
          >
            <Plus size={16} /> <span className="hidden sm:inline">{t.addEKupon}</span>
          </button>
        )}
      </div>

      {/* Main List */}
      <div className="space-y-6">
        {localEvents.length === 0 ? (
          <div className="text-center py-10 bg-surface rounded-2xl border border-border shadow-sm">
            <Ticket size={48} className="mx-auto text-text-muted opacity-30 mb-4" />
            <h3 className="text-text font-bold text-lg">{t.noEventsTitle}</h3>
            {isAdmin && events.some(e => e.status === "expired") ? (
              <p className="text-gold text-sm mt-1 font-medium">
                {t.noEventsExpired}
              </p>
            ) : (
              <p className="text-text-secondary text-sm mt-1">{t.noEventsEmpty}</p>
            )}
          </div>
        ) : (
          <>
            {localEvents
              .slice((eventsPage - 1) * EVENTS_PER_PAGE, eventsPage * EVENTS_PER_PAGE)
              .map(event => (
                <KuponCard
                  key={event.id}
                  event={event}
                  user={user}
                  isAdmin={isAdmin}
                  isClaimed={claimedIds.has(event.id)}
                  isScanned={scannedIds.has(event.id)}
                  claimId={claimMap.get(event.id)}
                  onClaimSuccess={(newClaimId) => {
                    setClaimedIds(prev => new Set(prev).add(event.id));
                    if (newClaimId) {
                      setClaimMap(prev => new Map(prev).set(event.id, newClaimId));
                      // PERSISTENCE: ONLY save to device localStorage if the user is anonymous (Guest).
                      // Registered members (Members/Admins) ignore device storage context.
                      if (isAnonymous || !user?.email) {
                        try {
                          const stored = localStorage.getItem("makmur_guest_claims");
                          const existing: Record<string, string> = stored ? JSON.parse(stored) : {};
                          existing[event.id] = newClaimId;
                          localStorage.setItem("makmur_guest_claims", JSON.stringify(existing));
                        } catch { /* ignore */ }
                      }
                    }
                  }}
                  onDeclaimSuccess={() => {
                    setClaimedIds(prev => {
                      const newSet = new Set(prev);
                      newSet.delete(event.id);
                      return newSet;
                    });
                    setClaimMap(prev => {
                      const newMap = new Map(prev);
                      newMap.delete(event.id);
                      return newMap;
                    });
                    // Always clean up localStorage ΓÇö safe for logged-in users too
                    try {
                      const stored = localStorage.getItem("makmur_guest_claims");
                      if (stored) {
                        const existing: Record<string, string> = JSON.parse(stored);
                        delete existing[event.id];
                        localStorage.setItem("makmur_guest_claims", JSON.stringify(existing));
                      }
                    } catch { /* ignore */ }
                  }}
                  onEdit={() => setEditingEvent(event)}
                  onDelete={() => setDeletingEvent(event)}
                />
              ))}
            <Pagination
              page={eventsPage}
              total={localEvents.length}
              perPage={EVENTS_PER_PAGE}
              onChange={setEventsPage}
            />
          </>
        )}
      </div>

      {/* ΓòÉΓòÉΓòÉ Modals ΓòÉΓòÉΓòÉ */}
      {showAddModal && <EKuponFormModal mode="add" onClose={() => setShowAddModal(false)} onSave={() => { }} />}
      {editingEvent && (
        <EKuponFormModal
          mode="edit"
          event={editingEvent}
          onClose={() => setEditingEvent(null)}
          onSave={handleEventUpdated}
        />
      )}
      {deletingEvent && (
        <DeleteEKuponModal
          event={deletingEvent}
          onClose={() => setDeletingEvent(null)}
          onDelete={handleEventDeleted}
        />
      )}
    </div>
  );
}

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
/*  Kupon Card                                     */
/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
function KuponCard({
  event, user, isAdmin, isClaimed, isScanned, claimId, onClaimSuccess, onDeclaimSuccess, onEdit, onDelete,
}: {
  event: any;
  user: any;
  isAdmin: boolean;
  isClaimed: boolean;
  isScanned: boolean;
  claimId?: string;
  onClaimSuccess: (id?: string) => void;
  onDeclaimSuccess: () => void;
  onEdit: () => void;
  onDelete: () => void;
}) {
  const [claimError, setClaimError] = useState<string | null>(null);
  const [isClaiming, setIsClaiming] = useState(false);
  const [isDeclaiming, setIsDeclaiming] = useState(false);
  const [localRemaining, setLocalRemaining] = useState<number | null>(null);
  const [confirmDeclaim, setConfirmDeclaim] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const { t } = useLanguage();

  const totalPacks = event.total_capacity;
  const remainingPacks = localRemaining ?? event.remaining_capacity;
  const percentageLeft = (remainingPacks / totalPacks) * 100;
  const isScheduled = event.status === "scheduled";
  const isExpired = event.status === "expired";
  const isActive = !isScheduled && !isExpired;

  useEffect(() => {
    if (event.remaining_capacity != null && localRemaining === null) {
      setLocalRemaining(event.remaining_capacity);
    }
  }, [event.remaining_capacity, localRemaining]);

  const handleClaim = async () => {
    if (isExpired) return;
    setIsClaiming(true);
    setClaimError(null);

    const deviceUuid = (typeof window !== "undefined"
      ? localStorage.getItem("makmur_guest_uuid")
      : null) ?? undefined;

    // If not logged in, silently sign in as anonymous (no popup, instant)
    let claimUserId = user?.id;
    if (!claimUserId) {
      try {
        const { createClient: mkClient } = await import("@/lib/supabase/client");
        const { data, error } = await mkClient().auth.signInAnonymously();
        if (error || !data.user) {
          setClaimError("Unable to process claim. Please try again.");
          setIsClaiming(false);
          return;
        }
        claimUserId = data.user.id;
      } catch {
        setClaimError("Unable to process claim. Please try again.");
        setIsClaiming(false);
        return;
      }
    }

    const result = await claimKupon(event.id, claimUserId, deviceUuid);
    if (result.success) {
      onClaimSuccess(result.claimId);
      setLocalRemaining((prev) => Math.max(0, (prev ?? event.remaining_capacity) - 1));
      toast.success(t.claimedTitle);
    } else {
      // Treat duplicate constraint as success ΓÇö already claimed on this device.
      // Recover the existing claimId from the SECURITY DEFINER RPC so the QR shows.
      if (result.error?.includes("already been claimed")) {
        let recoveredId: string | undefined;
        if (deviceUuid) {
          try {
            const { createClient: mkClient2 } = await import("@/lib/supabase/client");
            const { data: existing } = await mkClient2().rpc("get_kupon_claims_by_device", { p_device_uuid: deviceUuid });
            recoveredId = existing?.find((r: any) => r.event_id === event.id)?.id;
          } catch { /* ignore */ }
        }
        onClaimSuccess(recoveredId);
      } else {
        setClaimError(result.error ?? "Failed to claim kupon.");
        toast.error(result.error ?? "Failed to claim kupon.");
      }
    }
    setIsClaiming(false);
  };

  const handleDeclaim = async () => {
    if (!claimId) {
      setClaimError("Missing Kupon ID.");
      return;
    }

    setIsDeclaiming(true);
    setConfirmDeclaim(false);
    setClaimError(null);

    // In claim.ts we have cancelKupon
    const { cancelKupon } = await import("@/lib/mutations/claims");
    const result = await cancelKupon(claimId);

    if (result.success) {
      onDeclaimSuccess();
      setLocalRemaining((prev) => Math.min(totalPacks, (prev ?? event.remaining_capacity) + 1));
      toast.success(t.cancelGigSuccess);
    } else {
      setClaimError(result.error ?? t.cancelGigFail);
      toast.error(result.error ?? t.cancelGigFail);
    }
    setIsDeclaiming(false);
  };

  return (
    <div className={`card overflow-hidden transition-shadow ${
      isScheduled
        ? "card-scheduled ring-1 ring-gold/35 dark:ring-gold/20 shadow-md shadow-gold/10 dark:shadow-gold/5"
        : isActive
          ? "ring-1 ring-primary/20 dark:ring-primary/30 shadow-md shadow-primary/10 dark:shadow-primary/20"
          : ""
    }`}>
      <div
        className={`p-6 text-white relative overflow-hidden ${
          isExpired
            ? "bg-gradient-to-br from-gray-600/90 to-gray-800 dark:from-gray-700 dark:to-gray-900"
            : isActive
              ? "hero-gradient"
              : "bg-gradient-to-br from-amber-500 to-amber-600"
        }`}
        style={event.background_image && !isExpired ? {
          backgroundImage: isActive
            ? `linear-gradient(to bottom, rgba(0,0,0,0.55) 0%, rgba(0,0,0,0.25) 100%), url(${event.background_image})`
            : `linear-gradient(to bottom, rgba(0,0,0,0.35) 0%, rgba(0,0,0,0.65) 100%), url(${event.background_image})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
          backgroundColor: isActive ? "#059669" : "#d97706",
        } : undefined}
      >
        <div className="pattern-bg absolute inset-0 opacity-20" />
        <div className="absolute top-0 right-0 w-40 h-40 bg-surface/5 rounded-full -mt-20 -mr-20 blur-2xl" />

        <div className="flex items-start justify-between relative z-10 mb-4">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <Utensils size={20} />
            {event.name}
          </h2>
          <div className="flex items-center gap-2">
            <span className={`badge text-[10px] ${
              isExpired
                ? "bg-white/10 text-white/50 border border-white/10"
                : isScheduled
                  ? "bg-black/20 text-white border border-white/20 backdrop-blur-sm"
                  : "bg-white/20 text-white font-semibold backdrop-blur-sm border border-white/10"
            }`}>
            {isExpired ? "EXPIRED" : isScheduled ? t.statusScheduled : t.statusActive}
            </span>

            {/* ΓöÇΓöÇ ADMIN: Edit & Delete ΓöÇΓöÇ */}
            {isAdmin && (
              <>
                <button
                  onClick={onEdit}
                  title="Edit event"
                  className="w-8 h-8 rounded-lg bg-surface/15 hover:bg-surface/30 flex items-center justify-center text-white transition-all"
                >
                  <Pencil size={14} />
                </button>
                <button
                  onClick={onDelete}
                  title="Delete event"
                  className="w-8 h-8 rounded-lg bg-surface/15 hover:bg-red-400/60 flex items-center justify-center text-white transition-all"
                >
                  <Trash2 size={14} />
                </button>
              </>
            )}
          </div>
        </div>

        <div className="space-y-2 relative z-10 text-white/80">
          <div className="flex items-center gap-2 text-sm"><Clock size={14} /> {new Date(event.event_date).toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' })} ({event.start_time?.slice(0, 5)} - {event.end_time?.slice(0, 5)})</div>
          <div className="flex items-center gap-2 text-sm"><MapPin size={14} /> {event.location || "Primary Distribution Center"}</div>
        </div>
      </div>

      <div className="p-6">
        {/* Availability + conditional progress bar */}
        <div className="mb-6">
          <div className="flex justify-between items-center text-sm mb-2">
            <span className="text-text-secondary font-medium">{t.availability}</span>
            <span className="flex items-center gap-1.5">
              {isScheduled ? (
                <span className="w-2 h-2 rounded-full bg-amber-500 dark:bg-gold" />
              ) : (
                <span className="w-2 h-2 rounded-full bg-primary animate-live" />
              )}
              <span className={`font-bold ${
                isScheduled
                  ? "text-amber-600 dark:text-amber-400"
                  : "text-primary-dark dark:text-primary-light"
              }`}>
                {remainingPacks}/{totalPacks} {t.remaining}
              </span>
            </span>
          </div>
          {/* Only show progress bar for active events */}
          {isActive && (
            <div className="progress-bar">
              <div className="progress-fill" style={{ width: `${percentageLeft}%` }} />
            </div>
          )}
        </div>

        {claimError && (
          <div className="bg-gold-light/30 dark:bg-surface-muted border border-gold/30 text-gold-dark dark:text-gold px-4 py-3 rounded-xl mb-4 flex items-center gap-2 text-sm">
            <AlertCircle size={16} /> {claimError}
          </div>
        )}

        {!isClaimed ? (
          <button
            onClick={handleClaim}
            disabled={isClaiming || remainingPacks <= 0 || isExpired}
            className={`w-full py-4 text-base flex items-center justify-center gap-2 rounded-xl font-bold transition-all shadow-md ${
              isExpired
                ? "bg-surface-muted dark:bg-surface text-text-muted cursor-not-allowed border border-border shadow-none"
                : isScheduled
                  ? "bg-gradient-to-br from-amber-500 to-amber-600 hover:from-amber-600 hover:to-amber-700 text-white shadow-amber-500/25"
                  : "bg-gradient-to-br from-primary-light to-primary hover:from-primary hover:to-primary-dark text-white hover:shadow-lg shadow-primary/20 dark:shadow-primary/30"
            }`}
          >
            {isExpired ? <Clock size={20} /> : isScheduled ? <CalendarPlus size={20} /> : <Utensils size={20} />}
            {isExpired
              ? t.eventEnded
              : isScheduled
                ? isClaiming ? t.reserving : t.reserveSpot
                : isClaiming ? t.claiming : t.claimNow}
          </button>
        ) : isScanned ? (
          /* ΓöÇΓöÇ REDEEMED STATE ΓöÇΓöÇ */
          <div className="rounded-2xl p-5 bg-primary-50/40 dark:bg-primary/10 border-2 border-primary/20 dark:border-primary/30">
            <div className="flex items-center justify-center gap-2 cursor-pointer" onClick={() => setIsExpanded(!isExpanded)}>
              <span className="text-[10px] font-bold uppercase tracking-widest text-primary-dark dark:text-primary-light bg-transparent border border-primary/20 px-3 py-1 rounded-full flex items-center gap-1.5">
                <CheckCircle size={14} /> {t.redeemedTitle}
              </span>
              <button className="text-primary p-1 rounded-full transition-colors">
                {isExpanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
              </button>
            </div>
            <div className={`grid transition-all duration-300 ease-in-out ${isExpanded ? "grid-rows-[1fr] opacity-100 mt-4 border-t border-primary/10" : "grid-rows-[0fr] opacity-0"}`}>
              <div className="overflow-hidden">
                <div className="pt-4 flex flex-col items-center gap-2">
                  <p className="text-sm text-text-secondary text-center">
                    {t.redeemedMsg(event.name)}
                  </p>
                </div>
              </div>
            </div>
          </div>
        ) : isScheduled ? (
          /* ΓöÇΓöÇ RESERVED (claimed but event not active yet) ΓöÇΓöÇ */
          <div className="rounded-2xl border-2 border-dashed border-amber-300 dark:border-amber-700/50 p-5 bg-transparent">
            <div className="flex items-center justify-center gap-2 cursor-pointer mb-2" onClick={() => setIsExpanded(!isExpanded)}>
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#4a3b32] dark:text-amber-400 bg-transparent dark:bg-amber-900/10 border border-amber-200 dark:border-amber-800/50 px-3 py-1 rounded-full">{t.reservedTitle}</span>
              <button className="text-[#4a3b32] dark:text-amber-400 p-1 rounded-full transition-colors">
                {isExpanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
              </button>
            </div>
            
            <div className={`grid transition-all duration-300 ease-in-out ${isExpanded ? "grid-rows-[1fr] opacity-100 mt-4 border-t border-border" : "grid-rows-[0fr] opacity-0"}`}>
              <div className="overflow-hidden">
                <div className="pt-4">
                  {/* Body */}
                  <div className="text-center">
                    <p className="text-sm font-medium text-amber-600 dark:text-amber-400 leading-relaxed">
                      {t.reservedMsg(
                        new Date(event.event_date).toLocaleDateString('en-MY', { weekday: 'long', day: 'numeric', month: 'long' }),
                        event.start_time?.slice(0, 5)
                      )}
                    </p>
                    <p className="font-mono text-xs font-semibold text-text-secondary mt-3 bg-surface rounded-lg px-3 py-1.5 inline-block border border-border">ID: {claimId ? claimId.split("-")[0] : "..."}</p>
                  </div>
                  {/* Cancel Actions */}
                  <div className="mt-5 border-t border-border pt-4 flex justify-center">
                    {confirmDeclaim ? (
                      <div className="flex flex-col items-center gap-3 w-full">
                        <p className="text-xs text-text-secondary text-center">{t.cancelConfirmMsg}</p>
                        <div className="flex gap-2">
                          <button
                            onClick={() => setConfirmDeclaim(false)}
                            className="text-xs font-semibold text-text-secondary border border-border bg-surface hover:bg-surface-muted rounded-lg px-4 py-2 transition-all"
                          >
                            {t.keep}
                          </button>
                          <button
                            onClick={handleDeclaim}
                            disabled={isDeclaiming}
                            className="text-xs font-semibold text-white bg-red-500 hover:bg-red-600 rounded-lg px-4 py-2 transition-all"
                          >
                            {isDeclaiming ? t.canceling : t.yesCancel}
                          </button>
                        </div>
                      </div>
                    ) : (
                      <button
                        onClick={() => setConfirmDeclaim(true)}
                        disabled={isDeclaiming}
                        className="text-xs font-bold text-red-600 hover:text-red-700 border border-red-200 hover:border-red-300 bg-white hover:bg-red-50 dark:bg-surface dark:border-red-900/50 dark:text-red-400 dark:hover:bg-red-950/40 rounded-lg px-4 py-2.5 transition-all shadow-sm flex items-center gap-1.5"
                      >
                        <X size={13} />{t.cancelClaim}
                      </button>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="border-2 border-dashed border-primary/20 dark:border-primary/30 rounded-2xl p-5 bg-primary-50/30 dark:bg-primary/5">
            <div className="flex items-center justify-center gap-2 cursor-pointer" onClick={() => setIsExpanded(!isExpanded)}>
              <span className="text-[10px] font-bold uppercase tracking-widest text-primary-dark dark:text-primary-light bg-transparent border border-primary/20 px-3 py-1 rounded-full flex items-center gap-1.5">
                <CheckCircle size={14} /> {t.claimedTitle}
              </span>
              <button className="text-primary p-1 rounded-full transition-colors">
                {isExpanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
              </button>
            </div>
            
            <div className={`grid transition-all duration-300 ease-in-out ${isExpanded ? "grid-rows-[1fr] opacity-100 mt-4 border-t border-primary/10" : "grid-rows-[0fr] opacity-0"}`}>
              <div className="overflow-hidden">
                <div className="pt-5">
                  <div className="bg-surface dark:bg-white p-5 rounded-xl shadow-sm mx-auto w-fit">
                    <QRCode value={`makmur-kupon:${claimId ?? ""}`} size={180} level="H" fgColor="#1B6B4A" />
                  </div>
                  <p className="text-sm text-text-secondary mt-5 text-center">{t.showQrMsg}</p>
                  <p className="font-mono text-xs text-text-muted text-center mt-1">ID: {claimId ? claimId.split("-")[0] : "..."}</p>
                  <div className="mt-4 border-t border-border pt-4 flex justify-center">
                    {confirmDeclaim ? (
                      <div className="flex flex-col items-center gap-3 w-full">
                        <p className="text-xs text-text-secondary text-center">{t.cancelConfirmMsg}</p>
                        <div className="flex gap-2">
                          <button
                            onClick={() => setConfirmDeclaim(false)}
                            className="text-xs font-semibold text-text-secondary border border-border bg-surface hover:bg-surface-muted rounded-lg px-4 py-2 transition-all"
                          >
                            {t.keep}
                          </button>
                          <button
                            onClick={handleDeclaim}
                            disabled={isDeclaiming}
                            className="text-xs font-semibold text-white bg-red-500 hover:bg-red-600 rounded-lg px-4 py-2 transition-all"
                          >
                            {isDeclaiming ? t.canceling : t.yesCancel}
                          </button>
                        </div>
                      </div>
                    ) : (
                      <button
                        onClick={() => setConfirmDeclaim(true)}
                        disabled={isDeclaiming}
                        className="text-xs font-bold text-red-600 hover:text-red-700 border border-red-200 hover:border-red-300 bg-white hover:bg-red-50 dark:bg-surface dark:border-red-900/50 dark:text-red-400 dark:hover:bg-red-950/40 rounded-lg px-4 py-2.5 transition-all shadow-sm flex items-center gap-1.5"
                      >
                        <X size={13} />{t.cancelClaim}
                      </button>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
/*  Add / Edit E-Kupon Modal                       */
/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
function EKuponFormModal({
  mode, event, onClose, onSave,
}: {
  mode: "add" | "edit";
  event?: any;
  onClose: () => void;
  onSave: (data: any) => void;
}) {
  const isEdit = mode === "edit";
  const [name, setName] = useState(event?.name ?? "");
  const [capacity, setCapacity] = useState(String(event?.total_capacity ?? 500));
  const [location, setLocation] = useState(event?.location ?? "Primary Distribution Center");
  const [date, setDate] = useState(event?.event_date ?? new Date().toISOString().split("T")[0]);
  const [startTime, setStartTime] = useState(event?.start_time?.slice(0, 5) ?? "17:00");
  const [endTime, setEndTime] = useState(event?.end_time?.slice(0, 5) ?? "19:00");
  const [backgroundImage, setBackgroundImage] = useState<string>(event?.background_image ?? "");
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string>(event?.background_image ?? "");
  const [isUploading, setIsUploading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [success, setSuccess] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);

  // Clean up object URLs to prevent memory leaks
  useEffect(() => {
    return () => {
      if (imagePreview && imagePreview.startsWith("blob:")) {
        URL.revokeObjectURL(imagePreview);
      }
    };
  }, [imagePreview]);

  const handleImagePick = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (imagePreview.startsWith("blob:")) URL.revokeObjectURL(imagePreview);
    const objectUrl = URL.createObjectURL(file);
    setImageFile(file);
    setImagePreview(objectUrl);
    setBackgroundImage(""); // will be replaced by upload URL on save
  };

  const handleRemoveImage = () => {
    if (imagePreview.startsWith("blob:")) URL.revokeObjectURL(imagePreview);
    setImageFile(null);
    setImagePreview("");
    setBackgroundImage("");
  };
  const { t } = useLanguage();

  const handleSave = async () => {
    if (!name.trim() || !date) return;

    // Date validation: prevent backdating
    const today = new Date().toISOString().split('T')[0];
    if (date < today) {
      toast.error("Event date cannot be in the past.");
      return;
    }

    // Validation: End must be after start
    const startDateTime = new Date(`${date}T${startTime}`);
    const endDateTime = new Date(`${date}T${endTime}`);
    if (endDateTime <= startDateTime) {
      toast.error("End time must be strictly after start time");
      return;
    }

    setSaving(true);
    setSaveError(null);
    const supabase = createClient();

    try {
      // ΓöÇΓöÇ Upload image if a new file was picked ΓöÇΓöÇ
      let finalBgImage: string | null = backgroundImage.trim() || null;
      if (imageFile) {
        setIsUploading(true);
        const fileExt = imageFile.name.split(".").pop();
        const fileName = `food-events/${Date.now()}-${crypto.randomUUID()}.${fileExt}`;
        const { data: uploadData, error: uploadError } = await supabase
          .storage
          .from("campaigns")
          .upload(fileName, imageFile);
        setIsUploading(false);
        if (uploadError) {
          console.warn("Image upload error:", uploadError.message);
          // proceed without image rather than blocking the save
        } else if (uploadData) {
          const { data: { publicUrl } } = supabase.storage.from("campaigns").getPublicUrl(fileName);
          finalBgImage = publicUrl;
        }
      }

      if (isEdit && event) {
        // ΓöÇΓöÇ UPDATE ΓöÇΓöÇ
        const result = await Promise.race([
          supabase
            .from("food_events")
            .update({
              name: name.trim(),
              location: location.trim(),
              total_capacity: parseInt(capacity) || 500,
              event_date: date,
              start_time: startTime + ":00",
              end_time: endTime + ":00",
              background_image: finalBgImage,
            })
            .eq("id", event.id),
          waitMs(6000),
        ]);
        if (result && "error" in result && result.error) {
          console.warn("Update error:", result.error.message);
        }
        onSave({ ...event, name: name.trim(), location: location.trim(), total_capacity: parseInt(capacity) || 500, event_date: date, start_time: startTime + ":00", end_time: endTime + ":00", background_image: finalBgImage });

      } else {
        // ΓöÇΓöÇ INSERT ΓöÇΓöÇ
        const result = await Promise.race([
          supabase
            .from("food_events")
            .insert({
              name: name.trim(),
              location: location.trim(),
              total_capacity: parseInt(capacity) || 500,
              remaining_capacity: parseInt(capacity) || 500,
              event_date: date,
              start_time: startTime + ":00",
              end_time: endTime + ":00",
              background_image: finalBgImage,
            })
            .select("id")
            .single(),
          waitMs(6000),
        ]);
        if (result && "error" in result && result.error) {
          console.warn("Insert error:", result.error.message);
        } else {
          // ΓöÇΓöÇ Native Push Notification for New Kupon ΓöÇΓöÇ
          try {
            const { data: profiles } = await supabase
              .from("profiles")
              .select("fcm_tokens")
              .not("fcm_tokens", "is", null);

            if (profiles) {
              const allTokens = profiles.flatMap(p => p.fcm_tokens || []).filter(Boolean);
              if (allTokens.length > 0) {
                await fetch("/api/notifications/push", {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({
                    tokens: allTokens,
                    title: "New Food Coupon Available!",
                    body: `Grab your spot for "${name.trim()}" at ${location.trim()}.`,
                    data: { url: "/e-kupon" }
                  }),
                });
              }
            }
          } catch (pushErr) {
            console.error("Kupon push failed:", pushErr);
          }
        }
        onSave({});
      }

      setSuccess(true);
      setTimeout(() => onClose(), 1400);
      toast.success(isEdit ? t.eventUpdated : t.ekuponCreated);
    } catch (err: any) {
      setSaveError(err?.message ?? "Unexpected error.");
      toast.error(err?.message ?? "Unexpected error."); // Added toast
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-surface rounded-2xl w-full max-w-md shadow-2xl relative" onClick={(e) => e.stopPropagation()}>
        <button onClick={onClose} className="absolute top-4 right-4 z-20 text-white/50 hover:text-white transition bg-black/20 rounded-full p-1">
          <X size={20} />
        </button>

        {/* Header */}
        <div className="hero-gradient p-5 text-white overflow-hidden rounded-t-2xl relative">
          <div className="absolute top-0 right-0 w-32 h-32 bg-surface/5 rounded-full -mt-16 -mr-16 blur-2xl" />
          <div className="flex items-center gap-3 relative z-10">
            {isEdit ? <Pencil size={20} /> : <CalendarPlus size={22} />}
            <div>
              <h2 className="text-lg font-bold">{isEdit ? t.modalEditTitle : t.modalAddTitle}</h2>
              <p className="text-white/60 text-xs mt-0.5">
                {isEdit ? t.modalEditSubtitle : t.modalAddSubtitle}
              </p>
            </div>
          </div>
        </div>

        {/* Body */}
        <div className="p-6 space-y-4">
          {success ? (
            <div className="text-center py-8">
              <CheckCircle size={52} className="text-primary mx-auto mb-3" />
              <p className="font-bold text-text text-lg">{isEdit ? t.eventUpdated : t.ekuponCreated}</p>
              <p className="text-sm text-text-muted mt-1">{isEdit ? t.changesSaved : t.usersCanClaim}</p>
            </div>
          ) : (
            <>
              {saveError && (
                <div className="bg-red-50 border border-red-200 text-red-600 px-4 py-3 rounded-xl text-sm flex items-center gap-2">
                  <AlertCircle size={15} /> {saveError}
                </div>
              )}

              <div>
                <label className="text-xs font-semibold text-text-secondary uppercase tracking-wider mb-1.5 block">{t.fieldFoodName}</label>
                <input
                  type="text" placeholder="e.g., Nasi Briyani Kambing" value={name} onChange={(e) => setName(e.target.value)}
                  className="w-full px-3.5 py-2.5 border border-border rounded-xl text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none bg-background"
                />
              </div>

              <div>
                <label className="text-xs font-semibold text-text-secondary uppercase tracking-wider mb-1.5 block">{t.fieldLocation}</label>
                <input
                  type="text" placeholder="e.g., Primary Distribution Center" value={location} onChange={(e) => setLocation(e.target.value)}
                  className="w-full px-3.5 py-2.5 border border-border rounded-xl text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none bg-background"
                />
              </div>

              <div>
                <label className="text-xs font-semibold text-text-secondary uppercase tracking-wider mb-1.5 block">
                  Card Background Image
                  <span className="text-text-muted font-normal normal-case tracking-normal ml-1">(optional)</span>
                </label>
                {imagePreview ? (
                  /* Preview with remove button */
                  <div className="relative rounded-xl overflow-hidden h-28 border border-border group">
                    <img
                      src={imagePreview}
                      alt="background preview"
                      className="w-full h-full object-cover"
                    />
                    {/* auto gradient preview overlay */}
                    <div className="absolute inset-0 bg-gradient-to-b from-black/40 via-transparent to-black/50 pointer-events-none" />
                    <button
                      type="button"
                      onClick={handleRemoveImage}
                      className="absolute top-2 right-2 w-7 h-7 bg-black/60 hover:bg-red-500 text-white rounded-full flex items-center justify-center transition-all"
                    >
                      <X size={13} />
                    </button>
                    <span className="absolute bottom-2 left-2 text-[10px] font-bold text-white/80 bg-black/40 px-2 py-0.5 rounded-full">
                      {imageFile ? imageFile.name : "Current image"}
                    </span>
                  </div>
                ) : (
                  /* Upload drop zone */
                  <label className="flex flex-col items-center justify-center gap-2 h-20 border-2 border-dashed border-border hover:border-gold rounded-xl cursor-pointer bg-surface-muted/40 hover:bg-gold/5 transition-all">
                    <input
                      type="file"
                      accept="image/*"
                      className="hidden"
                      onChange={handleImagePick}
                    />
                    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-text-muted"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
                    <span className="text-xs text-text-muted">Click to upload image</span>
                  </label>
                )}
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-semibold text-text-secondary uppercase tracking-wider mb-1.5 block">{t.fieldCapacity}</label>
                  <input
                    type="number" placeholder="500" value={capacity} onChange={(e) => setCapacity(e.target.value)} min="1"
                    className="w-full px-3.5 py-2.5 border border-border rounded-xl text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none bg-background"
                  />
                </div>
                <div>
                  <label className="text-xs font-semibold text-text-secondary uppercase tracking-wider mb-1.5 block">{t.fieldDate}</label>
                  <input
                    type="date" value={date} onChange={(e) => setDate(e.target.value)}
                    min={new Date().toISOString().split('T')[0]}
                    className="w-full px-3.5 py-2.5 border border-border rounded-xl text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none bg-background"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-semibold text-text-secondary uppercase tracking-wider mb-1.5 block">{t.fieldStartTime}</label>
                  <input
                    type="time" value={startTime} onChange={(e) => setStartTime(e.target.value)}
                    className="w-full px-3.5 py-2.5 border border-border rounded-xl text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none bg-background"
                  />
                </div>
                <div>
                  <label className="text-xs font-semibold text-text-secondary uppercase tracking-wider mb-1.5 block">{t.fieldEndTime}</label>
                  <input
                    type="time" value={endTime} onChange={(e) => setEndTime(e.target.value)}
                    className="w-full px-3.5 py-2.5 border border-border rounded-xl text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none bg-background"
                  />
                </div>
              </div>

              <button
                onClick={handleSave}
                disabled={saving || isUploading || !name.trim() || !date}
                className="w-full py-3.5 btn-primary text-sm mt-2 flex items-center justify-center gap-2"
              >
                {(saving || isUploading) && <Loader2 size={15} className="animate-spin" />}
                {isUploading ? "Uploading imageΓÇª" : saving ? (isEdit ? "SavingΓÇª" : "CreatingΓÇª") : (isEdit ? "Save Changes" : "Create E-Kupon Event")}
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
/*  Delete Confirmation Modal                      */
/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
function DeleteEKuponModal({
  event, onClose, onDelete,
}: {
  event: any;
  onClose: () => void;
  onDelete: (id: string) => void;
}) {
  const [deleting, setDeleting] = useState(false);
  const { t } = useLanguage();

  const handleDelete = async () => {
    setDeleting(true);
    const supabase = createClient();
    await Promise.race([
      supabase.from("food_events").delete().eq("id", event.id),
      waitMs(5000),
    ]);
    onDelete(event.id);
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-surface rounded-2xl w-full max-w-sm overflow-hidden" onClick={(e) => e.stopPropagation()}>

        <div className="bg-red-50 dark:bg-red-950/60 border-b border-red-100 dark:border-red-900/50 p-5 flex items-center justify-between">
          <div className="flex gap-3 items-center">
            <AlertTriangle className="text-red-500 dark:text-red-400" />
            <div>
          <h2 className="font-bold text-red-900 dark:text-red-200">{t.deleteEKuponTitle}</h2>
            </div>
          </div>
          <button onClick={onClose} className="text-red-500 hover:text-red-700 dark:text-red-400 dark:hover:text-red-300 bg-red-100 dark:bg-red-900/40 p-1 rounded-md"><X size={18} /></button>
        </div>

        <div className="p-6">
          <p className="text-sm text-text-secondary mb-1">{t.deleteConfirmPrefix}</p>
          <p className="font-bold text-text bg-background border border-border rounded-xl px-4 py-3 text-sm mb-5">
            &ldquo;{event.name}&rdquo;
          </p>
          <div className="flex gap-3">
            <button onClick={onClose} className="flex-1 py-3 btn-outline text-sm font-bold rounded-xl">
              {t.cancel}
            </button>
            <button
              onClick={handleDelete}
              disabled={deleting}
              className="flex-1 py-3 bg-red-500 hover:bg-red-600 dark:bg-red-600 dark:hover:bg-red-500 text-white font-bold rounded-xl text-sm transition-all flex items-center justify-center gap-2 disabled:opacity-50 shadow-md shadow-red-500/20"
            >
              {deleting ? <Loader2 size={15} className="animate-spin" /> : <Trash2 size={15} />}
              {deleting ? t.deleting : t.deleteEvent}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useAuth } from "@/components/providers/AuthContext";
import { useLanguage } from "@/components/providers/LanguageContext";
import { createClient } from "@/lib/supabase/client";
import React, { useEffect, useState, useCallback } from "react";
import {
  Building2, Plus, X, Loader2, AlertTriangle, LogIn,
  Calendar, Clock, Users, MapPin, CheckCircle2,
  XCircle, Trash2, Pencil, ChevronDown, QrCode,
} from "lucide-react";
import Pagination from "@/components/ui/Pagination";
import { toast } from "react-hot-toast";
import type { Facility, FacilityBooking, BookingStatus } from "@/types/database";

/* ΓöÇΓöÇ Helpers ΓöÇΓöÇ */
function statusColor(s: BookingStatus) {
  switch (s) {
    case "pending":   return "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400";
    case "approved":  return "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400";
    case "rejected":  return "bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400";
    case "cancelled": return "bg-gray-100 text-gray-500 dark:bg-gray-800 dark:text-gray-400";
  }
}

function statusLabel(s: BookingStatus, t: any) {
  const map: Record<BookingStatus, string> = {
    pending: t.fbStatusPending,
    approved: t.fbStatusApproved,
    rejected: t.fbStatusRejected,
    cancelled: t.fbStatusCancelled,
  };
  return map[s] ?? s;
}

function formatDate(d: string, lang: string) {
  return new Date(d).toLocaleDateString(lang === "ms" ? "ms-MY" : "en-MY", {
    weekday: "short", day: "numeric", month: "short", year: "numeric",
  });
}

function formatTime(t: string) {
  return t.slice(0, 5); // HH:MM
}

/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */
/*  Main Page                                                  */
/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */
export default function FacilityBookingPage() {
  const { user, isAnonymous, isAdmin, setShowLoginModal } = useAuth();
  const { t, language } = useLanguage();

  const [facilities, setFacilities] = useState<Facility[]>([]);
  const [bookings, setBookings] = useState<FacilityBooking[]>([]);
  const [loading, setLoading] = useState(true);
  const [fetchError, setFetchError] = useState<string | null>(null);

  // Tabs
  const [tab, setTab] = useState<"facilities" | "myBookings" | "allBookings">("facilities");

  // Modals
  const [showBookModal, setShowBookModal] = useState(false);
  const [selectedFacility, setSelectedFacility] = useState<Facility | null>(null);
  const [showFacilityModal, setShowFacilityModal] = useState(false);
  const [editingFacility, setEditingFacility] = useState<Facility | null>(null);
  const [deletingFacility, setDeletingFacility] = useState<Facility | null>(null);

  // QR expand state ΓÇö stores the booking id whose QR is currently shown
  const [expandedQR, setExpandedQR] = useState<string | null>(null);

  // Pagination
  const PER_PAGE = 6;
  const [page, setPage] = useState(1);

  /* ΓöÇΓöÇ Fetch ΓöÇΓöÇ */
  const fetchAll = useCallback(async () => {
    try {
      const supabase = createClient();
      const since90 = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000)
        .toISOString()
        .split("T")[0];
      const [facRes, bookRes] = await Promise.all([
        supabase.from("facilities").select("*").eq("is_active", true).order("name"),
        user && !isAnonymous
          ? isAdmin
            ? supabase
                .from("facility_bookings")
                .select("*, facilities:facility_id(name), profiles:booked_by(display_name)")
                // Admin: last 90 days OR still-pending (could be older)
                .or(`booking_date.gte.${since90},status.eq.pending`)
                .order("booking_date", { ascending: false })
            : supabase
                .from("facility_bookings")
                .select("*, facilities:facility_id(name)")
                .eq("booked_by", user.id)
                // User: last 90 days OR approved (future bookings always visible)
                .or(`booking_date.gte.${since90},status.eq.approved`)
                .order("booking_date", { ascending: false })
          : Promise.resolve({ data: [], error: null }),
      ]);

      if (facRes.error) { setFetchError(facRes.error.message); return; }
      setFacilities((facRes.data as Facility[]) ?? []);
      setBookings((bookRes.data as FacilityBooking[]) ?? []);
      setFetchError(null);
    } catch {
      setFetchError("Unexpected error");
    } finally {
      setLoading(false);
    }
  }, [user, isAnonymous, isAdmin]);

  useEffect(() => {
    fetchAll();
    const supabase = createClient();
    const channel = supabase
      .channel("facility-booking-rt")
      .on("postgres_changes", { event: "*", schema: "public", table: "facility_bookings" }, () => fetchAll())
      .on("postgres_changes", { event: "*", schema: "public", table: "facilities" }, () => fetchAll())
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [fetchAll]);

  /* ΓöÇΓöÇ Booking status actions ΓöÇΓöÇ */
  const handleBookingAction = async (id: string, newStatus: BookingStatus, note?: string) => {
    const supabase = createClient();
    const payload: Record<string, unknown> = { status: newStatus, updated_at: new Date().toISOString() };
    if (note !== undefined) payload.admin_note = note;
    const { error } = await supabase.from("facility_bookings").update(payload).eq("id", id);
    if (error) { toast.error(error.message); return; }

    // ΓöÇΓöÇ Persist notification and send native push ΓöÇΓöÇ
    if (newStatus === "approved" || newStatus === "rejected" || (newStatus === "cancelled" && isAdmin)) {
      const booking = bookings.find((b) => b.id === id);
      if (booking && booking.booked_by !== user?.id) {
        const notifType =
          newStatus === "approved" ? "booking_approved" :
          newStatus === "cancelled" ? "booking_cancelled" :
          "booking_rejected";
        
        // 1. In-app notification
        await supabase.from("notifications").insert({
          user_id: booking.booked_by,
          type: notifType,
          payload: {
            booking_id: id,
            facility_name: booking.facilities?.name ?? "facility",
          },
        });

        // 2. Native Push Notification
        try {
          // Fetch user's tokens
          const { data: profile } = await supabase
            .from("profiles")
            .select("fcm_tokens")
            .eq("id", booking.booked_by)
            .single();

          if (profile?.fcm_tokens && profile.fcm_tokens.length > 0) {
            const title = 
              newStatus === "approved" ? "Booking Approved!" :
              newStatus === "cancelled" ? "Booking Cancelled" :
              "Booking Rejected";
            
            const body = newStatus === "approved" 
              ? `Your booking for ${booking.facilities?.name} has been approved.`
              : `There's an update regarding your booking for ${booking.facilities?.name}.`;

            await fetch("/api/notifications/push", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                tokens: profile.fcm_tokens,
                title,
                body,
                data: {
                  url: "/my-bookings",
                  bookingId: id
                }
              }),
            });
          }
        } catch (pushErr) {
          console.error("Push notification failed:", pushErr);
        }
      }
    }

    toast.success(t.fbUpdated);
    fetchAll();
  };

  /* ΓöÇΓöÇ Delete facility (admin) ΓöÇΓöÇ */
  const handleDeleteFacility = async (id: string) => {
    const supabase = createClient();
    const { error } = await supabase.from("facilities").delete().eq("id", id);
    if (error) { toast.error(error.message); return; }
    toast.success(t.fbFacilityDeleted);
    setDeletingFacility(null);
    fetchAll();
  };

  /* ΓöÇΓöÇ Filtered bookings ΓöÇΓöÇ */
  const displayBookings = tab === "myBookings"
    ? bookings.filter((b) => b.booked_by === user?.id)
    : bookings;

  const paginatedFacilities = facilities.slice((page - 1) * PER_PAGE, page * PER_PAGE);
  const paginatedBookings = displayBookings.slice((page - 1) * PER_PAGE, page * PER_PAGE);

  return (
    <div className="container mx-auto px-4 py-8 max-w-2xl">
      {/* Header */}
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-3">
          <div className="text-primary"><Building2 size={28} strokeWidth={2.5} /></div>
          <div>
            <h1 className="text-2xl font-bold text-text">{t.fbTitle}</h1>
            <p className="text-sm text-text-muted">{t.fbSubtitle}</p>
          </div>
        </div>
        {isAdmin && (
          <button
            onClick={() => { setEditingFacility(null); setShowFacilityModal(true); }}
            className="bg-primary hover:bg-primary-dark text-white px-4 py-2.5 rounded-xl font-semibold text-sm transition-all shadow-md hover:shadow-lg flex items-center gap-2"
          >
            <Plus size={16} /> <span className="hidden sm:inline">{t.fbAddFacility}</span>
          </button>
        )}
      </div>

      {/* Login notice */}
      {isAnonymous && (
        <div className="card p-4 mb-6 flex items-center gap-3 border-l-4 border-l-primary">
          <div className="text-primary"><LogIn size={24} strokeWidth={2.5} /></div>
          <p className="text-sm text-text-secondary">{t.fbLoginNotice}</p>
        </div>
      )}

      {/* Tab pills */}
      <div className="flex gap-1.5 p-1 bg-surface-alt rounded-xl border border-border/60 mb-6 overflow-x-auto">
        {(["facilities", ...(user && !isAnonymous ? ["myBookings"] : []), ...(isAdmin ? ["allBookings"] : [])] as const).map((tb) => {
          const label =
            tb === "facilities"
              ? t.fbFacilitiesTab
              : tb === "myBookings"
              ? t.fbMyBookings
              : t.fbAllBookings;
          return (
            <button
              key={tb}
              onClick={() => { setTab(tb as any); setPage(1); }}
              className={`px-4 py-1.5 rounded-lg text-xs font-semibold transition-all whitespace-nowrap ${
                tab === tb
                  ? "bg-primary text-white shadow-sm"
                  : "text-text-muted hover:text-text hover:bg-surface"
              }`}
            >
              {label}
            </button>
          );
        })}
      </div>

      {/* Loading */}
      {loading && (
        <div className="flex items-center justify-center py-12 gap-3 text-text-muted">
          <Loader2 size={20} className="animate-spin" />
          <span className="text-sm">{t.loading}</span>
        </div>
      )}

      {/* Error */}
      {!loading && fetchError && (
        <div className="card p-8 text-center">
          <AlertTriangle size={32} className="text-red-400 mx-auto mb-3" />
          <p className="font-semibold text-text mb-1">{t.loadFailed}</p>
          <p className="text-sm text-text-muted mb-4">{fetchError}</p>
          <button onClick={fetchAll} className="px-5 py-2 btn-primary text-sm">{t.retry}</button>
        </div>
      )}

      {/* ΓöÇΓöÇ Facilities Tab ΓöÇΓöÇ */}
      {!loading && !fetchError && tab === "facilities" && (
        <>
          {facilities.length === 0 ? (
            <div className="card p-8 text-center">
              <Building2 size={40} className="text-text-muted mx-auto mb-3 opacity-40" />
              <p className="font-semibold text-text">{t.fbNoFacilities}</p>
            </div>
          ) : (
            <div className="grid gap-4 sm:grid-cols-2">
              {paginatedFacilities.map((fac) => (
                <div key={fac.id} className="card p-4 flex flex-col">
                  {/* Image */}
                  {fac.image_url && (
                    <div className="rounded-xl overflow-hidden border border-border/40 mb-3 -mt-1 -mx-1">
                      <img src={fac.image_url} alt={fac.name} className="w-full h-32 object-cover" />
                    </div>
                  )}

                  <h3 className="font-semibold text-text text-sm">{fac.name}</h3>
                  {fac.description && (
                    <p className="text-xs text-text-secondary mt-1 line-clamp-2">{fac.description}</p>
                  )}

                  <div className="flex items-center gap-3 mt-2 flex-wrap text-[11px] text-text-muted">
                    {fac.location && (
                      <span className="flex items-center gap-1"><MapPin size={11} /> {fac.location}</span>
                    )}
                    {fac.capacity && (
                      <span className="flex items-center gap-1"><Users size={11} /> {t.fbCapacity(fac.capacity)}</span>
                    )}
                  </div>

                  <div className="mt-auto pt-3 flex gap-2">
                    {!isAnonymous && user && (
                      <button
                        onClick={() => { setSelectedFacility(fac); setShowBookModal(true); }}
                        className="flex-1 py-2 rounded-xl bg-primary hover:bg-primary-dark text-white text-xs font-semibold transition-all shadow-sm flex items-center justify-center gap-1.5"
                      >
                        <Calendar size={13} /> {t.fbBook}
                      </button>
                    )}
                    {isAdmin && (
                      <>
                        <button
                          onClick={() => { setEditingFacility(fac); setShowFacilityModal(true); }}
                          className="p-2 rounded-xl border border-border hover:bg-surface-alt transition-colors"
                        >
                          <Pencil size={13} className="text-text-muted" />
                        </button>
                        <button
                          onClick={() => setDeletingFacility(fac)}
                          className="p-2 rounded-xl border border-border hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
                        >
                          <Trash2 size={13} className="text-red-400" />
                        </button>
                      </>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
          <Pagination page={page} total={facilities.length} perPage={PER_PAGE} onChange={setPage} />
        </>
      )}

      {/* ΓöÇΓöÇ Bookings Tab (My / All) ΓöÇΓöÇ */}
      {!loading && !fetchError && (tab === "myBookings" || tab === "allBookings") && (
        <>
          {displayBookings.length === 0 ? (
            <div className="card p-8 text-center">
              <Calendar size={40} className="text-text-muted mx-auto mb-3 opacity-40" />
              <p className="font-semibold text-text">{t.fbNoBookings}</p>
            </div>
          ) : (
            <div className="space-y-3">
              {paginatedBookings.map((b) => {
                const isOwner = b.booked_by === user?.id;
                return (
                  <div key={b.id} className={`card p-4 ${b.status === "cancelled" || b.status === "rejected" ? "opacity-60" : ""}`}>
                    <div className="flex items-start justify-between gap-2">
                      <div className="min-w-0 flex-1">
                        <h3 className="font-semibold text-text text-sm truncate">
                          {b.facilities?.name ?? "ΓÇö"}
                        </h3>
                        {/* Admin: show who booked */}
                        {isAdmin && b.profiles?.display_name && (
                          <p className="text-[11px] text-text-muted mt-0.5 flex items-center gap-1">
                            <svg className="w-3 h-3 shrink-0" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 9a3 3 0 100-6 3 3 0 000 6zm-7 9a7 7 0 1114 0H3z" clipRule="evenodd" /></svg>
                            {b.profiles.display_name}
                          </p>
                        )}
                        <div className="flex items-center gap-2 mt-1 flex-wrap">
                          <span className={`text-[10px] font-bold uppercase px-2 py-0.5 rounded-full ${statusColor(b.status)}`}>
                            {statusLabel(b.status, t)}
                          </span>
                        </div>
                      </div>
                    </div>

                    {/* Details */}
                    <div className="flex items-center gap-4 mt-2 flex-wrap text-[11px] text-text-muted">
                      <span className="flex items-center gap-1"><Calendar size={11} /> {formatDate(b.booking_date, language)}</span>
                      <span className="flex items-center gap-1"><Clock size={11} /> {formatTime(b.start_time)} ΓÇô {formatTime(b.end_time)}</span>
                      {b.attendees > 0 && (
                        <span className="flex items-center gap-1"><Users size={11} /> {b.attendees}</span>
                      )}
                    </div>

                    {b.purpose && (
                      <p className="text-xs text-text-secondary mt-2">{b.purpose}</p>
                    )}

                    {b.admin_note && (
                      <p className="text-xs text-text-muted mt-1 italic">≡ƒô¥ {b.admin_note}</p>
                    )}

                    {/* ΓöÇΓöÇ Check-in indicator ΓöÇΓöÇ */}
                    {b.checked_in_at && (
                      <div className="mt-1.5 flex items-center gap-1.5 text-[11px] font-semibold text-emerald-600 dark:text-emerald-400">
                        <svg className="w-3 h-3 shrink-0" viewBox="0 0 20 20" fill="currentColor">
                          <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                        </svg>
                        {t.mbCheckedIn} ┬╖ {new Date(b.checked_in_at).toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" })}
                      </div>
                    )}

                    {/* ΓöÇΓöÇ Entry QR ΓÇö approved bookings owned by current user ΓöÇΓöÇ */}
                    {isOwner && b.status === "approved" && (
                      <div className="mt-3 border-t border-border/40 pt-3">
                        <button
                          onClick={() => setExpandedQR(expandedQR === b.id ? null : b.id)}
                          className="flex items-center gap-1.5 text-xs font-semibold text-primary hover:text-primary-dark transition"
                        >
                          <QrCode size={13} />
                          {expandedQR === b.id ? t.fbQrHide : t.fbQrShow}
                        </button>
                        {expandedQR === b.id && (
                          <div className="mt-3 flex flex-col items-center gap-2 p-4 rounded-xl bg-white border border-border/60">
                            {/* eslint-disable-next-line @next/next/no-img-element */}
                            <img
                              src={`https://api.qrserver.com/v1/create-qr-code/?size=160x160&ecc=M&data=${encodeURIComponent(`makmur-booking:${b.id}`)}`}
                              alt="QR Code"
                              width={160}
                              height={160}
                              className="rounded"
                            />
                            <p className="text-[11px] text-gray-500 font-semibold">{t.fbQrLabel}</p>
                            <p className="text-[10px] text-gray-400 text-center max-w-[180px]">{t.fbQrHint}</p>
                          </div>
                        )}
                      </div>
                    )}

                    {/* Actions */}
                    <div className="flex items-center gap-2 mt-3 flex-wrap">
                      {/* Admin actions */}
                      {isAdmin && b.status === "pending" && (
                        <>
                          <button
                            onClick={() => handleBookingAction(b.id, "approved")}
                            className="text-xs font-semibold text-emerald-600 hover:text-emerald-700 flex items-center gap-1 px-2.5 py-1 rounded-lg hover:bg-emerald-50 dark:hover:bg-emerald-900/20 transition-colors"
                          >
                            <CheckCircle2 size={13} /> {t.fbApprove}
                          </button>
                          <button
                            onClick={() => handleBookingAction(b.id, "rejected")}
                            className="text-xs font-semibold text-red-500 hover:text-red-600 flex items-center gap-1 px-2.5 py-1 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
                          >
                            <XCircle size={13} /> {t.fbReject}
                          </button>
                        </>
                      )}
                      {/* Admin cancel approved booking */}
                      {isAdmin && b.status === "approved" && (
                        <button
                          onClick={() => { if (window.confirm(t.fbCancelConfirm)) handleBookingAction(b.id, "cancelled"); }}
                          className="text-xs font-semibold text-amber-600 hover:text-amber-700 flex items-center gap-1 px-2.5 py-1 rounded-lg hover:bg-amber-50 dark:hover:bg-amber-900/20 transition-colors"
                        >
                          <XCircle size={13} /> {t.fbAdminCancel}
                        </button>
                      )}
                      {/* Owner cancel */}
                      {isOwner && !isAdmin && (b.status === "pending" || b.status === "approved") && (
                        <button
                          onClick={() => handleBookingAction(b.id, "cancelled")}
                          className="text-xs font-semibold text-amber-600 hover:text-amber-700 flex items-center gap-1 px-2.5 py-1 rounded-lg hover:bg-amber-50 dark:hover:bg-amber-900/20 transition-colors"
                        >
                          <XCircle size={13} /> {t.fbCancel}
                        </button>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
          <Pagination page={page} total={displayBookings.length} perPage={PER_PAGE} onChange={setPage} />
        </>
      )}

      {/* ΓöÇΓöÇ Book Facility Modal ΓöÇΓöÇ */}
      {showBookModal && selectedFacility && (
        <BookModal
          facility={selectedFacility}
          onClose={() => { setShowBookModal(false); setSelectedFacility(null); }}
          onSaved={() => { setShowBookModal(false); setSelectedFacility(null); setTab("myBookings"); fetchAll(); }}
          t={t}
          language={language}
          userId={user?.id ?? ""}
        />
      )}

      {/* ΓöÇΓöÇ Facility Add/Edit Modal (Admin) ΓöÇΓöÇ */}
      {showFacilityModal && (
        <FacilityFormModal
          facility={editingFacility}
          onClose={() => { setShowFacilityModal(false); setEditingFacility(null); }}
          onSaved={() => { setShowFacilityModal(false); setEditingFacility(null); fetchAll(); }}
          t={t}
          language={language}
        />
      )}

      {/* ΓöÇΓöÇ Delete Facility Confirm ΓöÇΓöÇ */}
      {deletingFacility && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
          <div className="bg-surface rounded-2xl shadow-xl max-w-sm w-full p-6 border border-border/60">
            <div className="w-12 h-12 rounded-xl bg-red-50 dark:bg-red-900/20 flex items-center justify-center mx-auto mb-4">
              <Trash2 size={24} className="text-red-500" />
            </div>
            <h3 className="text-lg font-bold text-text text-center mb-2">{t.fbDeleteFacility}</h3>
            <p className="text-sm text-text-secondary text-center mb-6">{t.fbDeleteConfirm}</p>
            <div className="flex gap-3">
              <button onClick={() => setDeletingFacility(null)} className="flex-1 py-2.5 rounded-xl border border-border text-sm font-semibold text-text-secondary hover:bg-surface-alt transition-colors">
                {t.cancel}
              </button>
              <button onClick={() => handleDeleteFacility(deletingFacility.id)} className="flex-1 py-2.5 rounded-xl bg-red-500 hover:bg-red-600 text-white text-sm font-semibold transition-colors shadow-md">
                {t.delete}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */
/*  Book Modal                                                 */
/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */
function BookModal({
  facility,
  onClose,
  onSaved,
  t,
  language,
  userId,
}: {
  facility: Facility;
  onClose: () => void;
  onSaved: () => void;
  t: any;
  language: string;
  userId: string;
}) {
  const [bookingDate, setBookingDate] = useState("");
  const [startTime, setStartTime] = useState("08:00");
  const [endTime, setEndTime] = useState("10:00");
  const [purpose, setPurpose] = useState("");
  const [attendees, setAttendees] = useState(1);
  const [saving, setSaving] = useState(false);

  const minDate = new Date().toISOString().split("T")[0];

  const handleSubmit = async () => {
    if (!bookingDate || !startTime || !endTime) return;
    
    // Date validation: prevent backdating
    if (bookingDate < minDate) {
      toast.error(t.fbDateInPastError || "Booking date cannot be in the past.");
      return;
    }

    if (startTime >= endTime) {
      toast.error(t.fbEndTimeError);
      return;
    }
    if (facility.capacity && attendees > facility.capacity) {
      toast.error(t.fbAttendeesError);
      return;
    }
    setSaving(true);
    const supabase = createClient();
    const { error } = await supabase.from("facility_bookings").insert({
      facility_id: facility.id,
      booked_by: userId,
      booking_date: bookingDate,
      start_time: startTime,
      end_time: endTime,
      purpose: purpose.trim() || null,
      attendees,
    });
    if (error) {
      if (
        error.message.includes("BOOKING_OVERLAP") ||
        error.message.includes("unique") ||
        error.code === "23505"
      ) {
        toast.error(t.fbOverlapError);
      } else {
        toast.error(error.message);
      }
      setSaving(false);
      return;
    }
    toast.success(t.fbBookingSubmitted);
    onSaved();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-black/40 backdrop-blur-sm">
      <div className="bg-surface rounded-t-2xl sm:rounded-2xl shadow-xl max-w-md w-full max-h-[85vh] overflow-y-auto border border-border/60">
        {/* Header */}
        <div className="flex items-center justify-between p-5 border-b border-border/60 sticky top-0 bg-surface z-10 rounded-t-2xl">
          <div>
            <h3 className="text-lg font-bold text-text">{t.fbBookFacility}</h3>
            <p className="text-sm text-text-muted mt-0.5">{facility.name}</p>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-surface-alt rounded-xl transition-colors">
            <X size={18} className="text-text-muted" />
          </button>
        </div>

        <div className="p-5 space-y-4">
          {/* Date */}
          <div>
            <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.fbDate}</label>
            <input
              type="date" value={bookingDate} min={minDate}
              onChange={(e) => setBookingDate(e.target.value)}
              className="w-full px-4 py-2.5 rounded-xl border border-border bg-surface text-sm text-text focus:outline-none focus:ring-2 focus:ring-primary/30"
            />
          </div>

          {/* Time row */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.fbStartTime}</label>
              <input
                type="time" value={startTime} onChange={(e) => setStartTime(e.target.value)}
                className="w-full px-4 py-2.5 rounded-xl border border-border bg-surface text-sm text-text focus:outline-none focus:ring-2 focus:ring-primary/30"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.fbEndTime}</label>
              <input
                type="time" value={endTime} onChange={(e) => setEndTime(e.target.value)}
                className="w-full px-4 py-2.5 rounded-xl border border-border bg-surface text-sm text-text focus:outline-none focus:ring-2 focus:ring-primary/30"
              />
            </div>
          </div>

          {/* Purpose */}
          <div>
            <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.fbPurpose}</label>
            <input
              type="text" value={purpose} onChange={(e) => setPurpose(e.target.value)}
              placeholder={t.fbPurposePlaceholder}
              className="w-full px-4 py-2.5 rounded-xl border border-border bg-surface text-sm text-text focus:outline-none focus:ring-2 focus:ring-primary/30"
            />
          </div>

          {/* Attendees */}
          <div>
            <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">
              {t.fbAttendees}{facility.capacity ? <span className="ml-1 font-normal normal-case text-text-muted/70">({t.fbCapacity(facility.capacity)})</span> : ""}
            </label>
            <input
              type="number" value={attendees} min={1}
              max={facility.capacity ?? 999}
              onChange={(e) => setAttendees(Math.max(1, parseInt(e.target.value) || 1))}
              className="w-full px-4 py-2.5 rounded-xl border border-border bg-surface text-sm text-text focus:outline-none focus:ring-2 focus:ring-primary/30"
            />
            {facility.capacity && attendees > facility.capacity && (
              <p className="text-xs text-red-500 mt-1 font-medium">{t.fbAttendeesError}</p>
            )}
          </div>

          {/* Submit */}
          <button
            onClick={handleSubmit}
            disabled={!bookingDate || saving}
            className="w-full py-3 rounded-xl bg-primary hover:bg-primary-dark text-white font-semibold text-sm transition-all shadow-md hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
          >
            {saving ? (
              <><Loader2 size={16} className="animate-spin" /> {t.fbSubmitting}</>
            ) : (
              <><Calendar size={16} /> {t.fbSubmitBooking}</>
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */
/*  Facility Form Modal (Admin)                                */
/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */
function FacilityFormModal({
  facility,
  onClose,
  onSaved,
  t,
  language,
}: {
  facility: Facility | null;
  onClose: () => void;
  onSaved: () => void;
  t: any;
  language: string;
}) {
  const isEdit = !!facility;
  const [name, setName] = useState(facility?.name ?? "");
  const [description, setDescription] = useState(facility?.description ?? "");
  const [location, setLocation] = useState(facility?.location ?? "");
  const [capacity, setCapacity] = useState(facility?.capacity ?? 0);
  const [saving, setSaving] = useState(false);

  const handleSave = async () => {
    if (!name.trim()) return;
    setSaving(true);
    const supabase = createClient();

    const payload = {
      name: name.trim(),
      description: description.trim() || null,
      location: location.trim() || null,
      capacity: capacity > 0 ? capacity : null,
    };

    const { error } = isEdit
      ? await supabase.from("facilities").update(payload).eq("id", facility!.id)
      : await supabase.from("facilities").insert(payload);

    if (error) {
      toast.error(error.message);
      setSaving(false);
      return;
    }

    toast.success(
      isEdit ? t.fbFacilityUpdated : t.fbFacilityAdded
    );
    onSaved();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-black/40 backdrop-blur-sm">
      <div className="bg-surface rounded-t-2xl sm:rounded-2xl shadow-xl max-w-md w-full max-h-[85vh] overflow-y-auto border border-border/60">
        <div className="flex items-center justify-between p-5 border-b border-border/60 sticky top-0 bg-surface z-10 rounded-t-2xl">
          <h3 className="text-lg font-bold text-text">{isEdit ? t.fbEditFacility : t.fbAddFacility}</h3>
          <button onClick={onClose} className="p-2 hover:bg-surface-alt rounded-xl transition-colors">
            <X size={18} className="text-text-muted" />
          </button>
        </div>

        <div className="p-5 space-y-4">
          {/* Name */}
          <div>
            <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.fbFacilityName}</label>
            <input
              type="text" value={name} onChange={(e) => setName(e.target.value)}
              placeholder={t.fbFacilityNamePlaceholder}
              className="w-full px-4 py-2.5 rounded-xl border border-border bg-surface text-sm text-text focus:outline-none focus:ring-2 focus:ring-primary/30"
            />
          </div>

          {/* Description */}
          <div>
            <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.fbFacilityDesc}</label>
            <textarea
              value={description} onChange={(e) => setDescription(e.target.value)} rows={2}
              className="w-full px-4 py-2.5 rounded-xl border border-border bg-surface text-sm text-text focus:outline-none focus:ring-2 focus:ring-primary/30 resize-none"
            />
          </div>

          {/* Location */}
          <div>
            <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.fbFacilityLocation}</label>
            <input
              type="text" value={location} onChange={(e) => setLocation(e.target.value)}
              placeholder={t.fbFacilityLocPlaceholder}
              className="w-full px-4 py-2.5 rounded-xl border border-border bg-surface text-sm text-text focus:outline-none focus:ring-2 focus:ring-primary/30"
            />
          </div>

          {/* Capacity */}
          <div>
            <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.fbFacilityCapacity}</label>
            <input
              type="number" min={0} value={capacity} onChange={(e) => setCapacity(parseInt(e.target.value) || 0)}
              className="w-full px-4 py-2.5 rounded-xl border border-border bg-surface text-sm text-text focus:outline-none focus:ring-2 focus:ring-primary/30"
            />
          </div>

          {/* Submit */}
          <button
            onClick={handleSave}
            disabled={!name.trim() || saving}
            className="w-full py-3 rounded-xl bg-primary hover:bg-primary-dark text-white font-semibold text-sm transition-all shadow-md hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
          >
            {saving ? (
              <><Loader2 size={16} className="animate-spin" /> {t.saving}</>
            ) : (
              isEdit ? t.save : t.fbAddFacility
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useAuth } from "@/components/providers/AuthContext";
import { claimGig, cancelGig } from "@/lib/mutations/claims";
import { createClient } from "@/lib/supabase/client";
import React, { useEffect, useState } from "react";
import {
  Users, Clock, CheckCircle, AlertCircle, LogIn,
  Briefcase, Plus, X, Pencil, Trash2, AlertTriangle, Loader2, Star,
} from "lucide-react";
import Pagination from "@/components/ui/Pagination";
import { toast } from "react-hot-toast";
import { useLanguage } from "@/components/providers/LanguageContext";

type Gig = {
  id: string;
  title: string;
  description: string;
  required_pax: number;
  claimed: number;
  gig_date: string;
  start_time: string;
  end_time: string;
  is_completed: boolean;
};

// No hardcoded fallback ΓÇö all gigs come from Supabase.
// If the DB is empty or all gigs are claimed, the UI will say so.

// Resolves after `ms` milliseconds ΓÇö used to race against Supabase calls
function waitMs(ms: number): Promise<null> {
  return new Promise((resolve) => setTimeout(() => resolve(null), ms));
}

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
/*  Main Page                          */
/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
export default function GigsPage() {
  const { user, isAnonymous, isAdmin, points, setShowLoginModal } = useAuth();
  const { t, language } = useLanguage();
  const [gigs, setGigs] = useState<Gig[]>([]);
  const [loadingGigs, setLoadingGigs] = useState(true);
  const [fetchError, setFetchError] = useState<string | null>(null);
  const [claimedIds, setClaimedIds] = useState<Set<string>>(new Set());

  const [showAddModal, setShowAddModal] = useState(false);
  const [editingGig, setEditingGig] = useState<Gig | null>(null);
  const [deletingGig, setDeletingGig] = useState<Gig | null>(null);
  const [cancellingId, setCancellingId] = useState<string | null>(null);
  const [cancelConfirmId, setCancelConfirmId] = useState<string | null>(null);
  const [currentTime, setCurrentTime] = useState(new Date());

  const GIGS_PER_PAGE = 5;
  const [gigsPage, setGigsPage] = useState(1);

  /* ΓöÇΓöÇ Fetch user's existing claims (persists across refresh) ΓöÇΓöÇ */
  const fetchMyClaims = async (userId: string) => {
    try {
      const supabase = createClient();
      const { data } = await supabase
        .from("gig_claims")
        .select("gig_id")
        .eq("guest_uuid", userId);
      if (data && data.length > 0) {
        setClaimedIds(new Set(data.map((r: any) => r.gig_id)));
      }
    } catch {
      // Non-critical ΓÇö claimed state just won't pre-populate
    }
  };

  /* ΓöÇΓöÇ Fetch gigs from Supabase on mount ΓöÇΓöÇ */
  const fetchGigs = async () => {
    try {
      const supabase = createClient();
        const { data, error } = await supabase
          .from("volunteer_gigs")
          .select(`id, title, description, required_pax, gig_date, start_time, end_time, is_completed, created_at, gig_claims(count)`)
          .eq("is_cancelled", false)
          .order("gig_date", { ascending: true });

      if (error) {
        console.warn("Could not load gigs:", error.message);
        setFetchError(error.message);
        setGigs([]);
      } else {
        setFetchError(null);
        // Map DB rows to Gig type
        const mapped: Gig[] = (data ?? []).map((row: any) => ({
          id: row.id,
          title: row.title,
          description: row.description ?? "",
          required_pax: row.required_pax,
          claimed: row.gig_claims?.[0]?.count ?? 0,
          gig_date: row.gig_date ?? new Date().toISOString().split('T')[0],
          start_time: row.start_time ?? '19:00',
          end_time: row.end_time ?? '21:00',
          is_completed: !!row.is_completed,
        }));
        setGigs(mapped);
      }
    } catch {
      setGigs([]);
    } finally {
      setLoadingGigs(false);
    }
  };

  useEffect(() => {
    fetchGigs();

    if (user && !user.is_anonymous) {
      fetchMyClaims(user.id);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user]);

  // Live clock for countdowns (ticks every second)
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  /* ΓöÇΓöÇ Claim ΓöÇΓöÇ */
  const handleClaim = async (gigId: string) => {
    if (isAnonymous) { setShowLoginModal(true); return; }
    if (!user) return;
    const result = await claimGig(gigId, user.id);
    if (result.success) {
      setClaimedIds((prev) => new Set(prev).add(gigId));
      setGigs((prev) => prev.map((g) => g.id === gigId ? { ...g, claimed: g.claimed + 1 } : g));
      toast.success(t.claimGigSuccess);
    } else {
      toast.error(result.error ?? t.claimGigFail);
    }
  };

  /* ΓöÇΓöÇ Cancel ΓöÇΓöÇ */
  const handleCancel = async (gigId: string) => {
    if (!user) return;
    setCancellingId(gigId);
    const result = await cancelGig(gigId, user.id);
    if (result.success) {
      setClaimedIds((prev) => { const s = new Set(prev); s.delete(gigId); return s; });
      setGigs((prev) => prev.map((g) => g.id === gigId ? { ...g, claimed: Math.max(0, g.claimed - 1) } : g));
      toast.success(t.cancelGigSuccess);
    } else {
      toast.error(result.error ?? t.cancelGigFail);
    }
    setCancellingId(null);
  };

  /* ΓöÇΓöÇ After add/edit: refresh from DB so list is always accurate ΓöÇΓöÇ */
  const handleAddGig = (newGig: Gig) => {
    // Add immediately to local state for instant feedback
    setGigs((prev) => [newGig, ...prev]);
    // Then re-fetch from DB in background to sync
    setTimeout(() => fetchGigs(), 1500);
  };

  const handleUpdateGig = (updated: Gig) => {
    setGigs((prev) => prev.map((g) => g.id === updated.id ? updated : g));
    setTimeout(() => fetchGigs(), 1500);
  };

  const handleDeleteGig = (deletedId: string) => {
    setGigs((prev) => prev.filter((g) => g.id !== deletedId));
  };

  return (
    <div className="container mx-auto px-4 py-8 max-w-2xl">
      {/* Header */}
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-3">
          <div className="text-primary"><Briefcase size={28} strokeWidth={2.5} /></div>
          <div>
            <h1 className="text-2xl font-bold text-text">{t.gigsTitle}</h1>
            <p className="text-sm text-text-muted">{t.gigsSubtitle}</p>
          </div>
        </div>
        {isAdmin && (
          <button
            onClick={() => setShowAddModal(true)}
            className="bg-primary hover:bg-primary-dark text-white px-4 py-2.5 rounded-xl font-semibold text-sm transition-all shadow-md hover:shadow-lg flex items-center gap-2"
          >
            <Plus size={16} /> <span className="hidden sm:inline">{language === 'ms' ? 'Tambah Gig' : 'Add Gig'}</span>
          </button>
        )}
      </div>

      {/* User points card */}
      {!isAnonymous && user && (
        <div className="card p-4 mb-6 flex items-center gap-4 border-l-4 border-l-gold">
          <div className="w-10 h-10 rounded-xl bg-gold-light/20 flex items-center justify-center">
            <Star size={20} className="text-gold fill-gold" />
          </div>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-text-muted">{t.gigsMyPoints}</p>
            <p className="text-2xl font-bold text-text">{points.toLocaleString()} <span className="text-sm font-normal text-text-muted">pts</span></p>
          </div>
          <div className="ml-auto text-xs text-text-muted max-w-[140px] text-right">
            {t.gigsPointsDesc}
          </div>
        </div>
      )}

      {/* Login notice */}
      {isAnonymous && (
        <div className="card p-4 mb-6 flex items-center gap-3 border-l-4 border-l-primary">
          <div className="text-primary"><LogIn size={24} strokeWidth={2.5} /></div>
          <p className="text-sm text-text-secondary">{t.gigsLoginNotice}</p>
        </div>
      )}


      {/* Loading state */}
      {loadingGigs && (
        <div className="flex items-center justify-center py-12 gap-3 text-text-muted">
          <Loader2 size={20} className="animate-spin" />
          <span className="text-sm">{t.loading}</span>
        </div>
      )}

      {/* Error state */}
      {!loadingGigs && fetchError && (
        <div className="card p-8 text-center">
          <AlertTriangle size={32} className="text-red-400 mx-auto mb-3" />
          <p className="font-semibold text-text mb-1">{t.loadFailed ?? "Failed to load"}</p>
          <p className="text-sm text-text-muted mb-4">{fetchError}</p>
          <button onClick={fetchGigs} className="px-5 py-2 btn-primary text-sm">{t.retry ?? "Retry"}</button>
        </div>
      )}

      {/* Gig cards */}
      {!loadingGigs && (() => {
        // Filter out past gigs (end_time has passed)
        const activeGigs = gigs.filter(g => {
          const gigEnd = new Date(`${g.gig_date}T${g.end_time}`);
          return currentTime < gigEnd;
        });
        const allClaimed = activeGigs.length > 0 && activeGigs.every((g) => g.claimed >= g.required_pax);
        const isEmpty = activeGigs.length === 0;

        if (isEmpty || allClaimed) {
          return (
            <div className="card p-12 text-center">
              <div className="w-16 h-16 rounded-2xl bg-primary-50 dark:bg-primary/10 flex items-center justify-center mx-auto mb-4">
                <CheckCircle size={32} className="text-primary" />
              </div>
              <h3 className="font-bold text-text text-lg mb-2">
                {allClaimed ? t.gigsAllClaimed : t.gigsNoAvailable}
              </h3>
              <p className="text-sm text-text-muted max-w-xs mx-auto">
                {allClaimed
                  ? t.gigsAllClaimedDesc
                  : isAdmin
                    ? t.gigsNoAvailableAdmin
                    : t.gigsNoAvailableUser}
              </p>
            </div>
          );
        }

        const pagedGigs = activeGigs.slice(
          (gigsPage - 1) * GIGS_PER_PAGE,
          gigsPage * GIGS_PER_PAGE
        );

        return (
          <div className="space-y-4">
            {pagedGigs.map((gig) => {
              const isFull = gig.claimed >= gig.required_pax;
              const isClaimed = claimedIds.has(gig.id);

              // Check if this gig's time overlaps with any other gig the user already claimed
              const gigStartDt = new Date(`${gig.gig_date}T${gig.start_time}`);
              const gigEndDt = new Date(`${gig.gig_date}T${gig.end_time}`);
              const conflictingGig = !isClaimed ? gigs.find(g =>
                g.id !== gig.id &&
                claimedIds.has(g.id) &&
                !g.is_completed &&
                g.gig_date === gig.gig_date &&
                new Date(`${g.gig_date}T${g.start_time}`) < gigEndDt &&
                new Date(`${g.gig_date}T${g.end_time}`) > gigStartDt
              ) : undefined;
              const isConflict = !!conflictingGig;

              const pct = Math.min(100, Math.round((gig.claimed / gig.required_pax) * 100));
              const gigStart = new Date(`${gig.gig_date}T${gig.start_time}`);
              const gigEnd = new Date(`${gig.gig_date}T${gig.end_time}`);
              const isOngoing = currentTime >= gigStart && currentTime < gigEnd;
              const isUpcoming = currentTime < gigStart;

              // Countdown calculation
              let countdownLabel = "";
              if (isOngoing) {
                const diff = Math.max(0, Math.floor((gigEnd.getTime() - currentTime.getTime()) / 1000));
                const h = Math.floor(diff / 3600);
                const m = Math.floor((diff % 3600) / 60);
                const s = diff % 60;
                countdownLabel = `Ends in ${h > 0 ? h + "h " : ""}${m}m ${s}s`;
              } else if (isUpcoming) {
                const diff = Math.max(0, Math.floor((gigStart.getTime() - currentTime.getTime()) / 1000));
                const d = Math.floor(diff / 86400);
                const h = Math.floor((diff % 86400) / 3600);
                const m = Math.floor((diff % 3600) / 60);
                const s = diff % 60;
                if (d > 0) {
                  countdownLabel = `Starts in ${d}d ${h}h`;
                } else {
                  countdownLabel = `Starts in ${h > 0 ? h + "h " : ""}${m}m ${s}s`;
                }
              }
              return (
                <div key={gig.id} className="card p-5">
                  <div className="flex justify-between items-start mb-2">
                    <h3 className="font-bold text-text pr-2">{gig.title}</h3>
                    <div className="flex items-center gap-2 shrink-0">
                      <span className={`badge ${isFull ? "bg-gold-light/40 text-gold-dark dark:bg-surface-muted dark:text-gold" : "bg-primary-50 dark:bg-primary/10 text-primary"}`}>
                        <Users size={12} /> {gig.claimed}/{gig.required_pax}
                      </span>
                      {isAdmin && (
                        <>
                          <button
                            onClick={() => setEditingGig(gig)}
                            title="Edit gig"
                            className="w-8 h-8 rounded-lg bg-background border border-border flex items-center justify-center text-text-secondary hover:bg-primary-50 hover:text-primary hover:border-primary transition-all"
                          >
                            <Pencil size={14} />
                          </button>
                          <button
                            onClick={() => setDeletingGig(gig)}
                            title="Delete gig"
                            className="w-8 h-8 rounded-lg bg-background border border-border flex items-center justify-center text-text-secondary hover:bg-red-50 hover:text-red-500 hover:border-red-200 transition-all"
                          >
                            <Trash2 size={14} />
                          </button>
                        </>
                      )}
                    </div>
                  </div>

                  <p className="text-sm text-text-secondary mb-3">{gig.description}</p>
                  <div className="flex items-center gap-2 text-xs text-text-muted mb-3">
                    <Clock size={13} /> {new Date(gig.gig_date).toLocaleDateString('en-MY', { day: 'numeric', month: 'short', year: 'numeric' })} ┬╖ {gig.start_time?.slice(0, 5)} ΓÇô {gig.end_time?.slice(0, 5)}
                    {countdownLabel && (
                      <span className={`ml-auto text-[11px] font-bold px-2 py-0.5 rounded-md ${isOngoing ? "bg-gold-light/40 text-gold-dark dark:bg-surface-muted dark:text-gold" : "bg-primary-50 dark:bg-primary/10 text-primary"}`}>
                        {countdownLabel}
                      </span>
                    )}
                  </div>
                  <div className="progress-bar mb-4">
                    <div className="progress-fill" style={{ width: `${pct}%`, background: isFull ? "#D4A843" : undefined }} />
                  </div>

                  {/* Claim / Cancel buttons */}
                  {isClaimed ? (
                    <div className="flex gap-2 items-center">
                      <div className="flex-1 py-3 btn-primary text-sm flex items-center justify-center gap-2 opacity-80 cursor-default">
                        <CheckCircle size={15} /> Claimed Γ£ô
                      </div>
                      {isOngoing ? (
                        <span className="w-10 h-10 rounded-xl bg-gold-light/40 dark:bg-surface-muted flex items-center justify-center shrink-0" title="In Progress">
                          <Clock size={16} className="text-gold-dark dark:text-gold" />
                        </span>
                      ) : cancelConfirmId === gig.id ? null : (
                        <button
                          onClick={() => setCancelConfirmId(gig.id)}
                          title="Cancel your claim"
                          className="w-10 h-10 rounded-xl bg-transparent border border-transparent flex items-center justify-center text-text-muted hover:bg-red-50 hover:text-red-500 hover:border-red-200 dark:hover:bg-red-900/30 transition-all shrink-0"
                        >
                          <X size={16} />
                        </button>
                      )}
                    </div>
                  ) : (
                    <button
                      onClick={() => handleClaim(gig.id)}
                      disabled={isFull || isConflict}
                      className={`w-full py-3 text-sm flex items-center justify-center gap-2 rounded-xl font-semibold transition-all ${isConflict
                          ? 'bg-gold-light/20 text-gold-dark border border-gold/30 cursor-not-allowed dark:bg-surface-muted dark:text-gold dark:border-gold/20'
                          : 'btn-primary'
                        }`}
                      title={isConflict ? `Overlaps with "${conflictingGig?.title}"` : undefined}
                    >
                      {isConflict ? <AlertCircle size={16} /> : isAnonymous ? <LogIn size={16} /> : <Users size={16} />}
                      {isFull ? (language === 'ms' ? 'Penuh' : 'Fully Booked') : isConflict ? `Clashes with "${conflictingGig?.title}"` : isAnonymous ? t.signIn : t.claimGig}
                    </button>
                  )}
                </div>
              );
            })}
            <Pagination
              page={gigsPage}
              total={activeGigs.length}
              perPage={GIGS_PER_PAGE}
              onChange={setGigsPage}
            />
          </div>
        );
      })()}

      {/* Modals */}
      {showAddModal && (
        <GigFormModal mode="add" onClose={() => setShowAddModal(false)} onSave={handleAddGig} />
      )}
      {editingGig && (
        <GigFormModal mode="edit" gig={editingGig} onClose={() => setEditingGig(null)} onSave={handleUpdateGig} />
      )}
      {deletingGig && (
        <DeleteConfirmModal gig={deletingGig} onClose={() => setDeletingGig(null)} onDelete={handleDeleteGig} />
      )}
      {cancelConfirmId && (
        <CancelClaimModal
          gigTitle={gigs.find(g => g.id === cancelConfirmId)?.title ?? "this gig"}
          cancelling={cancellingId === cancelConfirmId}
          onConfirm={() => { handleCancel(cancelConfirmId); setCancelConfirmId(null); }}
          onClose={() => setCancelConfirmId(null)}
        />
      )}
    </div>
  );
}

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
/*  Shared Form Modal: Add OR Edit                 */
/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
function GigFormModal({
  mode, gig, onClose, onSave,
}: {
  mode: "add" | "edit";
  gig?: Gig;
  onClose: () => void;
  onSave: (gig: Gig) => void;
}): React.ReactElement {
  const { user } = useAuth();
  const { t } = useLanguage();
  const [title, setTitle] = useState(gig?.title ?? "");
  const [description, setDescription] = useState(gig?.description ?? "");
  const [requiredPax, setRequiredPax] = useState(String(gig?.required_pax ?? 10));
  const [gigDate, setGigDate] = useState(gig?.gig_date ?? new Date().toISOString().split('T')[0]);
  const [startTime, setStartTime] = useState(gig?.start_time ?? '19:00');
  const [endTime, setEndTime] = useState(gig?.end_time ?? '21:00');
  const [saving, setSaving] = useState(false);
  const [success, setSuccess] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);

  const isEdit = mode === "edit";

  const handleSave = async () => {
    if (!title.trim() || !description.trim()) return;
    if (!user) { setSaveError(t.gigLoginRequired); return; }

    // Date validation: prevent backdating
    const today = new Date().toISOString().split('T')[0];
    if (gigDate < today) {
      toast.error("Gig date cannot be in the past.");
      return;
    }

    setSaving(true);
    setSaveError(null);

    const supabase = createClient();

    try {
      if (isEdit && gig) {
        // ΓöÇΓöÇ UPDATE ΓöÇΓöÇ
        const result = await Promise.race([
          supabase
            .from("volunteer_gigs")
            .update({ title: title.trim(), description: description.trim(), required_pax: parseInt(requiredPax) || 10, gig_date: gigDate, start_time: startTime, end_time: endTime })
            .eq("id", gig.id),
          waitMs(6000),
        ]);

        if (result && "error" in result && result.error) {
          console.warn("Update warning (saved locally):", result.error.message);
          toast.error(result.error.message);
        } else {
          toast.success("Gig updated successfully!");
        }

        // Always update local state regardless of DB result
        onSave({ ...gig, title: title.trim(), description: description.trim(), required_pax: parseInt(requiredPax) || 10, gig_date: gigDate, start_time: startTime, end_time: endTime });

      } else {
        // ΓöÇΓöÇ INSERT ΓöÇΓöÇ
        const result = await Promise.race([
          supabase
            .from("volunteer_gigs")
            .insert({ title: title.trim(), description: description.trim(), required_pax: parseInt(requiredPax) || 10, gig_date: gigDate, start_time: startTime, end_time: endTime, created_by: user.id })
            .select("id")
            .single(),
          waitMs(6000),
        ]);

        const newId: string =
          result && "data" in result && result.data?.id
            ? (result.data.id as string)
            : crypto.randomUUID();

        if (result && "error" in result && result.error) {
          console.warn("Insert warning (saved locally with UUID):", result.error.message);
          toast.error(result.error.message);
        } else {
          toast.success("Gig created successfully!");
          
          // ΓöÇΓöÇ Native Push Notification for New Gig ΓöÇΓöÇ
          try {
            const { data: profiles } = await supabase
              .from("profiles")
              .select("fcm_tokens")
              .not("fcm_tokens", "is", null);

            if (profiles) {
              const allTokens = profiles.flatMap(p => p.fcm_tokens || []).filter(Boolean);
              if (allTokens.length > 0) {
                await fetch("/api/notifications/push", {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({
                    tokens: allTokens,
                    title: "New Volunteer Oppportunity!",
                    body: `Join us for "${title.trim()}". We need ${requiredPax} volunteers!`,
                    data: { url: "/gigs" }
                  }),
                });
              }
            }
          } catch (pushErr) {
            console.error("Gig push failed:", pushErr);
          }
        }

        onSave({
          id: newId,
          title: title.trim(),
          description: description.trim(),
          required_pax: parseInt(requiredPax) || 10,
          claimed: 0,
          gig_date: gigDate,
          start_time: startTime,
          end_time: endTime,
          is_completed: gig?.is_completed ?? false,
        });
      }

      setSuccess(true);
      setTimeout(() => onClose(), 1500);

    } catch (err) {
      console.error("Unexpected error in handleSave:", err);
      toast.error("Failed to save gig due to an unexpected error.");
      // Even on unexpected error, add the gig locally so user's work isn't lost
      const fallbackGig: Gig = {
        id: gig?.id ?? crypto.randomUUID(),
        title: title.trim(),
        description: description.trim(),
        required_pax: parseInt(requiredPax) || 10,
        claimed: gig?.claimed ?? 0,
        gig_date: gigDate,
        start_time: startTime,
        end_time: endTime,
        is_completed: gig?.is_completed ?? false,
      };
      onSave(fallbackGig);
      setSuccess(true);
      setTimeout(() => onClose(), 1500);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-surface rounded-2xl w-full max-w-md shadow-2xl relative" onClick={(e) => e.stopPropagation()}>
        <button onClick={onClose} className="absolute top-4 right-4 z-20 text-white/50 hover:text-white transition bg-black/20 rounded-full p-1">
          <X size={20} />
        </button>

        <div className="hero-gradient p-5 text-white overflow-hidden rounded-t-2xl relative">
          <div className="absolute top-0 right-0 w-32 h-32 bg-surface/5 rounded-full -mt-16 -mr-16 blur-2xl" />
          <div className="flex items-center gap-3 relative z-10">
            {isEdit ? <Pencil size={20} /> : <Briefcase size={22} />}
            <div>
              <h2 className="text-lg font-bold">{isEdit ? t.gigFormEditTitle : t.gigFormAddTitle}</h2>
              <p className="text-white/60 text-xs mt-0.5">
                {isEdit ? t.gigFormEditDesc : t.gigFormAddDesc}
              </p>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {success ? (
            <div className="text-center py-8">
              <CheckCircle size={52} className="text-primary mx-auto mb-3" />
              <p className="font-bold text-text text-lg">{isEdit ? t.gigUpdated : t.gigCreated}</p>
              <p className="text-sm text-text-muted mt-1">
                {isEdit ? t.gigChangesSaved : t.gigListedForVols}
              </p>
            </div>
          ) : (
            <>
              {saveError && (
                <div className="bg-red-50 border border-red-200 text-red-600 px-4 py-3 rounded-xl text-sm flex items-center gap-2">
                  <AlertCircle size={15} /> {saveError}
                </div>
              )}

              <div>
                <label className="text-xs font-semibold text-text-secondary uppercase tracking-wider mb-1.5 block">{t.gigFieldTitle}</label>
                <input
                  type="text" placeholder="e.g., Setup Audio System" value={title} onChange={(e) => setTitle(e.target.value)}
                  className="w-full px-3.5 py-2.5 border border-border rounded-xl text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none bg-background"
                />
              </div>

              <div>
                <label className="text-xs font-semibold text-text-secondary uppercase tracking-wider mb-1.5 block">{t.gigFieldDesc}</label>
                <textarea
                  placeholder="Describe what volunteers will doΓÇª" value={description} onChange={(e) => setDescription(e.target.value)} rows={3}
                  className="w-full px-3.5 py-2.5 border border-border rounded-xl text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none bg-background resize-none"
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-semibold text-text-secondary uppercase tracking-wider mb-1.5 block">{t.gigFieldVolunteers}</label>
                  <input
                    type="number" placeholder="10" value={requiredPax} onChange={(e) => setRequiredPax(e.target.value)} min="1"
                    className="w-full px-3.5 py-2.5 border border-border rounded-xl text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none bg-background"
                  />
                </div>
                <div>
                  <label className="text-xs font-semibold text-text-secondary uppercase tracking-wider mb-1.5 block">{t.gigFieldDate}</label>
                  <input
                    type="date" value={gigDate} onChange={(e) => setGigDate(e.target.value)}
                    min={new Date().toISOString().split('T')[0]}
                    className="w-full px-3.5 py-2.5 border border-border rounded-xl text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none bg-background"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-semibold text-text-secondary uppercase tracking-wider mb-1.5 block">{t.gigFieldStart}</label>
                  <input
                    type="time" value={startTime} onChange={(e) => setStartTime(e.target.value)}
                    className="w-full px-3.5 py-2.5 border border-border rounded-xl text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none bg-background"
                  />
                </div>
                <div>
                  <label className="text-xs font-semibold text-text-secondary uppercase tracking-wider mb-1.5 block">{t.gigFieldEnd}</label>
                  <input
                    type="time" value={endTime} onChange={(e) => setEndTime(e.target.value)}
                    className="w-full px-3.5 py-2.5 border border-border rounded-xl text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none bg-background"
                  />
                </div>
              </div>

              <button
                onClick={handleSave}
                disabled={saving || !title.trim() || !description.trim()}
                className="w-full py-3.5 btn-primary text-sm mt-2 flex items-center justify-center gap-2"
              >
                {saving && <Loader2 size={15} className="animate-spin" />}
                {saving ? (isEdit ? t.gigSaving : t.gigCreating) : (isEdit ? t.gigSaveChanges : t.gigCreateGig)}
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
/*  Delete Confirmation Modal                  */
/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
function DeleteConfirmModal({
  gig, onClose, onDelete,
}: {
  gig: Gig;
  onClose: () => void;
  onDelete: (id: string) => void;
}): React.ReactElement {
  const [deleting, setDeleting] = useState(false);
  const { t } = useLanguage();

  const handleDelete = async () => {
    setDeleting(true);
    const supabase = createClient();
    const result = await Promise.race([
      supabase.from("volunteer_gigs").delete().eq("id", gig.id),
      waitMs(5000),
    ]);
    if (result && "error" in result && result.error) {
      console.error("Error deleting gig:", result.error.message);
      toast.error("Failed to delete gig.");
      setDeleting(false);
    } else {
      toast.success("Gig deleted.");
      onDelete(gig.id);
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-surface rounded-2xl w-full max-w-sm overflow-hidden" onClick={(e) => e.stopPropagation()}>

        <div className="bg-red-50 dark:bg-red-950 border-b border-red-100 dark:border-red-900 p-5 flex items-center justify-between">
          <div className="flex gap-3 items-center">
            <AlertTriangle className="text-red-500" />
            <div>
              <h2 className="font-bold text-red-900 dark:text-red-200">{t.gigDeleteTitle}</h2>
              <p className="text-xs text-red-700 dark:text-red-400 mt-0.5">{t.gigDeleteUndo}</p>
            </div>
          </div>
          <button onClick={onClose} className="text-red-500 hover:text-red-700 bg-red-100 p-1 rounded-md"><X size={18} /></button>
        </div>

        <div className="p-6">
          <p className="text-sm text-text-secondary mb-1">{t.gigDeletePrefix}</p>
          <p className="font-bold text-text bg-background border border-border rounded-xl px-4 py-3 text-sm mb-5">
            &ldquo;{gig.title}&rdquo;
          </p>
          <div className="flex gap-3">
            <button onClick={onClose} className="flex-1 py-3 btn-outline text-sm font-bold rounded-xl">
              {t.cancel}
            </button>
            <button
              onClick={handleDelete}
              disabled={deleting}
              className="flex-1 py-3 bg-red-500 hover:bg-red-600 text-white font-bold rounded-xl text-sm transition-all flex items-center justify-center gap-2 disabled:opacity-50"
            >
              {deleting ? <Loader2 size={15} className="animate-spin" /> : <Trash2 size={15} />}
              {deleting ? t.gigDeleting : t.gigDeleteBtn}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

