"use client";

import { useAuth } from "@/components/providers/AuthContext";
import { useLanguage } from "@/components/providers/LanguageContext";
import { createClient } from "@/lib/supabase/client";
import type { FacilityBooking, BookingStatus } from "@/types/database";
import Link from "next/link";
import React, { useEffect, useState } from "react";
import Pagination from "@/components/ui/Pagination";
import {
  Building2, Users, Loader2, CalendarDays, Clock, ChevronRight,
  LogIn, Briefcase, QrCode, Download, HandHeart, Printer
} from "lucide-react";
import DonationReceiptModal from "@/components/modals/DonationReceiptModal";
import { QRCodeSVG } from "qrcode.react";

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
/* Helpers shared with facility-booking page            */
/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
function statusColor(s: BookingStatus) {
  const map: Record<BookingStatus, string> = {
    pending:   "bg-amber-500 text-white dark:bg-amber-500/80",
    approved:  "bg-emerald-600 text-white dark:bg-emerald-600/80",
    rejected:  "bg-red-600 text-white dark:bg-red-600/80",
    cancelled: "bg-gray-500 text-white dark:bg-gray-600",
  };
  return map[s] ?? map.pending;
}

function statusLabel(s: BookingStatus, t: any) {
  const map: Record<BookingStatus, string> = {
    pending:   t.fbStatusPending,
    approved:  t.fbStatusApproved,
    rejected:  t.fbStatusRejected,
    cancelled: t.fbStatusCancelled,
  };
  return map[s] ?? s;
}

function fmtDate(d: string) {
  return new Date(d + "T00:00").toLocaleDateString(undefined, {
    day: "numeric", month: "short", year: "numeric",
  });
}
function fmtTime(t: string) { return t?.slice(0, 5) ?? ""; }

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */

interface GigClaim {
  id: string;
  claimed_at: string;
  volunteer_gigs: {
    title: string;
    gig_date: string;
    start_time: string;
    end_time: string;
    is_completed: boolean;
    is_cancelled: boolean;
  } | null;
}

type TabKey = "facilities" | "gigs" | "donations";

const ITEMS_PER_PAGE = 5;

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */

export default function MyBookingsPage() {
  const { user, isAnonymous, isLoading: authLoading, setShowLoginModal } = useAuth();
  const { t } = useLanguage();

  const [tab, setTab] = useState<TabKey>("facilities");
  const [bookingPage, setBookingPage] = useState(1);
  const [gigPage, setGigPage] = useState(1);
  const [donationPage, setDonationPage] = useState(1);
  const [bookings, setBookings] = useState<FacilityBooking[]>([]);
  const [gigs, setGigs] = useState<GigClaim[]>([]);
  const [donations, setDonations] = useState<any[]>([]);
  const [showReceiptModal, setShowReceiptModal] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  // Reset page when tab changes
  function switchTab(key: TabKey) {
    setTab(key);
    setBookingPage(1);
    setGigPage(1);
    setDonationPage(1);
  }

  useEffect(() => {
    if (!user || isAnonymous) { setLoading(false); return; }
    const supabase = createClient();

    async function load() {
      setLoading(true);
      // Show bookings from the last 90 days (plus any future-dated approved bookings)
      const since90days = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000)
        .toISOString()
        .split("T")[0];
      const [bookRes, gigRes, donRes] = await Promise.all([
        supabase
          .from("facility_bookings")
          .select("*, facilities(name)")
          .eq("booked_by", user!.id)
          .order("booking_date", { ascending: false }),
        supabase
          .from("gig_claims")
          .select("id, claimed_at, volunteer_gigs(title, gig_date, start_time, end_time, is_completed, is_cancelled)")
          .eq("guest_uuid", user!.id)
          .order("claimed_at", { ascending: false }),
        supabase
          .from("donations")
          .select("*, crowdfund_campaigns(title)")
          .eq("donor_email", user!.email) // We track by email since donations can be done while guest but linked via email
          .eq("status", "completed")
          .order("created_at", { ascending: false }),
      ]);
      if (bookRes.data) setBookings(bookRes.data as FacilityBooking[]);
      if (gigRes.data) setGigs(gigRes.data as unknown as GigClaim[]);
      if (donRes.data) setDonations(donRes.data);
      setLoading(false);
    }
    load();

    // ΓöÇΓöÇ Realtime Subscriptions ΓöÇΓöÇ
    const bookingsChannel = supabase
      .channel("my_bookings_realtime")
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "facility_bookings", filter: `booked_by=eq.${user!.id}` },
        load
      )
      .subscribe();

    const gigsChannel = supabase
      .channel("my_gigs_realtime")
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "gig_claims", filter: `guest_uuid=eq.${user!.id}` },
        load
      )
      .subscribe();

    const donationsChannel = supabase
      .channel("my_donations_realtime")
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "donations", filter: `donor_email=eq.${user!.email}` },
        load
      )
      .subscribe();

    return () => {
      supabase.removeChannel(bookingsChannel);
      supabase.removeChannel(gigsChannel);
      supabase.removeChannel(donationsChannel);
    };
  }, [user, isAnonymous]);

  /* ΓöÇΓöÇ Guest gate ΓöÇΓöÇ */
  if (authLoading) {
    return (
      <div className="flex items-center justify-center min-h-[50vh]">
        <Loader2 className="animate-spin text-text-muted" size={22} />
      </div>
    );
  }
  if (isAnonymous || !user) {
    return (
      <div className="container mx-auto px-4 py-16 max-w-md text-center">
        <div className="w-16 h-16 rounded-2xl hero-gradient flex items-center justify-center text-white mx-auto mb-4">
          <Building2 size={28} />
        </div>
        <h1 className="text-2xl font-bold text-text mb-2">{t.myBookingsTitle}</h1>
        <p className="text-text-muted mb-6 text-sm">{t.myBookingsSignInHint}</p>
        <button
          onClick={() => setShowLoginModal(true)}
          className="btn-primary px-6 py-2.5 flex items-center gap-2 mx-auto"
        >
          <LogIn size={16} /> {t.signIn}
        </button>
      </div>
    );
  }

  const tabs: { key: TabKey; label: string; count: number }[] = [
    { key: "facilities", label: t.myBookingsFacilities, count: bookings.length },
    { key: "gigs",       label: t.myBookingsGigs,       count: gigs.length },
    { key: "donations",  label: "Donations",             count: donations.length },
  ];

  return (
    <div className="container mx-auto px-4 py-6 max-w-2xl">
      {/* Header */}
      <div className="flex items-center gap-3 mb-5">
        <div className="text-primary"><Briefcase size={24} strokeWidth={2.5} /></div>
        <div>
          <h1 className="text-xl font-bold text-text">{t.myBookingsTitle}</h1>
          <p className="text-xs text-text-muted">{t.myBookingsSubtitle}</p>
        </div>
      </div>

      {/* Tab pills ΓÇö full-width so they look balanced on mobile */}
      <div className="flex gap-2 mb-5">
        {tabs.map(tb => (
          <button
            key={tb.key}
            onClick={() => switchTab(tb.key)}
            className={`flex-1 py-2.5 rounded-xl text-sm font-semibold transition-all flex items-center justify-center gap-1.5 ${
              tab === tb.key
                ? "bg-primary text-white shadow-sm"
                : "bg-surface-alt text-text-muted hover:text-text"
            }`}
          >
            {tb.label}
            <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded-full ${
              tab === tb.key ? "bg-white/20 text-white" : "bg-border text-text-muted"
            }`}>
              {tb.count}
            </span>
          </button>
        ))}
      </div>

      {/* Content */}
      {loading ? (
        <div className="flex items-center justify-center py-16 text-text-muted gap-2">
          <Loader2 size={18} className="animate-spin" />
        </div>
      ) : tab === "facilities" ? (
        <FacilityList bookings={bookings} t={t} page={bookingPage} onPageChange={setBookingPage} />
      ) : tab === "gigs" ? (
        <GigList gigs={gigs} t={t} page={gigPage} onPageChange={setGigPage} />
      ) : (
        <DonationList 
          donations={donations} 
          t={t} 
          page={donationPage} 
          onPageChange={setDonationPage} 
          onShowReceipt={(id) => setShowReceiptModal(id)} 
        />
      )}

      {/* Receipt Modal */}
      {showReceiptModal && (
        <DonationReceiptModal 
          donationId={showReceiptModal}
          onClose={() => setShowReceiptModal(null)}
        />
      )}
    </div>
  );
}

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */

function FacilityList({ bookings, t, page, onPageChange }: { bookings: FacilityBooking[]; t: any; page: number; onPageChange: (p: number) => void }) {
  const [expandedQR, setExpandedQR] = useState<string | null>(null);

  const paged = bookings.slice((page - 1) * ITEMS_PER_PAGE, page * ITEMS_PER_PAGE);

  if (bookings.length === 0) {
    return (
      <div className="text-center py-16">
        <div className="w-14 h-14 rounded-2xl bg-surface-alt border border-border flex items-center justify-center mx-auto mb-3">
          <Building2 size={24} className="text-text-muted/50" />
        </div>
        <p className="text-sm font-semibold text-text-muted">{t.myBookingsFacilityEmpty}</p>
        <Link href="/facility-booking" className="mt-4 inline-flex items-center gap-1.5 text-sm text-primary font-semibold hover:underline">
          {t.myBookingsViewAll} <ChevronRight size={14} />
        </Link>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {paged.map(b => (
        <div key={b.id} className="card px-4 py-3.5">
          <div className="flex items-start justify-between gap-2 mb-2">
            <div className="min-w-0 flex-1">
              <p className="font-bold text-text text-[15px] leading-snug truncate">
                {b.facilities?.name ?? "ΓÇö"}
              </p>
              {b.purpose && (
                <p className="text-xs text-text-muted mt-0.5 line-clamp-1">{b.purpose}</p>
              )}
            </div>
            <span className={`text-[10px] font-bold uppercase px-2 py-1 rounded-full whitespace-nowrap flex-shrink-0 ${statusColor(b.status)}`}>
              {statusLabel(b.status, t)}
            </span>
          </div>
          <div className="flex flex-wrap gap-3 text-xs text-text-muted">
            <span className="flex items-center gap-1">
              <CalendarDays size={11} /> {fmtDate(b.booking_date)}
            </span>
            <span className="flex items-center gap-1">
              <Clock size={11} /> {fmtTime(b.start_time)} ΓÇô {fmtTime(b.end_time)}
            </span>
            <span className="flex items-center gap-1">
              <Users size={11} /> {b.attendees}
            </span>
          </div>
          {b.admin_note && (
            <p className="mt-2 text-xs text-text-muted italic border-t border-border/60 pt-2">
              {b.admin_note}
            </p>
          )}

          {/* ΓöÇΓöÇ Checked-in indicator ΓöÇΓöÇ */}
          {b.checked_in_at && (
            <div className="mt-2 flex items-center gap-1.5 text-[11px] font-semibold text-emerald-600 dark:text-emerald-400">
              <svg className="w-3 h-3 shrink-0" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
              </svg>
              {t.mbCheckedIn} ┬╖ {new Date(b.checked_in_at).toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" })}
            </div>
          )}

          {/* ΓöÇΓöÇ Entry QR ΓÇö approved bookings only ΓöÇΓöÇ */}
          {b.status === "approved" && (
            <div className="mt-3 border-t border-border/40 pt-3">
              <button
                onClick={() => setExpandedQR(expandedQR === b.id ? null : b.id)}
                className="flex items-center gap-1.5 text-xs font-semibold text-primary hover:text-primary-dark transition"
              >
                <QrCode size={13} />
                {expandedQR === b.id ? t.fbQrHide : t.fbQrShow}
              </button>
              {expandedQR === b.id && (
                <div className="mt-3 flex flex-col items-center gap-2 p-4 rounded-xl bg-white border border-border/60">
                  <QRCodeSVG
                    value={`makmur-booking:${b.id}`}
                    size={160}
                    level="M"
                    includeMargin
                  />
                  <p className="text-[11px] text-gray-500 font-semibold">{t.fbQrLabel}</p>
                  <p className="text-[10px] text-gray-400 text-center max-w-[180px]">{t.fbQrHint}</p>
                </div>
              )}
            </div>
          )}
        </div>
      ))}
      <Pagination page={page} total={bookings.length} perPage={ITEMS_PER_PAGE} onChange={onPageChange} />
    </div>
  );
}

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */

function GigList({ gigs, t, page, onPageChange }: { gigs: GigClaim[]; t: any; page: number; onPageChange: (p: number) => void }) {
  if (gigs.length === 0) {
    return (
      <div className="text-center py-16">
        <div className="w-14 h-14 rounded-2xl bg-surface-alt border border-border flex items-center justify-center mx-auto mb-3">
          <Briefcase size={24} className="text-text-muted/50" />
        </div>
        <p className="text-sm font-semibold text-text-muted">{t.myBookingsGigsEmpty}</p>
        <Link href="/gigs" className="mt-4 inline-flex items-center gap-1.5 text-sm text-primary font-semibold hover:underline">
          {t.navVolunteer} <ChevronRight size={14} />
        </Link>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {gigs.slice((page - 1) * ITEMS_PER_PAGE, page * ITEMS_PER_PAGE).map(c => {
        const g = c.volunteer_gigs;
        if (!g) return null;
        return (
          <div key={c.id} className="card px-4 py-3.5">
            <div className="flex items-start justify-between gap-2 mb-2">
              <p className="font-bold text-text text-[15px] leading-snug min-w-0 flex-1 truncate">{g.title}</p>
              <span className={`text-[10px] font-bold uppercase px-2 py-1 rounded-full whitespace-nowrap flex-shrink-0 ${
                g.is_cancelled
                  ? "bg-gray-500 text-white dark:bg-gray-600"
                  : g.is_completed
                    ? "bg-emerald-600 text-white dark:bg-emerald-600/80"
                    : "bg-primary/10 text-primary"
              }`}>
                {g.is_cancelled ? t.fbStatusCancelled : g.is_completed ? t.gigCompleted : t.mpUpcoming}
              </span>
            </div>
            <div className="flex flex-wrap gap-3 text-xs text-text-muted">
              <span className="flex items-center gap-1">
                <CalendarDays size={11} /> {fmtDate(g.gig_date)}
              </span>
              <span className="flex items-center gap-1">
                <Clock size={11} /> {fmtTime(g.start_time)} ΓÇô {fmtTime(g.end_time)}
              </span>
            </div>
          </div>
        );
      })}
      <Pagination page={page} total={gigs.length} perPage={ITEMS_PER_PAGE} onChange={onPageChange} />
    </div>
  );
}

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */

function DonationList({ donations, t, page, onPageChange, onShowReceipt }: { donations: any[]; t: any; page: number; onPageChange: (p: number) => void, onShowReceipt: (id: string) => void }) {
  if (donations.length === 0) {
    return (
      <div className="text-center py-16">
        <div className="w-14 h-14 rounded-2xl bg-surface-alt border border-border flex items-center justify-center mx-auto mb-3 text-text-muted/50">
          <HandHeart size={24} />
        </div>
        <p className="text-sm font-semibold text-text-muted">No donations yet.</p>
        <Link href="/crowdfunding" className="mt-4 inline-flex items-center gap-1.5 text-sm text-primary font-semibold hover:underline">
          Browse Campaigns <ChevronRight size={14} />
        </Link>
      </div>
    );
  }

  const paged = donations.slice((page - 1) * ITEMS_PER_PAGE, page * ITEMS_PER_PAGE);

  return (
    <div className="space-y-3">
      {paged.map(d => (
        <div key={d.id} className="card px-4 py-4">
          <div className="flex items-start justify-between gap-2 mb-3">
            <div className="min-w-0 flex-1">
              <p className="font-bold text-text text-[15px] leading-snug truncate">
                {d.crowdfund_campaigns?.title || "General Donation"}
              </p>
              <p className="text-xs text-text-muted mt-0.5">
                {new Date(d.created_at).toLocaleDateString(undefined, {
                  day: "numeric", month: "short", year: "numeric"
                })}
              </p>
            </div>
            <div className="text-right">
              <p className="text-[15px] font-black text-primary">
                {new Intl.NumberFormat("en-MY", {
                  style: "currency",
                  currency: "MYR",
                  minimumFractionDigits: 2,
                }).format(d.amount)}
              </p>
              <p className="text-[9px] uppercase tracking-wider text-emerald-600 dark:text-emerald-400 font-bold">Successful</p>
            </div>
          </div>
          
          <div className="flex gap-2">
            <button 
              onClick={() => onShowReceipt(d.id)}
              className="flex-1 py-2 bg-surface-alt border border-border hover:bg-primary/5 hover:border-primary/30 rounded-xl text-xs font-bold text-text-secondary hover:text-primary transition-all flex items-center justify-center gap-2"
            >
              <Printer size={13} />
              View Receipt
            </button>
          </div>
        </div>
      ))}
      <Pagination page={page} total={donations.length} perPage={ITEMS_PER_PAGE} onChange={onPageChange} />
    </div>
  );
}

"use client";

import React, { useEffect, useState, useRef, useCallback, useMemo } from "react";
import { useMachine } from "@xstate/react";
import { format } from "date-fns";
import { ms } from "date-fns/locale";
import { useScreenConfig } from "@/hooks/useScreenConfig";
import { useSystemSettings } from "@/hooks/useSystemSettings";
import { createClient } from "@/lib/supabase/client";
import FullScreenAlertScene from "@/components/paparan-masjid/FullScreenAlertScene";
import TimedCountdownScene from "@/components/paparan-masjid/TimedCountdownScene";
import { paparanMachine } from "@/lib/paparan-masjid/machine";
import { resolvePaparanScene } from "@/lib/paparan-masjid/schedule";
import { AZAN_PRAYERS, getPrayerLabel, PRAYER_DISPLAY, type PaparanScene, type PaparanSceneKind, type PrayerDay, type PrayerKey } from "@/lib/paparan-masjid/types";
import { Monitor, X, Volume2, Bell, Timer, ChevronDown, AlarmClock, AlertTriangle, Users, BookOpen } from "lucide-react";

// ΓöÇΓöÇ Helper ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function unixToTimeStr(unix: number): string {
  const d = new Date(unix * 1000);
  return format(d, "h:mm a");
}

function getCurrentAndNext(prayers: PrayerDay, nowUnix: number) {
  const order: PrayerKey[] = ["fajr", "syuruk", "dhuhr", "asr", "maghrib", "isha"];
  let current: PrayerKey | null = null;

  for (const key of order) {
    if (nowUnix >= prayers[key]) current = key;
  }

  const idx = current ? order.indexOf(current) : -1;
  // Skip syuruk as "next" ΓÇö itΓÇÖs a sunrise window, not a congregational prayer
  const next: PrayerKey | null = order.slice(idx + 1).find(k => k !== "syuruk") ?? null;
  return { current, next };
}

// ΓöÇΓöÇ Main Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export default function PaparanMasjidPage() {
  const { config, slides, loaded } = useScreenConfig();
  const sysSettings = useSystemSettings();
  const [machineState, sendToMachine] = useMachine(paparanMachine);

  const [now, setNow] = useState<Date>(new Date());
  const [prayers, setPrayers] = useState<PrayerDay | null>(null);
  const [hijriDate, setHijriDate] = useState<string>("");

  // Slideshow
  const [slideIdx, setSlideIdx] = useState(0);

  // Test panel
  const [showTestPanel, setShowTestPanel] = useState(false);
  const [testPrayer, setTestPrayer] = useState<PrayerKey>("dhuhr");
  const [testIqamatSecs, setTestIqamatSecs] = useState(30);
  const [debugOverride, setDebugOverride] = useState<{
    kind: PaparanSceneKind;
    prayerKey: PrayerKey;
    startedAtMs: number;
    endsAtMs: number;
  } | null>(null);
  const dismissedTokenRef = useRef<string>("");

  // Auto-detected zone (used when config.zone is blank)
  const [detectedZone, setDetectedZone] = useState<string>("");
  const [zoneDetecting, setZoneDetecting] = useState(false);

  // Active broadcasts for the ticker
  const [activeBroadcasts, setActiveBroadcasts] = useState<string[]>([]);

  const audioSubuhRef = useRef<HTMLAudioElement | null>(null);
  const audioOtherRef = useRef<HTMLAudioElement | null>(null);
  const audioBeepRef = useRef<HTMLAudioElement | null>(null);
  const lastScheduledTokenRef = useRef<string>("");
  const lastCueTokenRef = useRef<string>("");
  const lastPushTokenRef = useRef<string>("");
  const activeZoneRef = useRef("");
  // Track the calendar date last fetched so we can re-fetch at midnight
  const lastFetchedDate = useRef<number>(new Date().getDate());

  // ΓöÇΓöÇ Restore fired-guards from sessionStorage on mount ΓöÇΓöÇ
  useEffect(() => {
    const storedCueToken = sessionStorage.getItem("paparanLastCueToken");
    if (storedCueToken) lastCueTokenRef.current = storedCueToken;
    const storedPushToken = sessionStorage.getItem("paparanLastPushToken");
    if (storedPushToken) lastPushTokenRef.current = storedPushToken;
  }, []);

  // ΓöÇΓöÇ Helper: play a double-beep pattern, repeated `reps` times ΓöÇΓöÇ
  // Pattern per rep: beep ΓåÆ 150ms ΓåÆ beep  |  600ms gap before next rep
  const playBeeps = useCallback((reps = 1) => {
    const audio = audioBeepRef.current;
    if (!audio) return;
    let rep = 0;
    const playRep = () => {
      if (rep >= reps) return;
      // First beep of the pair
      audio.currentTime = 0;
      audio.play().catch(() => { });
      // Second beep 200ms later
      setTimeout(() => {
        audio.currentTime = 0;
        audio.play().catch(() => { });
        rep++;
        // Gap before next pair
        if (rep < reps) setTimeout(playRep, 600);
      }, 200);
    };
    playRep();
  }, []);

  // ΓöÇΓöÇ Live broadcasts for ticker (fetch + realtime) ΓöÇΓöÇ
  useEffect(() => {
    const supabase = createClient();
    const fetchBroadcasts = async () => {
      const { data } = await supabase
        .from("system_broadcasts")
        .select("message")
        .eq("is_active", true)
        .order("created_at", { ascending: false });
      setActiveBroadcasts((data ?? []).map((b: { message: string }) => b.message));
    };
    fetchBroadcasts();
    const channel = supabase
      .channel("ticker_broadcasts")
      .on("postgres_changes", { event: "*", schema: "public", table: "system_broadcasts" }, fetchBroadcasts)
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  // ΓöÇΓöÇ Auto-detect zone from geolocation when config.zone is blank ΓöÇΓöÇ
  useEffect(() => {
    if (config.zone || detectedZone || zoneDetecting) return;
    if (!navigator.geolocation) return;
    setZoneDetecting(true);
    navigator.geolocation.getCurrentPosition(
      async ({ coords }) => {
        try {
          const res = await fetch(
            `https://api.waktusolat.app/zones/${coords.latitude}/${coords.longitude}`
          );
          if (!res.ok) throw new Error(`HTTP error! status: ${res.status}`);
          const contentType = res.headers.get("content-type");
          if (!contentType || !contentType.includes("application/json")) {
            throw new Error("Received non-JSON response from API");
          }
          const data: { zone: string } = await res.json();
          if (data.zone) setDetectedZone(data.zone);
        } catch (err) {
          console.error("Failed to auto-detect zone:", err);
        } finally {
          setZoneDetecting(false);
        }
      },
      () => setZoneDetecting(false)
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [config.zone]);

  // ΓöÇΓöÇ Keyboard shortcut: press T to open test panel ΓöÇΓöÇ
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === "t" || e.key === "T") setShowTestPanel(v => !v);
      if (e.key === "Escape") {
        setShowTestPanel(false);
        setDebugOverride(null);
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, []);

  // ΓöÇΓöÇ Fetch prayer times (callable for both zone-change and midnight refresh) ΓöÇΓöÇ
  const activeZone = config.zone || detectedZone;
  useEffect(() => { activeZoneRef.current = activeZone; }, [activeZone]);

  const fetchPrayers = useCallback(async (zone: string) => {
    if (!zone) return;
    try {
      const r = await fetch(`https://api.waktusolat.app/v2/solat/${zone}`);
      if (!r.ok) throw new Error(`HTTP error! status: ${r.status}`);
      const contentType = r.headers.get("content-type");
      if (!contentType || !contentType.includes("application/json")) {
        throw new Error("Received non-JSON response from API");
      }
      const data: { prayers: PrayerDay[] } = await r.json();
      const today = new Date().getDate();
      lastFetchedDate.current = today;
      const dayData = data.prayers.find(p => p.day === today) || data.prayers[0];
      setPrayers(dayData);

      if (dayData?.hijri) {
        const [y, m, d] = dayData.hijri.split("-");
        const monthMap: Record<string, string> = {
          "01": "Muharam", "02": "Safar", "03": "Rabiulawal", "04": "Rabiulakhir",
          "05": "Jamadilawwal", "06": "Jamadilakhir", "07": "Rejab", "08": "Syaaban",
          "09": "Ramadan", "10": "Syawal", "11": "Zulkaedah", "12": "Zulhijjah",
        };
        setHijriDate(`${parseInt(d)} ${monthMap[m] ?? m} ${y}H`);
      }
    } catch (err) {
      console.error("Failed to fetch prayers in PaparanMasjid:", err);
    }
  }, []);

  useEffect(() => {
    fetchPrayers(activeZone);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeZone]);

  // ΓöÇΓöÇ Clock + midnight refresh ΓöÇΓöÇ
  useEffect(() => {
    const timer = setInterval(() => {
      const nowDate = new Date();
      setNow(nowDate);

      // ΓöÇΓöÇ Midnight prayer-data refresh ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      const todayDay = nowDate.getDate();
      if (todayDay !== lastFetchedDate.current && activeZoneRef.current) {
        fetchPrayers(activeZoneRef.current);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [fetchPrayers]);

  // ΓöÇΓöÇ Slideshow rotation ΓöÇΓöÇ
  useEffect(() => {
    if (!config.slideshow.enabled || slides.length === 0) return;
    const interval = Math.max(3, config.slideshow.interval_seconds) * 1000;
    const t = setInterval(() => setSlideIdx(i => (i + 1) % slides.length), interval);
    return () => clearInterval(t);
  }, [config.slideshow, slides]);

  const scheduledScene = useMemo(
    () => resolvePaparanScene({ now, prayers, config }),
    [now, prayers, config]
  );

  useEffect(() => {
    if (scheduledScene.token === lastScheduledTokenRef.current) return;
    lastScheduledTokenRef.current = scheduledScene.token;
    sendToMachine({ type: "SCHEDULE_UPDATED", scene: scheduledScene });
  }, [scheduledScene, sendToMachine]);

  const activeDebugScene = useMemo<PaparanScene | null>(() => {
    if (!debugOverride) return null;

    const nowMs = now.getTime();
    if (nowMs >= debugOverride.endsAtMs) return null;

    const totalMs = Math.max(debugOverride.endsAtMs - debugOverride.startedAtMs, 1);
    const remainingMs = Math.max(0, debugOverride.endsAtMs - nowMs);
    return {
      kind: debugOverride.kind,
      token: `debug:${debugOverride.kind}:${debugOverride.prayerKey}:${debugOverride.startedAtMs}`,
      prayerKey: debugOverride.prayerKey,
      startedAtMs: debugOverride.startedAtMs,
      endsAtMs: debugOverride.endsAtMs,
      totalMs,
      remainingMs,
      progress: Math.min(Math.max((nowMs - debugOverride.startedAtMs) / totalMs, 0), 1),
    };
  }, [debugOverride, now]);

  useEffect(() => {
    if (debugOverride && !activeDebugScene) {
      setDebugOverride(null);
    }
  }, [activeDebugScene, debugOverride]);

  const activeScene = activeDebugScene ?? scheduledScene;

  useEffect(() => {
    if (activeScene.kind === "idle") return;
    if (activeScene.token === lastCueTokenRef.current) return;

    lastCueTokenRef.current = activeScene.token;
    sessionStorage.setItem("paparanLastCueToken", activeScene.token);

    if (activeScene.kind === "azanAlert") {
      playBeeps(1);

      if (config.bunyi_azan.enabled && activeScene.prayerKey) {
        if (activeScene.prayerKey === "fajr" && audioSubuhRef.current) {
          audioSubuhRef.current.currentTime = 0;
          audioSubuhRef.current.play().catch(() => { });
        } else if (audioOtherRef.current) {
          audioOtherRef.current.currentTime = 0;
          audioOtherRef.current.play().catch(() => { });
        }
      }

      if (activeScene.token !== lastPushTokenRef.current && activeScene.prayerKey) {
        lastPushTokenRef.current = activeScene.token;
        sessionStorage.setItem("paparanLastPushToken", activeScene.token);
        fetch("/api/notifications/azan", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ prayerKey: activeScene.prayerKey }),
        }).catch(() => { });
      }

      return;
    }

    if (activeScene.kind === "iqamatFinalAlert" || activeScene.kind === "solatPhase") {
      playBeeps(1);
    }
  }, [activeScene, config.bunyi_azan.enabled, playBeeps]);

  // ΓöÇΓöÇ Test action handlers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const testPreAzan = () => {
    const startedAtMs = Date.now();
    setDebugOverride({
      kind: "preAzanCountdown",
      prayerKey: testPrayer,
      startedAtMs,
      endsAtMs: startedAtMs + testIqamatSecs * 1000,
    });
    setShowTestPanel(false);
  };

  const testAlert = () => {
    const startedAtMs = Date.now();
    setDebugOverride({
      kind: "azanAlert",
      prayerKey: testPrayer,
      startedAtMs,
      endsAtMs: startedAtMs + 120_000,
    });
    setShowTestPanel(false);
  };

  const testIqamat = () => {
    const startedAtMs = Date.now();
    setDebugOverride({
      kind: "iqamatCountdownMain",
      prayerKey: testPrayer,
      startedAtMs,
      endsAtMs: startedAtMs + testIqamatSecs * 1000,
    });
    setShowTestPanel(false);
  };

  const testIqamatFinal = () => {
    const startedAtMs = Date.now();
    setDebugOverride({
      kind: "iqamatFinalAlert",
      prayerKey: testPrayer,
      startedAtMs,
      endsAtMs: startedAtMs + testIqamatSecs * 1000,
    });
    setShowTestPanel(false);
  };

  const testSolat = () => {
    const startedAtMs = Date.now();
    setDebugOverride({
      kind: "solatPhase",
      prayerKey: testPrayer,
      startedAtMs,
      endsAtMs: startedAtMs + 120_000,
    });
    setShowTestPanel(false);
  };

  const testKhutbah = () => {
    const startedAtMs = Date.now();
    setDebugOverride({
      kind: "fridayKhutbah",
      prayerKey: "dhuhr",
      startedAtMs,
      endsAtMs: startedAtMs + testIqamatSecs * 1000,
    });
    setShowTestPanel(false);
  };

  const testAzan = (type: "subuh" | "other") => {
    if (type === "subuh" && audioSubuhRef.current) {
      audioSubuhRef.current.currentTime = 0;
      audioSubuhRef.current.play().catch(() => { });
    } else if (type === "other" && audioOtherRef.current) {
      audioOtherRef.current.currentTime = 0;
      audioOtherRef.current.play().catch(() => { });
    }
    setShowTestPanel(false);
  };

  const stopAll = () => {
    audioSubuhRef.current?.pause();
    audioOtherRef.current?.pause();
    audioBeepRef.current?.pause();
    if (audioSubuhRef.current) audioSubuhRef.current.currentTime = 0;
    if (audioOtherRef.current) audioOtherRef.current.currentTime = 0;
    if (audioBeepRef.current) audioBeepRef.current.currentTime = 0;
    setDebugOverride(null);
  };

  // ΓöÇΓöÇ Helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const nowUnix = Math.floor(now.getTime() / 1000);
  const { current: currentPrayer, next: nextPrayer } = prayers
    ? getCurrentAndNext(prayers, nowUnix)
    : { current: null, next: null };

  const bgStyle: React.CSSProperties = config.gambar_masjid.enabled && config.gambar_masjid.url
    ? { backgroundImage: `url(${config.gambar_masjid.url})`, backgroundSize: "cover", backgroundPosition: "center" }
    : {};

  // ΓöÇΓöÇ Memoised ticker values ΓÇö must be before any early return (Rules of Hooks) ΓöÇΓöÇ
  const tickerText = useMemo(
    () => activeBroadcasts.join("     ΓÇó     "),
    [activeBroadcasts]
  );
  const tickerDuration = useMemo(
    () => Math.max(20, Math.round(21 + tickerText.length * 0.09)),
    [tickerText]
  );
  const tickerActive = config.ticker?.enabled && activeBroadcasts.length > 0;
  const activePrayerLabel = getPrayerLabel(activeScene.prayerKey);
  const activePrayerTime = activeScene.prayerKey && prayers
    ? unixToTimeStr(prayers[activeScene.prayerKey])
    : undefined;
  const containerScene = activeScene.kind === "preAzanCountdown" || activeScene.kind === "iqamatCountdownMain"
    ? activeScene
    : null;
  const fullScreenScene = activeScene.kind !== "idle" && !containerScene && activeScene.token !== dismissedTokenRef.current ? activeScene : null;
  const sceneBackgroundUrl = slides[slideIdx]?.url || (config.gambar_masjid.enabled ? config.gambar_masjid.url : "");

  if (!loaded) {
    return (
      <div className="fixed inset-0 z-[9999] bg-[#0d1117] flex items-center justify-center">
        <div className="flex flex-col items-center gap-3 text-white/60">
          <Monitor size={40} className="animate-pulse" />
          <p className="text-sm">Memuatkan skrin masjidΓÇª</p>
        </div>
      </div>
    );
  }

  // ΓöÇΓöÇ Render ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const panelLayout = config.panel_waktu.layout ?? "horizontal";
  const isFriday = now.getDay() === 5;
  // Dim screen from 7 pm to 7 am to reduce OLED burn-in during low-activity hours
  const overlayDarkness = (now.getHours() >= 19 || now.getHours() < 7) ? "bg-black/93" : "bg-black/70";
  return (
    <div className="fixed inset-0 z-[9999] overflow-hidden select-none" style={bgStyle}>
      {/* Dark overlay ΓÇö auto-darkens between midnight and 4 am to reduce burn-in */}
      <div className={`absolute inset-0 ${overlayDarkness}`} />

      {/* ΓöÇΓöÇ CONTENT LAYER ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {/* pb is extended when the ticker bar is visible so content never hides behind it */}
      <div className={`relative z-10 h-full flex flex-col gap-4 pt-6 px-6 ${tickerActive ? "pb-[52px]" : "pb-6"}`}>

        {/* ΓöÇΓöÇ TOP BAR (always full-width) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
        <div className="flex items-start justify-between flex-shrink-0">
          {/* Left: system name + hijri */}
          <div>
            <p className="text-white/60 text-sm font-medium tracking-widest uppercase">
              {sysSettings.system_name}
            </p>
            {hijriDate && (
              <p className="text-white/40 text-xs mt-0.5">{hijriDate}</p>
            )}
            {/* Next prayer countdown chip */}
            {nextPrayer && prayers && (() => {
              const secs = Math.max(0, prayers[nextPrayer] - nowUnix);
              const h = Math.floor(secs / 3600);
              const m = Math.floor((secs % 3600) / 60);
              const s = secs % 60;
              return (
                <div className="inline-flex items-center gap-2 bg-white/10 rounded-full px-3 py-1 mt-2">
                  <div className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" />
                  <span className="text-white/70 text-xs font-semibold uppercase tracking-widest">
                    {getPrayerLabel(nextPrayer)}
                  </span>
                  <span className="text-white/50 text-xs tabular-nums">
                    {`${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`}
                  </span>
                </div>
              );
            })()}
          </div>

          {/* Right: clock */}
          <div className="text-right">
            <div className="flex items-end justify-end gap-1.5 leading-none">
              <p className="text-white text-5xl font-bold tabular-nums leading-none">
                {format(now, "HH:mm")}
              </p>
              <p className="text-white/40 text-2xl font-bold tabular-nums leading-none mb-0.5">
                {format(now, "ss")}
              </p>
            </div>
            <p className="text-white/50 text-sm mt-1">
              {format(now, "EEEE, d MMMM yyyy", { locale: ms })}
            </p>
          </div>
        </div>

        {/* ΓöÇΓöÇ MIDDLE ROW (flex-1, fills remaining height) ΓöÇΓöÇ */}
        {/* vertical ΓåÆ flex-row: slideshow left + prayer panel right */}
        {/* horizontal ΓåÆ flex-col: slideshow top + prayer panel bottom */}
