function formatDate(iso: string, lang: string): string {
  return new Date(iso).toLocaleDateString(lang === "ms" ? "ms-MY" : "en-MY", {
    day: "numeric", month: "long", year: "numeric",
  });
}

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */

export default function ProfilePage() {
  const { user, isAnonymous, isAdmin, points, signOut, setShowLoginModal, refreshProfile } = useAuth();
  const { t, language } = useLanguage();
  const router = useRouter();

  const [displayName, setDisplayName] = useState("");
  const [phone, setPhone] = useState("");
  const [avatarUrl, setAvatarUrl] = useState<string | null>(null);

  const [avatarFile, setAvatarFile] = useState<File | null>(null);
  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [loadingProfile, setLoadingProfile] = useState(true);
  const [showChangePassword, setShowChangePassword] = useState(false);
  const [showiOSModal, setShowiOSModal] = useState(false);
  const [showAndroidModal, setShowAndroidModal] = useState(false);
  const [isNotificationsEnabled, setIsNotificationsEnabled] = useState(false);
  const { subscribeToNotifications, unsubscribeFromNotifications, isSubscribing } = usePushNotifications();

  const avatarRef = useRef<HTMLInputElement>(null);

  /* ΓöÇΓöÇ Redirect guests ΓöÇΓöÇ */
  useEffect(() => {
    if (!isAnonymous) return;
    setShowLoginModal(true);
    router.push("/");
  }, [isAnonymous, router, setShowLoginModal]);

  /* ΓöÇΓöÇ Load profile ΓöÇΓöÇ */
  useEffect(() => {
    if (!user || isAnonymous) return;

    const fetchProfile = async () => {
      setLoadingProfile(true);
      const supabase = createClient();
      const { data } = await supabase
        .from("profiles")
        .select("display_name, phone, avatar_url, fcm_tokens")
        .eq("id", user.id)
        .single();

      if (data) {
        setDisplayName(data.display_name ?? "");
        setPhone(data.phone ?? "");
        setAvatarUrl(data.avatar_url ?? null);
        setAvatarPreview(data.avatar_url ?? null);
        
        // Initial subscription check (very basic)
        if (data.fcm_tokens && data.fcm_tokens.length > 0) {
          setIsNotificationsEnabled(true);
        }
      }
      setLoadingProfile(false);
    };

    fetchProfile();
  }, [user, isAnonymous]);

  /* ΓöÇΓöÇ Avatar file select ΓöÇΓöÇ */
  const handleAvatarSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 2 * 1024 * 1024) {
      toast.error(t.profileImgTooBig);
      return;
    }
    setAvatarFile(file);
    setAvatarPreview(URL.createObjectURL(file));
    e.target.value = "";
  };

  const clearAvatarChange = () => {
    setAvatarFile(null);
    setAvatarPreview(avatarUrl); // revert to saved
  };

  /* ΓöÇΓöÇ Save profile ΓöÇΓöÇ */
  const handleSave = async () => {
    if (!user) return;
    setSaving(true);
    const supabase = createClient();

    let newAvatarUrl = avatarUrl;

    // Upload new avatar if selected
    if (avatarFile) {
      setUploading(true);
      const ext = avatarFile.name.split(".").pop() ?? "jpg";
      const path = `${user.id}/avatar.${ext}`;
      const { data: uploadData, error: uploadErr } = await supabase.storage
        .from("avatars")
        .upload(path, avatarFile, { upsert: true });
      setUploading(false);
      if (uploadErr) {
        toast.error(uploadErr.message);
        setSaving(false);
        return;
      }
      const { data: { publicUrl } } = supabase.storage.from("avatars").getPublicUrl(uploadData.path);
      newAvatarUrl = publicUrl;
    }

    const { error } = await supabase.from("profiles").upsert({
      id: user.id,
      display_name: displayName.trim() || null,
      phone: phone.trim() || null,
      avatar_url: newAvatarUrl,
      updated_at: new Date().toISOString(),
    });

    if (error) {
      toast.error(error.message);
    } else {
      setAvatarUrl(newAvatarUrl);
      setAvatarFile(null);
      await refreshProfile(); // push new avatar/name to Navbar instantly
      toast.success(t.profileSaved);
    }
    setSaving(false);
  };

  const handleToggleNotifications = async () => {
    // Detect OS
    const ua = navigator.userAgent;
    const isIOS = /iPad|iPhone|iPod/.test(ua) && !(window as any).MSStream;
    const isAndroid = /Android/.test(ua);
    const isStandalone = window.matchMedia('(display-mode: standalone)').matches || (navigator as any).standalone;

    if (isIOS && !isStandalone) {
      setShowiOSModal(true);
      return;
    }

    if (isAndroid && !isStandalone) {
      setShowAndroidModal(true);
      return;
    }

    if (isNotificationsEnabled) {
      await unsubscribeFromNotifications();
      setIsNotificationsEnabled(false);
    } else {
      const success = await subscribeToNotifications();
      if (success) setIsNotificationsEnabled(true);
    }
  };

  /* ΓöÇΓöÇ Sign out ΓöÇΓöÇ */
  const handleSignOut = async () => {
    await signOut();
    router.push("/");
  };

  /* ΓöÇΓöÇ Loading / redirect ΓöÇΓöÇ */
  if (isAnonymous) return null;

  if (loadingProfile) {
    return (
      <div className="flex items-center justify-center min-h-[60vh] gap-3 text-text-muted">
        <Loader2 size={22} className="animate-spin" />
        <span className="text-sm">{t.loading}</span>
      </div>
    );
  }

  const initials = (displayName || user?.email || "U")[0].toUpperCase();
  const isBusy = saving || uploading;

  return (
    <div className="container mx-auto px-4 py-8 max-w-lg">
      {/* ΓöÇΓöÇ Header ΓöÇΓöÇ */}
      <div className="flex items-center gap-3 mb-8">
        <div className="text-primary"><User size={28} strokeWidth={2.5} /></div>
        <div>
          <h1 className="text-2xl font-bold text-text">
            {t.profileTitle}
          </h1>
          <p className="text-sm text-text-muted">
            {t.profileSubtitle}
          </p>
        </div>
      </div>

      {/* ΓöÇΓöÇ Avatar card ΓöÇΓöÇ */}
      <div className="card p-6 mb-5 flex flex-col items-center gap-4">
        <div className="relative">
          {avatarPreview ? (
            <img
              src={avatarPreview}
              alt="avatar"
              className="w-24 h-24 rounded-2xl object-cover border-2 border-border/50 shadow"
            />
          ) : (
            <div className="w-24 h-24 rounded-2xl hero-gradient flex items-center justify-center text-white text-3xl font-bold shadow">
              {initials}
            </div>
          )}
          <button
            onClick={() => avatarRef.current?.click()}
            className="absolute -bottom-2 -right-2 w-8 h-8 rounded-xl bg-primary text-white flex items-center justify-center shadow-md hover:bg-primary-dark transition"
            title={t.profileChangePhoto}
          >
            <Camera size={14} />
          </button>
        </div>

        {/* Changed indicator */}
        {avatarFile && (
          <div className="flex items-center gap-2 text-xs text-primary font-medium">
            <span>{t.profilePhotoSelected}</span>
            <button onClick={clearAvatarChange} className="text-text-muted hover:text-red-500 transition">
              <XCircle size={14} />
            </button>
          </div>
        )}

        {isAdmin && (
          <span className="flex items-center gap-1.5 text-xs font-bold px-3 py-1 rounded-full bg-gold/10 text-gold border border-gold/20">
            <ShieldCheck size={12} /> {t.profileAdminBadge}
          </span>
        )}

        <input
          ref={avatarRef}
          type="file"
          accept="image/*"
          className="hidden"
          onChange={handleAvatarSelect}
        />

        {/* ΓöÇΓöÇ Points display ΓöÇΓöÇ */}
        <div className="flex flex-col items-center pt-2">
          <div className="flex items-center gap-2 text-2xl font-bold text-text">
            <Star size={20} className="text-gold fill-gold" />
            {points.toLocaleString()}
          </div>
          <p className="text-[10px] font-bold uppercase tracking-widest text-text-muted mt-1">
            {t.profilePoints}
          </p>
        </div>
      </div>

      {/* ΓöÇΓöÇ Info card ΓöÇΓöÇ */}
      <div className="card p-6 mb-5 space-y-5">

        {/* Email ΓÇö read-only */}
        <div>
          <label className="flex items-center gap-1.5 text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">
            <Mail size={11} /> {t.profileEmailReadOnly}
          </label>
          <div className="px-4 py-2.5 rounded-xl bg-surface-alt border border-border/40 text-sm text-text-muted select-all">
            {user?.email}
          </div>
        </div>

        {/* Display name */}
        <div>
          <label className="flex items-center gap-1.5 text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">
            <User size={11} /> {t.profileDisplayName}
          </label>
          <input
            type="text"
            value={displayName}
            onChange={(e) => setDisplayName(e.target.value)}
            placeholder={t.profileNamePlaceholder}
            className="w-full px-4 py-2.5 rounded-xl border border-border bg-surface text-sm text-text focus:outline-none focus:ring-2 focus:ring-primary/30"
          />
        </div>

        {/* Phone */}
        <div>
          <label className="flex items-center gap-1.5 text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">
            <Phone size={11} /> {t.profilePhone}
          </label>
          <input
            type="tel"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
            placeholder="012-345 6789"
            className="w-full px-4 py-2.5 rounded-xl border border-border bg-surface text-sm text-text focus:outline-none focus:ring-2 focus:ring-primary/30"
          />
        </div>

        {/* Member since */}
        {user?.created_at && (
          <div className="flex items-center gap-2 text-xs text-text-muted pt-1 border-t border-border/40">
            <CalendarDays size={12} />
            <span>
              {t.profileMemberSince}{" "}
              {formatDate(user.created_at, language)}
            </span>
          </div>
        )}
      </div>

      {/* ΓöÇΓöÇ Notifications Card ΓöÇΓöÇ */}
      <div className="card p-6 mb-5">
        {((/iPad|iPhone|iPod/.test(navigator.userAgent) && !(window as any).MSStream) || /Android/.test(navigator.userAgent)) && 
         !(window.matchMedia('(display-mode: standalone)').matches || (navigator as any).standalone) && (
          <div className="mb-6 p-4 rounded-2xl bg-amber-500/5 border border-amber-500/20">
            <div className="flex gap-3">
              <div className="p-2 rounded-xl bg-amber-500/10 text-amber-500 shrink-0 h-fit">
                <Smartphone size={18} />
              </div>
              <div>
                <h4 className="text-sm font-bold text-text-muted mb-1">
                  {/Android/.test(navigator.userAgent) 
                    ? (language === 'ms' ? 'Tip Pengguna Android' : 'Android User Tip')
                    : (language === 'ms' ? 'Tip Pengguna iOS' : 'iOS User Tip')}
                </h4>
                <p className="text-xs text-text-muted leading-relaxed">
                  {/Android/.test(navigator.userAgent)
                    ? (language === 'ms' 
                        ? 'Untuk terima notifikasi di Android, anda perlu pasang aplikasi ini ke skrin utama dahulu.' 
                        : 'To receive notifications on your Android device, you must first install this app to your home screen.')
                    : (language === 'ms' 
                        ? 'Untuk terima notifikasi di iPhone, anda perlu "Add to Home Screen" dahulu melalui butang Share di pelayar.' 
                        : 'To receive notifications on your iPhone, you must first "Add to Home Screen" using the Share button in your browser.')}
                </p>
              </div>
            </div>
          </div>
        )}

        <div className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-amber-500/10 text-amber-500 flex items-center justify-center shrink-0">
              <Bell size={20} />
            </div>
            <div>
              <h3 className="text-sm font-bold text-text leading-tight">
                {t.profileNotifications}
              </h3>
              <p className="text-[11px] text-text-muted mt-0.5">
                {t.profileNotificationsDesc}
              </p>
            </div>
          </div>
          <button
            onClick={handleToggleNotifications}
            disabled={isSubscribing}
            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2 ${
              isSubscribing 
                ? 'bg-surface-alt text-text-muted cursor-not-allowed'
                : isNotificationsEnabled
                  ? 'bg-red-500/10 text-red-500 hover:bg-red-500/20'
                  : 'bg-primary/10 text-primary hover:bg-primary/20'
            }`}
          >
            {isSubscribing ? (
              <Loader2 size={14} className="animate-spin" />
            ) : isNotificationsEnabled ? (
              <Bell size={14} className="opacity-70" />
            ) : (
              <Smartphone size={14} />
            )}
            {isSubscribing 
              ? t.profileSaving 
              : isNotificationsEnabled 
                ? (language === 'ms' ? 'Matikan' : 'Disable') 
                : (language === 'ms' ? 'Aktifkan' : 'Enable')}
          </button>
        </div>
      </div>

      {/* ΓöÇΓöÇ Save button ΓöÇΓöÇ */}
      <button
        onClick={handleSave}
        disabled={isBusy}
        className="w-full py-3 rounded-xl bg-primary hover:bg-primary-dark text-white font-semibold text-sm transition-all shadow-md hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 mb-3"
      >
        {uploading ? (
          <><Loader2 size={16} className="animate-spin" /> {t.profileUploading}</>
        ) : saving ? (
          <><Loader2 size={16} className="animate-spin" /> {t.saving}</>
        ) : (
          <><Save size={16} /> {t.profileSave}</>
        )}
      </button>

      {/* ΓöÇΓöÇ Account actions ΓöÇΓöÇ */}
      <div className="card p-4 space-y-2 mt-2">
        <p className="text-xs font-semibold text-text-muted uppercase tracking-wider mb-3">
          {t.profileAccount}
        </p>
        <button
          onClick={() => setShowChangePassword(true)}
          className="w-full px-4 py-3 rounded-xl text-sm font-medium text-text-secondary hover:bg-surface-alt flex items-center gap-2.5 transition"
        >
          <KeyRound size={15} className="text-primary" />
          {t.navResetPassword}
        </button>
        <button
          onClick={handleSignOut}
          className="w-full px-4 py-3 rounded-xl text-sm font-medium text-red-500 hover:bg-red-50 dark:hover:bg-red-950/30 flex items-center gap-2.5 transition"
        >
          <LogOut size={15} />
          {t.signOut}
        </button>
      </div>

      {showChangePassword && (
        <ChangePasswordModal onClose={() => setShowChangePassword(false)} />
      )}

      {showiOSModal && (
        <IOSPushModal onClose={() => setShowiOSModal(false)} />
      )}
      {showAndroidModal && (
        <AndroidPushModal onClose={() => setShowAndroidModal(false)} />
      )}
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import dynamic from "next/dynamic";
import { Search, MapPin, Clock, Pencil, Trash2, X, AlertTriangle, Loader2, User, Calendar } from "lucide-react";
import { useAuth } from "@/components/providers/AuthContext";
import { createClient } from "@/lib/supabase/client";
import { toast } from "react-hot-toast";
import { useLanguage } from "@/components/providers/LanguageContext";

const MapComponent = dynamic(() => import("@/components/zakat/MapComponent"), { ssr: false });

type CounterStatus = "active" | "scheduled" | "expired";

interface ZakatCounter {
  id: string;
  name: string;
  lat: number;
  lng: number;
  status: CounterStatus;
  address: string;
  start_date?: string;
  end_date?: string;
  start_time?: string;
  end_time?: string;
}

function waitMs(ms: number): Promise<null> {
  return new Promise((resolve) => setTimeout(() => resolve(null), ms));
}

function getDistance(lat1: number, lon1: number, lat2: number, lon2: number) {
  const R = 6371; // Radius of the earth in km
  // deg2rad formula
  const dLat = (lat2 - lat1) * (Math.PI / 180);
  const dLon = (lon2 - lon1) * (Math.PI / 180);
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(lat1 * (Math.PI / 180)) *
    Math.cos(lat2 * (Math.PI / 180)) *
    Math.sin(dLon / 2) *
    Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c; // Distance in km
}

export default function ZakatLocatorPage() {
  const { isAdmin } = useAuth();
  const { t } = useLanguage();
  const [activeLocation, setActiveLocation] = useState<string | null>(null);
  const [panTrigger, setPanTrigger] = useState(0);
  const [locations, setLocations] = useState<ZakatCounter[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isPanning, setIsPanning] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [radiusKm, setRadiusKm] = useState<number | "All">("All");
  const [userLocation, setUserLocation] = useState<{ lat: number; lng: number } | null>(null);

  const filteredLocations = locations.filter((loc) => {
    const q = searchQuery.toLowerCase();
    const matchSearch = loc.name.toLowerCase().includes(q) || loc.address.toLowerCase().includes(q);
    if (!matchSearch) return false;

    if (radiusKm !== "All") {
      if (!userLocation) return false;
      const dist = getDistance(userLocation.lat, userLocation.lng, loc.lat, loc.lng);
      if (dist > radiusKm) return false;
    }
    return true;
  });

  // Admin Modals
  const [editingCounter, setEditingCounter] = useState<ZakatCounter | null>(null);
  const [deletingCounter, setDeletingCounter] = useState<ZakatCounter | null>(null);

  const fetchCounters = useCallback(async () => {
    try {
      const supabase = createClient();
      const { data, error } = await supabase.from("zakat_counters").select("*");
      if (error || !data) return;

      const now = new Date();
      const parsedLocations = data.map(zc => {
        let computedStatus: CounterStatus = "active";

        if (zc.start_date && zc.end_date && zc.start_time && zc.end_time) {
          const start = new Date(`${zc.start_date}T${zc.start_time.split('.')[0]}`);
          const end = new Date(`${zc.end_date}T${zc.end_time.split('.')[0]}`);
          const nowMs = now.getTime();

          if (nowMs > end.getTime()) {
            computedStatus = "expired";
          } else if (nowMs < start.getTime()) {
            computedStatus = "scheduled";
          } else {
            computedStatus = "active";
          }
        } else if (!zc.is_active) {
          computedStatus = "expired";
        }

        const timeStr = zc.start_time && zc.end_time ? `${zc.start_time.slice(0, 5)} - ${zc.end_time.slice(0, 5)}` : "Daily";

        return {
          id: zc.id,
          name: zc.name,
          lat: zc.latitude,
          lng: zc.longitude,
          address: zc.address || zc.name,
          status: computedStatus,
          start_date: zc.start_date,
          end_date: zc.end_date,
          start_time: zc.start_time,
          end_time: zc.end_time,
        };
      }).filter(loc => loc.status !== "expired");

      setLocations(parsedLocations);
      // Auto-select first active or scheduled
      const firstValid = parsedLocations.find(l => l.status !== "expired");
      if (firstValid && !activeLocation) setActiveLocation(firstValid.id);
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  }, [activeLocation]);

  useEffect(() => {
    fetchCounters();

    // Automatically poll every 30 seconds to update 'active', 'scheduled' and 'expired' map items organically over time.
    const pollInterval = setInterval(() => {
      fetchCounters();
    }, 30000);

    return () => clearInterval(pollInterval);
  }, [fetchCounters]);

  const handleLocationClick = (id: string) => {
    if (isPanning) return;
    setIsPanning(true);
    setActiveLocation(id);
    setPanTrigger(prev => prev + 1);
    // Debounce map panning clicks
    setTimeout(() => setIsPanning(false), 800);
  };

  const handleAddCounter = async (newLoc: any) => {
    try {
      const supabase = createClient();
      const { data, error } = await supabase.from("zakat_counters").insert({
        name: newLoc.name,
        latitude: newLoc.lat,
        longitude: newLoc.lng,
        address: newLoc.address,
        pic_name: newLoc.pic_name || "Makmur Admin",
        start_date: newLoc.start_date,
        end_date: newLoc.end_date,
        start_time: newLoc.start_time,
        end_time: newLoc.end_time,
        is_active: true,
      }).select("id").single();

      if (error) throw error;

      toast.success("Zakat counter added!");
      const timeStr = newLoc.start_time && newLoc.end_time ? `${newLoc.start_time.slice(0, 5)} - ${newLoc.end_time.slice(0, 5)}` : "Daily";
      setLocations((prev) => [...prev, {
        id: data.id,
        name: newLoc.name,
        lat: newLoc.lat,
        lng: newLoc.lng,
        status: newLoc.status,
        address: newLoc.address || newLoc.name,
        start_date: newLoc.start_date,
        end_date: newLoc.end_date,
        start_time: newLoc.start_time,
        end_time: newLoc.end_time,
      }]);
    } catch (err) {
      console.error("Error adding counter:", err);
      toast.error("Failed to save counter to database.");
    }
  };

  return (
    <div className="flex flex-col md:flex-row h-[calc(100vh-4rem)] bg-background overflow-hidden">
      {/* Sidebar */}
      <div className="w-full md:w-96 bg-surface border-r border-border flex flex-col h-1/2 md:h-full z-10">
        <div className="p-4 border-b border-border bg-surface sticky top-0">
          <div className="flex items-center gap-3 mb-4">
            <div className="icon-box icon-box-primary w-10 h-10"><MapPin size={18} /></div>
            <h1 className="text-lg font-bold text-text">{t.zakatTitle}</h1>
          </div>
          <div className="relative">
            <Search className="absolute left-3 top-2.5 text-text-muted" size={18} />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder={t.zakatSearch}
              className="w-full bg-background text-sm rounded-xl pl-10 pr-4 py-2.5 outline-none border border-border focus:ring-2 focus:ring-primary/20 focus:border-primary transition"
            />
          </div>
          <div className="mt-3 flex items-center gap-2">
            <span className="text-xs font-semibold text-text-muted uppercase">{t.zakatRadius}:</span>
            <select
              value={radiusKm}
              onChange={(e) => setRadiusKm(e.target.value === "All" ? "All" : Number(e.target.value))}
              className="bg-background border border-border text-sm rounded-lg py-1 px-2 outline-none focus:border-primary"
            >
              <option value="All">{t.zakatAll}</option>
              <option value="5">5 km</option>
              <option value="10">10 km</option>
              <option value="25">25 km</option>
              <option value="50">50 km</option>
            </select>
          </div>
          {radiusKm !== "All" && !userLocation && (
            <div className="mt-2 text-[11px] text-amber-600 bg-amber-50 rounded p-1.5 border border-amber-100 flex items-start gap-1">
              <AlertTriangle size={14} className="shrink-0" />
              <p>Please click "My Location" on the map so we can calculate distances!</p>
            </div>
          )}
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {filteredLocations.length === 0 ? (
            <div className="text-center py-10 bg-background rounded-2xl border border-border">
              <MapPin size={32} className="mx-auto text-text-muted opacity-30 mb-2" />
              <p className="text-text-secondary text-sm">{t.zakatNoResults}</p>
            </div>
          ) : filteredLocations.map((loc) => (
            <div
              key={loc.id}
              onClick={() => handleLocationClick(loc.id)}
              className={`card p-4 cursor-pointer relative ${activeLocation === loc.id ? "border-primary bg-primary-50" : ""} ${isPanning ? "pointer-events-none opacity-80" : ""}`}
            >
              <div className="flex justify-between items-start mb-2">
                <h3 className="font-bold text-text text-sm pr-12">{loc.name}</h3>
                <span className={`badge text-[10px] whitespace-nowrap ${loc.status === "active" ? "bg-primary-50 text-primary" :
                  loc.status === "scheduled" ? "bg-gold-light/20 text-gold" :
                    "bg-surface-muted text-text-muted"
                  }`}>
                  {loc.status === "active" ? t.statusActive : loc.status === "scheduled" ? t.statusScheduled : t.statusExpired}
                </span>
              </div>

              <div className="space-y-1.5 mt-2">
                {(loc.start_date || loc.end_date) && (
                  <div className="flex items-start gap-2 text-text-secondary text-xs">
                    <Calendar size={13} className="mt-0.5 shrink-0" />
                    <span>
                      {(() => {
                        const sDt = loc.start_date ? new Date(loc.start_date + 'T00:00').toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' }) : '';
                        const eDt = loc.end_date ? new Date(loc.end_date + 'T00:00').toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' }) : '';
                        
                        if (loc.start_time && loc.end_time) {
                          return (
                            <div className="flex flex-col gap-0.5 mt-[-2px]">
                              <span className="font-semibold text-primary-dark">{sDt} ({loc.start_time.slice(0, 5)})</span>
                              <span className="text-[10px] text-text-muted mt-0.5 ml-2 border-l-2 border-border pl-2 border-dashed">until</span>
                              <span className="font-semibold text-red-600 dark:text-red-400">{eDt} ({loc.end_time.slice(0, 5)})</span>
                            </div>
                          );
                        }
                        
                        return loc.start_date === loc.end_date ? sDt : `${sDt || 'Unspecified'} to ${eDt || 'Unspecified'}`;
                      })()}
                    </span>
                  </div>
                )}
                {/* Only show the compact time band if there are NO dates at all (i.e. 'Daily') */}
                {!loc.start_date && !loc.end_date && (
                  <div className="flex items-start gap-2 text-text-secondary text-xs">
                    <Clock size={13} className="mt-0.5 shrink-0" /> {loc.start_time ? `${loc.start_time.slice(0, 5)} - ${loc.end_time?.slice(0, 5) || 'Close'}` : 'Daily'}
                  </div>
                )}
                <div className="flex items-start gap-2 text-text text-xs font-semibold">
                  <MapPin size={13} className="mt-0.5 shrink-0" /> <span className="line-clamp-2 text-text-secondary">{loc.address}</span>
                </div>
              </div>

              {isAdmin && (
                <div className="absolute bottom-3 right-3 flex gap-1.5">
                  <button
                    onClick={(e) => { e.stopPropagation(); setEditingCounter(loc); }}
                    className="p-1.5 bg-surface border border-border rounded-md text-text-secondary hover:text-primary hover:bg-primary-50 transition"
                  >
                    <Pencil size={12} />
                  </button>
                  <button
                    onClick={(e) => { e.stopPropagation(); setDeletingCounter(loc); }}
                    className="p-1.5 bg-surface border border-border rounded-md text-text-secondary hover:text-red-500 hover:bg-red-50 transition"
                  >
                    <Trash2 size={12} />
                  </button>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Map */}
      <div className="w-full h-1/2 md:h-full md:flex-1 relative z-0 bg-border">
        {isLoading ? (
          <div className="w-full h-full flex items-center justify-center bg-border">
            <div className="animate-pulse flex flex-col items-center">
              <MapPin size={32} className="text-text-muted mb-2" />
              <p className="text-sm font-medium text-text-muted">Loading map...</p>
            </div>
          </div>
        ) : (
          <MapComponent
            locations={filteredLocations}
            activeLocationId={activeLocation}
            panTrigger={panTrigger}
            isAdmin={isAdmin}
            onAddCounter={handleAddCounter}
            onLocationFound={(lat, lng) => setUserLocation({ lat, lng })}
            userLocationCoords={userLocation}
          />
        )}
      </div>

      {/* Modals */}
      {editingCounter && (
        <EditCounterModal
          counter={editingCounter}
          onClose={() => setEditingCounter(null)}
          onSave={(updated) => {
            setLocations(prev => prev.map(l => l.id === updated.id ? updated : l));
          }}
        />
      )}
      {deletingCounter && (
        <DeleteCounterModal
          counter={deletingCounter}
          onClose={() => setDeletingCounter(null)}
          onDelete={(id) => {
            setLocations(prev => prev.filter(l => l.id !== id));
            if (activeLocation === id) setActiveLocation(null);
          }}
        />
      )}
    </div>
  );
}

