function EditCounterModal({ counter, onClose, onSave }: { counter: ZakatCounter, onClose: () => void, onSave: (c: ZakatCounter) => void }) {
  const [name, setName] = useState(counter.name);
  const [address, setAddress] = useState(counter.address);
  const [startDate, setStartDate] = useState(counter.start_date || "");
  const [endDate, setEndDate] = useState(counter.end_date || "");
  const [startTime, setStartTime] = useState(counter.start_time?.slice(0, 5) || "");
  const [endTime, setEndTime] = useState(counter.end_time?.slice(0, 5) || "");
  const [saving, setSaving] = useState(false);

  const handleSave = async () => {
    // Validation: End must be after start
    if (startDate && endDate && startTime && endTime) {
      const startDateTime = new Date(`${startDate}T${startTime.split('.')[0]}`);
      const endDateTime = new Date(`${endDate}T${endTime.split('.')[0]}`);
      
      if (endDateTime <= startDateTime) {
        toast.error("End date/time must be strictly after start date/time");
        return;
      }
    }

    setSaving(true);
    const supabase = createClient();
    try {
      await Promise.race([
        supabase.from("zakat_counters").update({
          name, address, 
          start_date: startDate || null, 
          end_date: endDate || null,
          start_time: startTime ? `${startTime}:00` : null,
          end_time: endTime ? `${endTime}:00` : null
        }).eq("id", counter.id),
        waitMs(5000)
      ]);

      const timeStr = startTime && endTime ? `${startTime} - ${endTime}` : "Daily";

      onSave({
        ...counter,
        name, address,
        start_date: startDate || undefined, 
        end_date: endDate || undefined,
        start_time: startTime ? `${startTime}:00` : undefined,
        end_time: endTime ? `${endTime}:00` : undefined
      });
      toast.success("Counter updated!");
      onClose();
    } catch {
      toast.error("Failed to update counter.");
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[200] flex items-center justify-center p-4 transition-opacity" onClick={onClose}>
      <div className="bg-surface rounded-2xl w-full max-w-md shadow-2xl relative" onClick={(e) => e.stopPropagation()}>
        <button onClick={onClose} className="absolute top-4 right-4 z-20 text-white/50 hover:text-white transition bg-black/20 rounded-full p-1">
          <X size={20} />
        </button>

        <div className="hero-gradient p-5 text-white overflow-hidden rounded-t-2xl relative">
          <div className="absolute top-0 right-0 w-32 h-32 bg-surface/5 rounded-full -mt-16 -mr-16 blur-2xl" />
          <h2 className="text-lg font-bold relative z-10 flex items-center gap-2"><Pencil size={18} /> Edit Zakat Counter</h2>
        </div>

        <div className="p-6 space-y-4">
          <div>
            <label className="text-xs font-semibold text-text-secondary uppercase block mb-1">Name</label>
            <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full px-3 py-2 border border-border rounded-lg text-sm bg-background outline-none focus:border-primary" />
          </div>
          <div>
            <label className="text-xs font-semibold text-text-secondary uppercase block mb-1">Address/Location Name</label>
            <input type="text" value={address} onChange={e => setAddress(e.target.value)} className="w-full px-3 py-2 border border-border rounded-lg text-sm bg-background outline-none focus:border-primary" />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-xs font-semibold text-text-secondary uppercase block mb-1">Start Date</label>
              <input type="date" min={new Date().toLocaleDateString('en-CA')} value={startDate} onChange={e => { setStartDate(e.target.value); if (endDate < e.target.value) setEndDate(e.target.value); }} className="w-full px-3 py-2 border border-border rounded-lg text-sm bg-background outline-none focus:border-primary" />
            </div>
            <div>
              <label className="text-xs font-semibold text-text-secondary uppercase block mb-1">End Date</label>
              <input type="date" min={startDate || new Date().toLocaleDateString('en-CA')} value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full px-3 py-2 border border-border rounded-lg text-sm bg-background outline-none focus:border-primary" />
            </div>
            <div>
              <label className="text-xs font-semibold text-text-secondary uppercase block mb-1">Start Time</label>
              <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full px-3 py-2 border border-border rounded-lg text-sm bg-background outline-none focus:border-primary" />
            </div>
            <div>
              <label className="text-xs font-semibold text-text-secondary uppercase block mb-1">End Time</label>
              <input type="time" value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full px-3 py-2 border border-border rounded-lg text-sm bg-background outline-none focus:border-primary" />
            </div>
          </div>
          <button onClick={handleSave} disabled={saving || !name.trim()} className="w-full py-3.5 btn-primary text-sm mt-3 flex justify-center gap-2">
            {saving && <Loader2 size={16} className="animate-spin" />} Save Changes
          </button>
        </div>
      </div>
    </div>
  );
}

function DeleteCounterModal({ counter, onClose, onDelete }: { counter: ZakatCounter, onClose: () => void, onDelete: (id: string) => void }) {
  const [deleting, setDeleting] = useState(false);

  const handleDelete = async () => {
    setDeleting(true);
    const supabase = createClient();
    await Promise.race([
      supabase.from("zakat_counters").delete().eq("id", counter.id),
      waitMs(5000)
    ]);
    toast.success("Counter deleted.");
    onDelete(counter.id);
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[200] flex items-center justify-center p-4 transition-opacity" onClick={onClose}>
      <div className="bg-surface rounded-2xl w-full max-w-sm overflow-hidden" onClick={e => e.stopPropagation()}>
        <div className="bg-red-50 dark:bg-red-950 border-b border-red-100 dark:border-red-900 p-5 flex items-center justify-between">
          <div className="flex gap-3 items-center">
            <AlertTriangle className="text-red-500" />
            <h2 className="font-bold text-red-900 dark:text-red-200">Delete Location?</h2>
          </div>
          <button onClick={onClose} className="text-red-500 hover:text-red-700 bg-red-100 p-1 rounded-md transition-colors"><X size={18} /></button>
        </div>
        <div className="p-6">
          <p className="text-sm text-text-secondary mb-4">Are you sure you want to remove "{counter.name}"?</p>
          <button onClick={handleDelete} disabled={deleting} className="w-full py-3 bg-red-500 text-white rounded-xl font-bold flex justify-center gap-2 transition-colors">
            {deleting && <Loader2 size={16} className="animate-spin" />} {deleting ? "Deleting..." : "Delete Location"}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import jsQR from "jsqr";
import { CameraOff, Loader2 } from "lucide-react";

interface CameraScannerProps {
  /** Called with the raw decoded QR string once per scan (2-second cooldown). */
  onScan: (value: string) => void;
}

export default function CameraScanner({ onScan }: CameraScannerProps) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const rafRef = useRef<number | null>(null);
  const lastScanRef = useRef<number>(0);  // 2-second cooldown after a successful scan
  const lastFrameRef = useRef<number>(0); // throttle frame processing to ~10 fps

  const [status, setStatus] = useState<"loading" | "active" | "error">("loading");
  const [errorMsg, setErrorMsg] = useState("");

  useEffect(() => {
    let cancelled = false;

    async function startCamera() {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "environment" },
        });
        if (cancelled) {
          stream.getTracks().forEach((t) => t.stop());
          return;
        }
        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          await videoRef.current.play();
        }
        setStatus("active");
        scanFrame();
      } catch (err: any) {
        if (!cancelled) {
          setStatus("error");
          if (err?.name === "NotAllowedError") {
            setErrorMsg("Camera permission denied. Please allow camera access and try again.");
          } else if (err?.name === "NotFoundError") {
            setErrorMsg("No camera found on this device.");
          } else {
            setErrorMsg("Unable to access camera: " + (err?.message ?? "Unknown error"));
          }
        }
      }
    }

    function scanFrame() {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      if (!video || !canvas || video.readyState < 2) {
        rafRef.current = requestAnimationFrame(scanFrame);
        return;
      }

      // Throttle to ~10 fps ΓÇö skip jsQR processing on intermediate frames.
      // Video continues rendering at native refresh rate; only decoding is capped.
      const now = Date.now();
      if (now - lastFrameRef.current < 100) {
        rafRef.current = requestAnimationFrame(scanFrame);
        return;
      }
      lastFrameRef.current = now;

      const ctx = canvas.getContext("2d", { willReadFrequently: true });
      if (!ctx) {
        rafRef.current = requestAnimationFrame(scanFrame);
        return;
      }

      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const code = jsQR(imageData.data, imageData.width, imageData.height, {
        inversionAttempts: "dontInvert",
      });

      if (code && now - lastScanRef.current > 2000) {
        lastScanRef.current = now;
        onScan(code.data);
      }

      rafRef.current = requestAnimationFrame(scanFrame);
    }

    startCamera();

    return () => {
      cancelled = true;
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      streamRef.current?.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
    };
  }, [onScan]);

  return (
    <div className="relative w-full rounded-xl overflow-hidden bg-black aspect-video flex items-center justify-center">
      {/* Video feed */}
      <video
        ref={videoRef}
        className="w-full h-full object-cover"
        muted
        playsInline
      />

      {/* Hidden canvas for frame processing */}
      <canvas ref={canvasRef} className="hidden" />

      {/* Loading overlay */}
      {status === "loading" && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/70 gap-2">
          <Loader2 className="animate-spin text-white" size={32} />
          <p className="text-white text-sm">Starting cameraΓÇª</p>
        </div>
      )}

      {/* Error overlay */}
      {status === "error" && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/80 gap-3 px-6 text-center">
          <CameraOff className="text-red-400" size={36} />
          <p className="text-white text-sm">{errorMsg}</p>
        </div>
      )}

      {/* Targeting reticle ΓÇö only shown when active */}
      {status === "active" && (
        <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
          <div className="w-48 h-48 relative">
            {/* Four corner brackets */}
            <span className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-primary rounded-tl-lg" />
            <span className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-primary rounded-tr-lg" />
            <span className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-primary rounded-bl-lg" />
            <span className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-primary rounded-br-lg" />

            {/* Scanning line animation */}
            <span className="absolute left-2 right-2 h-0.5 bg-primary/70 animate-scan-line" />
          </div>
          <p className="absolute bottom-4 text-white/70 text-xs tracking-wide">Point at the user&apos;s QR code</p>
        </div>
      )}
    </div>
  );
}

"use client";
/**
 * GigCompletionCard ΓÇö isolated from AdminPage so its 1-second
 * setInterval does NOT force the entire admin page to re-render.
 */
import { useState, useEffect } from "react";
import { Award, CheckCircle, Loader2 } from "lucide-react";
import { useLanguage } from "@/components/providers/LanguageContext";
import { createClient } from "@/lib/supabase/client";
import { formatTime } from "@/lib/utils";
import { toast } from "react-hot-toast";
import Link from "next/link";

export type GigEntry = {
  id: string;
  title: string;
  gig_date: string;
  start_time: string;
  end_time: string;
  is_completed: boolean;
  is_cancelled: boolean;
  completed_at: string | null;
  participant_count?: number;
};

interface Props {
  gigs: GigEntry[];
  onRefresh: () => void;
}

export default function GigCompletionCard({ gigs, onRefresh }: Props) {
  const { t } = useLanguage();

  // Timer lives HERE ΓÇö only this component re-renders every second
  const [currentTime, setCurrentTime] = useState(() => new Date());
  useEffect(() => {
    const id = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  // Derived: filter to past gigs, dedup, sort completed to bottom
  const pastGigs = gigs.filter((g) => {
    if (g.is_cancelled) return false; // Hide cancelled gigs immediately
    
    // Explicitly hide ghost gigs (0 participants) that have expired
    // This provides "immediate" effect before the DB cron runs
    const gigEnd = new Date(`${g.gig_date}T${g.end_time}`);
    const isPast = gigEnd < currentTime;
    if (isPast && !g.is_completed && (g.participant_count ?? 0) === 0) {
      return false;
    }
    
    return isPast;
  });

  const seen = new Set<string>();
  const uniquePastGigs = pastGigs.filter((g) => {
    const key = `${g.title}|${g.gig_date}|${g.start_time}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

  const visibleGigs = uniquePastGigs
    .filter((g) => {
      if (!g.is_completed) return true;
      if (!g.completed_at) return false;
      return currentTime.getTime() - new Date(g.completed_at).getTime() < 12 * 60 * 60 * 1000;
    })
    .sort((a, b) => {
      if (a.is_completed && !b.is_completed) return 1;
      if (!a.is_completed && b.is_completed) return -1;
      return 0;
    });

  const handleCompleteGig = async (gigId: string, gigTitle: string) => {
    const supabase = createClient();
    try {
      const { error } = await supabase.rpc("complete_gig", { p_gig_id: gigId });
      if (error) {
        toast.error(`Failed: ${error.message}`);
      } else {
        toast.success("Gig completed! Points awarded to volunteers.");
        onRefresh();

        // Trigger push notifications for participants
        const { data: claims } = await supabase
          .from("gig_claims")
          .select("guest_uuid")
          .eq("gig_id", gigId);

        if (claims && claims.length > 0) {
          const userIds = claims.map(c => c.guest_uuid);
          const { data: profiles } = await supabase
            .from("profiles")
            .select("fcm_tokens")
            .in("id", userIds);

          const allTokens = (profiles || [])
            .flatMap(p => p.fcm_tokens || [])
            .filter(t => typeof t === 'string' && t.length > 0);

          if (allTokens.length > 0) {
            try {
              await fetch("/api/notifications/push", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                  tokens: allTokens,
                  title: "Gig Completed! ≡ƒîƒ",
                  body: `Thank you for your help with "${gigTitle}". 100 points awarded!`,
                  data: { gig_id: gigId, type: "gig_completed" }
                })
              });
            } catch (pushErr) {
              console.error("Failed to send push notification:", pushErr);
            }
          }
        }
      }
    } catch (err) {
      console.error(err);
      toast.error("An unexpected error occurred.");
    }
  };

  return (
    <div className="card p-6 relative">
      <div className="flex justify-between items-start mb-2">
        <h2 className="font-bold text-lg text-text">{t.adminGigCompletion}</h2>
        <Link href="/admin/gigs" className="text-xs font-bold text-primary hover:text-primary-dark transition-colors border max-w-fit px-2 py-1 rounded-md border-primary/20 bg-primary/5 hover:bg-primary/10">
          Gig Details &raquo;
        </Link>
      </div>
      <p className="text-sm text-text-muted mb-4">{t.adminGigCompletionDesc}</p>

      {visibleGigs.length > 0 ? (
        <div className="space-y-2 max-h-80 overflow-y-auto">
          {visibleGigs.map((g) => (
            <div
              key={g.id}
              className={`flex justify-between items-center bg-background border rounded-xl px-4 py-3 transition-all duration-500 ${
                g.is_completed
                  ? "border-primary/30 bg-primary-50/30 dark:bg-primary/5 opacity-70"
                  : "border-border"
              }`}
            >
              <div>
                <span
                  className={`text-sm font-medium ${
                    g.is_completed ? "text-text-muted line-through" : "text-text"
                  }`}
                >
                  {g.title}
                </span>
                <span className="text-xs text-text-muted block">
                  {new Date(g.gig_date).toLocaleDateString("en-MY", {
                    day: "numeric",
                    month: "short",
                  })}{" "}
                  ┬╖ {formatTime(g.start_time)} ΓÇô {formatTime(g.end_time)}
                </span>
              </div>

              {g.is_completed ? (
                <div className="flex flex-col items-end gap-1">
                  <span className="badge bg-primary-50 text-primary border border-primary/20 text-xs">
                    <CheckCircle size={12} /> {t.adminAwardedLabel}
                  </span>
                  {g.completed_at &&
                    (() => {
                      const remainMs =
                        12 * 60 * 60 * 1000 -
                        (currentTime.getTime() - new Date(g.completed_at).getTime());
                      const totalSec = Math.max(0, Math.floor(remainMs / 1000));
                      const h = Math.floor(totalSec / 3600);
                      const m = Math.floor((totalSec % 3600) / 60);
                      const s = totalSec % 60;
                      return (
                        <span className="text-[10px] text-text-muted font-mono">
                          {t.adminClearsIn(h, m, s)}
                        </span>
                      );
                    })()}
                </div>
              ) : (
                <button
                  onClick={() => handleCompleteGig(g.id, g.title)}
                  className="badge bg-primary-50 text-primary border border-[#D5F5E3] hover:bg-[#D5F5E3] hover:scale-105 active:scale-95 transition-all text-xs"
                >
                  <Award size={12} /> {t.adminCompleteAward}
                </button>
              )}
            </div>
          ))}
        </div>
      ) : (
        <p className="text-sm text-text-muted text-center py-6">{t.adminNoPastGigs}</p>
      )}
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { createClient } from "@/lib/supabase/client";
import { useLanguage } from "@/components/providers/LanguageContext";
import { useAuth } from "@/components/providers/AuthContext";
import type { MosqueProgram, ProgramType } from "@/types/database";
import toast from "react-hot-toast";
import {
  CalendarDays, Plus, Pencil, Trash2, X,
  ToggleLeft, ToggleRight, Loader2, Radio,
} from "lucide-react";

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
/* Shared helpers                                       */
/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
function typeColor(type: ProgramType) {
  const map: Record<ProgramType, string> = {
    lecture: "bg-blue-600 text-white dark:bg-blue-500/80",
    halaqah: "bg-emerald-600 text-white dark:bg-emerald-500/80",
    jumuah:  "bg-amber-500 text-white dark:bg-amber-500/80",
    other:   "bg-purple-600 text-white dark:bg-purple-500/80",
  };
  return map[type] ?? map.other;
}

function typeLabel(type: ProgramType, t: any) {
  const map: Record<ProgramType, string> = {
    lecture: t.mpLecture,
    halaqah: t.mpHalaqah,
    jumuah:  t.mpJumuah,
    other:   t.mpOther,
  };
  return map[type] ?? type;
}

function fmtDate(d: string) {
  return new Date(d + "T00:00").toLocaleDateString(undefined, {
    day: "numeric", month: "short", year: "numeric",
  });
}

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
/* Inline Add / Edit Modal                             */
/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
interface ModalProps {
  program: MosqueProgram | null;
  onClose: () => void;
  onSaved: (p: MosqueProgram) => void;
  t: any;
}

function ProgramModal({ program, onClose, onSaved, t }: ModalProps) {
  const { user } = useAuth();
  const isEdit = !!program;

  const [title,          setTitle]          = useState(program?.title ?? "");
  const [type,           setType]           = useState<ProgramType>(program?.program_type ?? "lecture");
  const [date,           setDate]           = useState(program?.program_date ?? new Date().toISOString().split("T")[0]);
  const [startTime,      setStartTime]      = useState(program?.start_time?.slice(0, 5) ?? "20:00");
  const [endTime,        setEndTime]        = useState(program?.end_time?.slice(0, 5) ?? "21:00");
  const [speaker,        setSpeaker]        = useState(program?.speaker ?? "");
  const [location,       setLocation]       = useState(program?.location ?? "");
  const [desc,           setDesc]           = useState(program?.description ?? "");
  const [isRecurring,    setIsRecurring]    = useState(program?.is_recurring ?? false);
  const [recurrenceNote, setRecurrenceNote] = useState(program?.recurrence_note ?? "");
  const [saving,         setSaving]         = useState(false);

  // Lock body scroll while modal is open
  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = prev; };
  }, []);

  const programTypes: { value: ProgramType; label: string }[] = [
    { value: "lecture", label: t.mpLecture },
    { value: "halaqah", label: t.mpHalaqah },
    { value: "jumuah",  label: t.mpJumuah  },
    { value: "other",   label: t.mpOther   },
  ];

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim() || !date || !startTime || !endTime) return;

    // Date validation: prevent backdating
    const today = new Date().toISOString().split("T")[0];
    if (date < today) {
      toast.error(t.mpDateInPastError || "Program date cannot be in the past.");
      return;
    }

    if (endTime < startTime) { toast.error(t.mpTimeError); return; }
    setSaving(true);
    const supabase = createClient();
    const payload = {
      title:           title.trim(),
      program_type:    type,
      program_date:    date,
      start_time:      startTime,
      end_time:        endTime,
      speaker:         speaker.trim() || null,
      location:        location.trim() || null,
      description:     desc.trim() || null,
      is_recurring:    isRecurring,
      recurrence_note: isRecurring && recurrenceNote.trim() ? recurrenceNote.trim() : null,
      is_active:       true,
    };

    if (isEdit && program) {
      const { data, error } = await supabase
        .from("mosque_programs")
        .update(payload)
        .eq("id", program.id)
        .select()
        .single();
      setSaving(false);
      if (error) { toast.error(error.message); return; }
      toast.success(t.mpUpdated);
      onSaved(data as MosqueProgram);
    } else {
      const { data, error } = await supabase
        .from("mosque_programs")
        .insert({ ...payload, created_by: user?.id ?? null })
        .select()
        .single();
      setSaving(false);
      if (error) { toast.error(error.message); return; }
      toast.success(t.mpCreated);
      onSaved(data as MosqueProgram);
    }
  };

  return (
    <div
      className="fixed inset-0 z-[60] flex items-end sm:items-center justify-center p-0 sm:p-4 bg-black/40 backdrop-blur-sm"
      onClick={onClose}
    >
      <div
        className="bg-surface rounded-t-2xl sm:rounded-2xl shadow-xl max-w-md w-full max-h-[90vh] overflow-y-auto border border-border/60"
        onClick={e => e.stopPropagation()}
      >
        <div className="sticky top-0 bg-surface border-b border-border/60 flex items-center justify-between px-5 py-4 z-10 rounded-t-2xl">
          <div className="flex items-center gap-2.5">
            <div className="w-7 h-7 rounded-lg hero-gradient flex items-center justify-center flex-shrink-0">
              {isEdit ? <Pencil size={12} className="text-white" /> : <Plus size={12} className="text-white" />}
            </div>
            <h2 className="font-bold text-text">{isEdit ? t.mpEditTitle : t.mpAddTitle}</h2>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20 text-text-muted hover:text-red-500 transition-colors"
          >
            <X size={18} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-5 space-y-3">
          <div>
            <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.mpFieldTitle}</label>
            <input value={title} onChange={e => setTitle(e.target.value)} required autoFocus className="input w-full" placeholder="Kuliah Maghrib Harian" />
          </div>
          <div>
            <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.mpFieldType}</label>
            <select value={type} onChange={e => setType(e.target.value as ProgramType)} className="input w-full">
              {programTypes.map(pt => <option key={pt.value} value={pt.value}>{pt.label}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.mpFieldDate}</label>
            <input type="date" value={date} onChange={e => setDate(e.target.value)} required className="input w-full" />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.mpFieldStart}</label>
              <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} required className="input w-full" />
            </div>
            <div>
              <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.mpFieldEnd}</label>
              <input type="time" value={endTime} onChange={e => setEndTime(e.target.value)} required className="input w-full" />
            </div>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.mpFieldSpeaker}</label>
              <input value={speaker} onChange={e => setSpeaker(e.target.value)} className="input w-full" placeholder="Ustaz Ahmad" />
            </div>
            <div>
              <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.mpFieldLocation}</label>
              <input value={location} onChange={e => setLocation(e.target.value)} className="input w-full" placeholder="Dewan Utama" />
            </div>
          </div>
          <div>
            <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.mpFieldDesc}</label>
            <textarea value={desc} onChange={e => setDesc(e.target.value)} rows={2} className="input w-full resize-none" placeholder="Penerangan singkat..." />
          </div>
          <label className="flex items-center gap-2 cursor-pointer select-none">
            <input type="checkbox" checked={isRecurring} onChange={e => setIsRecurring(e.target.checked)} className="w-4 h-4 accent-primary rounded" />
            <span className="text-sm text-text">{t.mpFieldRecurring}</span>
          </label>
          {isRecurring && (
            <div>
              <label className="block text-xs font-semibold text-text-muted uppercase tracking-wider mb-1.5">{t.mpFieldRecurrenceNote}</label>
              <input value={recurrenceNote} onChange={e => setRecurrenceNote(e.target.value)} className="input w-full" placeholder="Setiap malam Ramadan" />
            </div>
          )}
          <button type="submit" disabled={saving}
            className="w-full py-3 bg-primary hover:bg-primary-dark text-white font-bold rounded-xl transition-all flex items-center justify-center gap-2 disabled:opacity-60">
            {saving ? <><Loader2 size={16} className="animate-spin" /> {t.saving}</> : isEdit ? t.save : t.mpAddProgram}
          </button>
        </form>
      </div>
    </div>
  );
}

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
/* ProgramsManagementCard                              */
/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
export interface ProgramsManagementCardProps {
  programs: MosqueProgram[];
  onRefresh: () => void;
}

export default function ProgramsManagementCard({ programs, onRefresh }: ProgramsManagementCardProps) {
  const { t } = useLanguage();
  const [showModal, setShowModal] = useState(false);
  const [editingProgram, setEditingProgram] = useState<MosqueProgram | null>(null);
  const [deletingProgram, setDeletingProgram] = useState<MosqueProgram | null>(null);
  const [togglingId, setTogglingId] = useState<string | null>(null);

  /* ΓöÇΓöÇ Toggle is_active ΓöÇΓöÇ */
  const handleToggle = async (prog: MosqueProgram) => {
    setTogglingId(prog.id);
    const supabase = createClient();
    const { error } = await supabase
      .from("mosque_programs")
      .update({ is_active: !prog.is_active })
      .eq("id", prog.id);
    setTogglingId(null);
    if (error) toast.error(error.message);
    else onRefresh();
  };

  /* ΓöÇΓöÇ Delete ΓöÇΓöÇ */
  const handleDelete = async () => {
    if (!deletingProgram) return;
    const supabase = createClient();
    const { error } = await supabase.from("mosque_programs").delete().eq("id", deletingProgram.id);
    if (error) toast.error(error.message);
    else { toast.success(t.mpDeleted); onRefresh(); }
    setDeletingProgram(null);
  };

  const sorted = [...programs].sort((a, b) =>
    a.program_date === b.program_date
      ? a.start_time.localeCompare(b.start_time)
      : a.program_date.localeCompare(b.program_date)
  );

  return (
    <div className="card col-span-1 lg:col-span-2">
      {/* Card header */}
      <div className="flex items-center justify-between p-5 border-b border-border/60">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl bg-primary/10 flex items-center justify-center text-primary">
            <CalendarDays size={18} />
          </div>
          <div>
            <h2 className="font-bold text-text text-base">{t.adminPrograms}</h2>
            <p className="text-xs text-text-muted">{t.adminProgramsDesc}</p>
          </div>
        </div>
        <button
          onClick={() => { setEditingProgram(null); setShowModal(true); }}
          className="flex items-center gap-1.5 px-3.5 py-2 bg-primary hover:bg-primary-dark text-white text-xs font-bold rounded-xl transition-all shadow-sm hover:shadow-md"
        >
          <Plus size={14} /> {t.mpAddProgram}
        </button>
      </div>

      {/* Program list */}
      <div className="divide-y divide-border/50 max-h-[480px] overflow-y-auto">
        {sorted.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-14 gap-3 text-text-muted">
            <div className="w-12 h-12 rounded-xl bg-surface-alt border border-border flex items-center justify-center">
              <Radio size={20} className="text-text-muted/40" />
            </div>
            <p className="text-sm font-medium">{t.adminProgramsEmpty}</p>
          </div>
        ) : (
          sorted.map(prog => (
            <div
              key={prog.id}
              className={`flex items-center gap-3 px-5 py-3.5 hover:bg-surface-alt/30 transition-colors ${!prog.is_active ? "opacity-50" : ""}`}
            >
              {/* Date + type */}
              <div className="flex flex-col items-center w-14 flex-shrink-0 text-center">
                <span className="text-[10px] font-bold text-text-muted uppercase leading-none">
                  {new Date(prog.program_date + "T00:00").toLocaleDateString(undefined, { month: "short" })}
                </span>
                <span className="text-xl font-extrabold text-text leading-tight">
                  {new Date(prog.program_date + "T00:00").getDate()}
                </span>
              </div>

              {/* Main info */}
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-1.5 mb-0.5 flex-wrap">
                  <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded-full ${typeColor(prog.program_type)}`}>
                    {typeLabel(prog.program_type, t)}
                  </span>
                  {!prog.is_active && (
                    <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-gray-100 text-gray-500 dark:bg-gray-800 dark:text-gray-400">
                      {t.mpInactive}
                    </span>
                  )}
                </div>
                <p className="text-sm font-semibold text-text truncate">{prog.title}</p>
                {prog.speaker && (
                  <p className="text-xs text-text-muted truncate">{prog.speaker}</p>
                )}
              </div>

              {/* Actions */}
              <div className="flex items-center gap-1.5 flex-shrink-0">
                {/* Toggle */}
                <button
                  onClick={() => handleToggle(prog)}
                  disabled={togglingId === prog.id}
                  className={`p-1.5 rounded-lg transition-colors ${
                    prog.is_active
                      ? "text-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-900/20"
                      : "text-gray-400 hover:bg-surface-alt"
                  }`}
                  title={prog.is_active ? "Deactivate" : "Activate"}
                >
                  {togglingId === prog.id
                    ? <Loader2 size={14} className="animate-spin" />
                    : prog.is_active ? <ToggleRight size={18} /> : <ToggleLeft size={18} />
                  }
                </button>
                {/* Edit */}
                <button
                  onClick={() => { setEditingProgram(prog); setShowModal(true); }}
                  className="p-1.5 rounded-lg text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors"
                  title={t.edit}
                >
                  <Pencil size={14} />
                </button>
                {/* Delete */}
                <button
                  onClick={() => setDeletingProgram(prog)}
                  className="p-1.5 rounded-lg text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
                  title={t.delete}
                >
                  <Trash2 size={14} />
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Add / Edit Modal */}
      {showModal && (
        <ProgramModal
          program={editingProgram}
          onClose={() => { setShowModal(false); setEditingProgram(null); }}
          onSaved={() => { setShowModal(false); setEditingProgram(null); onRefresh(); }}
          t={t}
        />
      )}

      {/* Delete confirm */}
      {deletingProgram && (
        <div
          className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm"
          onClick={() => setDeletingProgram(null)}
        >
          <div
            className="bg-surface rounded-2xl shadow-xl max-w-sm w-full border border-border/60"
            onClick={e => e.stopPropagation()}
          >
            <div className="flex items-center justify-between px-5 py-4 border-b border-border/60">
              <h2 className="font-bold text-text">{t.mpDeleteTitle}</h2>
              <button
                onClick={() => setDeletingProgram(null)}
                className="p-1.5 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20 text-text-muted hover:text-red-500 transition-colors"
              >
                <X size={18} />
              </button>
            </div>
            <div className="p-5">
              <p className="text-sm text-text-secondary mb-2">{t.mpDeleteConfirm}</p>
              <p className="font-semibold text-text mb-5">"{deletingProgram.title}"</p>
              <div className="flex gap-3">
                <button
                  onClick={() => setDeletingProgram(null)}
                  className="flex-1 py-2.5 rounded-xl border border-border text-text-secondary text-sm hover:bg-background transition-colors"
                >
                  {t.cancel}
                </button>
                <button
                  onClick={handleDelete}
                  className="flex-1 py-2.5 rounded-xl bg-red-500 hover:bg-red-600 text-white font-semibold text-sm transition-colors"
                >
                  {t.delete}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { Bell, Loader2, CheckCircle2, XCircle } from "lucide-react";
import toast from "react-hot-toast";

const PRAYER_OPTIONS = [
  { key: "fajr",    label: "Subuh (Fajr)" },
  { key: "dhuhr",   label: "Zohor (Dhuhr)" },
  { key: "asr",     label: "Asar (Asr)" },
  { key: "maghrib", label: "Maghrib" },
  { key: "isha",    label: "Isyak (Isha)" },
];

export default function PushNotificationTestCard() {
  const [sending, setSending] = useState<string | null>(null);
  const [lastResult, setLastResult] = useState<{ key: string; sent: number } | null>(null);

  const sendTest = async (prayerKey: string) => {
    setSending(prayerKey);
    setLastResult(null);
    try {
      const res = await fetch("/api/notifications/azan", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ prayerKey }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || "Failed");
      setLastResult({ key: prayerKey, sent: json.sent ?? 0 });
      toast.success(`Push sent to ${json.sent} device(s)`);
    } catch (err: any) {
      toast.error(err.message || "Push failed");
    } finally {
      setSending(null);
    }
  };

  return (
    <div className="card p-5 flex flex-col gap-4">
      <div className="flex items-center gap-3">
        <div className="icon-box icon-box-primary"><Bell size={18} /></div>
        <div>
          <h2 className="text-base font-bold text-text">Push Notification Test</h2>
          <p className="text-xs text-text-muted">Send a test azan push to all registered devices</p>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-2">
        {PRAYER_OPTIONS.map(({ key, label }) => {
          const isSending = sending === key;
          const isSuccess = lastResult?.key === key;
          return (
            <button
              key={key}
              onClick={() => sendTest(key)}
              disabled={!!sending}
              className="flex items-center justify-between px-4 py-2.5 rounded-xl border border-border bg-surface hover:bg-surface-muted disabled:opacity-50 transition-all text-sm font-medium text-text group"
            >
              <span>{label}</span>
              <span className="flex items-center gap-2 text-xs text-text-muted">
                {isSending && <Loader2 size={14} className="animate-spin text-primary" />}
                {!isSending && isSuccess && (
                  <span className="flex items-center gap-1 text-emerald-500">
                    <CheckCircle2 size={14} /> {lastResult.sent} sent
                  </span>
                )}
                {!isSending && !isSuccess && (
                  <Bell size={13} className="opacity-40 group-hover:opacity-100 transition" />
                )}
              </span>
            </button>
          );
        })}
      </div>

      {lastResult && (
        <p className="text-xs text-text-muted text-center">
          Last: <span className="font-semibold text-primary">
            {PRAYER_OPTIONS.find(p => p.key === lastResult.key)?.label}
          </span> ΓåÆ {lastResult.sent} device(s) notified
        </p>
      )}
    </div>
  );
}

"use client";
/**
 * SkrinMasjidEditor ΓÇö mosque display screen configurator.
 * Moved out of admin/page.tsx to keep the page thin.
 * Includes the SortableSlideItem sub-component.
 */
import { useState, useEffect } from "react";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  type DragEndEvent,
} from "@dnd-kit/core";
import {
  SortableContext,
  rectSortingStrategy,
  useSortable,
  arrayMove,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import {
  Monitor,
  ExternalLink,
  Upload,
  ImageIcon,
  LocateFixed,
  GripVertical,
  Trash2,
  Loader2,
  LayoutGrid,
  LayoutList,
} from "lucide-react";
import { useLanguage } from "@/components/providers/LanguageContext";
import { createClient } from "@/lib/supabase/client";
import type { ScreenConfig, ScreenSlide } from "@/hooks/useScreenConfig";
import { DEFAULT_SCREEN_CONFIG } from "@/hooks/useScreenConfig";
import { toast } from "react-hot-toast";

// ΓöÇΓöÇ Module list ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const MODULE_LIST: { key: keyof ScreenConfig; labelKey: string; descKey: string }[] = [
  { key: "gambar_masjid", labelKey: "skrinGambar",     descKey: "skrinGambarDesc"     },
  { key: "alert_masuk",   labelKey: "skrinAlertMasuk", descKey: "skrinAlertMasukDesc" },
  { key: "alert_iqamat",  labelKey: "skrinIqamat",     descKey: "skrinIqamatDesc"     },
  { key: "slideshow",     labelKey: "skrinSlideshow",  descKey: "skrinSlideshowDesc"  },
  { key: "panel_waktu",   labelKey: "skrinPanelWaktu", descKey: "skrinPanelWaktuDesc" },
  { key: "bunyi_azan",    labelKey: "skrinAzan",       descKey: "skrinAzanDesc"       },
  { key: "ticker",        labelKey: "skrinTicker",     descKey: "skrinTickerDesc"     },
];

// ΓöÇΓöÇ SortableSlideItem ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function SortableSlideItem({
  slide,
  onDelete,
}: {
  slide: ScreenSlide;
  onDelete: (s: ScreenSlide) => void;
}) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: slide.id });

  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.4 : 1,
    zIndex: isDragging ? 50 : undefined,
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      className="relative rounded-xl overflow-hidden border border-border group"
    >
      <button
        {...attributes}
        {...listeners}
        className="absolute top-1.5 left-1.5 z-10 bg-black/50 text-white rounded-full p-1 opacity-0 group-hover:opacity-100 transition cursor-grab active:cursor-grabbing"
      >
        <GripVertical size={11} />
      </button>
      <img
        src={slide.url}
        alt={slide.caption}
        className="w-full h-24 object-cover"
      />
      {slide.caption && (
        <p className="text-xs text-text-muted px-2 py-1 truncate bg-surface">
          {slide.caption}
        </p>
      )}
      <button
        onClick={() => onDelete(slide)}
        className="absolute top-1.5 right-1.5 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover:opacity-100 transition"
      >
        <Trash2 size={11} />
      </button>
    </div>
  );
}

// ΓöÇΓöÇ SkrinMasjidEditor ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export default function SkrinMasjidEditor() {
  const { t, language } = useLanguage();
  const supabase = createClient();

  const [cfg, setCfg] = useState<ScreenConfig>(DEFAULT_SCREEN_CONFIG);
  const [slides, setSlides] = useState<ScreenSlide[]>([]);
  const [loadingCfg, setLoadingCfg] = useState(true);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } })
  );

  const [photoUploading, setPhotoUploading] = useState(false);
  const [slideFile, setSlideFile] = useState<File | null>(null);
  const [slideCaption, setSlideCaption] = useState("");
  const [slideUploading, setSlideUploading] = useState(false);
  const [iqamatDelay, setIqamatDelay] = useState(cfg.alert_iqamat.delay_minutes);
  const [slideInterval, setSlideInterval] = useState(cfg.slideshow.interval_seconds);

  useEffect(() => {
    const load = async () => {
      const [sRes, slRes] = await Promise.all([
        supabase
          .from("system_settings")
          .select("screen_config")
          .eq("id", 1)
          .single(),
        supabase.from("screen_slides").select("*").order("sort_order"),
      ]);
      if (sRes.data?.screen_config) {
        const merged = { ...DEFAULT_SCREEN_CONFIG, ...sRes.data.screen_config };
        setCfg(merged);
        setIqamatDelay(merged.alert_iqamat.delay_minutes);
        setSlideInterval(merged.slideshow.interval_seconds);
      }
      if (slRes.data) setSlides(slRes.data);
      setLoadingCfg(false);
    };
    load();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const savePartial = async (partial: Partial<ScreenConfig>) => {
    const updated = { ...cfg, ...partial };
    setCfg(updated);
    await supabase
      .from("system_settings")
      .update({ screen_config: updated })
      .eq("id", 1);
  };

  const toggleModule = async (key: keyof ScreenConfig) => {
    const module = cfg[key] as Record<string, unknown>;
    await savePartial({ [key]: { ...module, enabled: !module.enabled } });
  };

  const handlePhotoUpload = async (file: File) => {
    setPhotoUploading(true);
    try {
      const ext = file.name.split(".").pop();
      const fileName = `mosque-bg-${Date.now()}.${ext}`;
      const { data: uploadData, error } = await supabase.storage
        .from("screen-assets")
        .upload(fileName, file, { upsert: true });
      if (error) {
        toast.error("Upload failed.");
        return;
      }
      const {
        data: { publicUrl },
      } = supabase.storage.from("screen-assets").getPublicUrl(uploadData.path);
      await savePartial({ gambar_masjid: { ...cfg.gambar_masjid, url: publicUrl } });
      toast.success("Mosque photo updated!");
    } finally {
      setPhotoUploading(false);
    }
  };

  const handleSlideUpload = async () => {
    if (!slideFile) return;
    setSlideUploading(true);
    try {
      const ext = slideFile.name.split(".").pop();
      const fileName = `slide-${Date.now()}.${ext}`;
      const { data: uploadData, error } = await supabase.storage
        .from("screen-slides")
        .upload(fileName, slideFile);
      if (error) {
        toast.error("Slide upload failed.");
        return;
      }
      const {
        data: { publicUrl },
      } = supabase.storage
        .from("screen-slides")
        .getPublicUrl(uploadData.path);
      const { data: newSlide } = await supabase
        .from("screen_slides")
        .insert({
          url: publicUrl,
          caption: slideCaption.trim(),
          sort_order: slides.length,
        })
        .select()
        .single();
      if (newSlide) setSlides((prev) => [...prev, newSlide]);
      setSlideFile(null);
      setSlideCaption("");
      toast.success("Slide added!");
    } finally {
      setSlideUploading(false);
    }
  };

  const handleDeleteSlide = async (slide: ScreenSlide) => {
    await supabase.from("screen_slides").delete().eq("id", slide.id);
    setSlides((prev) => prev.filter((s) => s.id !== slide.id));
    toast.success("Slide removed.");
  };

  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id) return;
    const oldIdx = slides.findIndex((s) => s.id === active.id);
    const newIdx = slides.findIndex((s) => s.id === over.id);
    const reordered = arrayMove(slides, oldIdx, newIdx);
    setSlides(reordered);
    await Promise.all(
      reordered.map((s, i) =>
        supabase.from("screen_slides").update({ sort_order: i }).eq("id", s.id)
      )
    );
  };

  const [zoneDetecting, setZoneDetecting] = useState(false);
  const detectZone = async () => {
    if (!navigator.geolocation) {
      toast.error("Geolocation tidak disokong.");
      return;
    }
    setZoneDetecting(true);
    navigator.geolocation.getCurrentPosition(
      async ({ coords }) => {
        try {
          const res = await fetch(
            `https://api.waktusolat.app/zones/${coords.latitude}/${coords.longitude}`
          );
          const data: { zone: string; district: string } = await res.json();
          if (!data.zone) throw new Error("no zone");
          const updated = { ...cfg, zone: data.zone };
          setCfg(updated);
          await supabase
            .from("system_settings")
            .update({ screen_config: updated })
            .eq("id", 1);
          toast.success(`Zon dikesan: ${data.zone} (${data.district})`);
        } catch {
          toast.error("Gagal mengesan zon. Cuba lagi.");
        } finally {
          setZoneDetecting(false);
        }
      },
      () => {
        toast.error("Akses lokasi ditolak.");
        setZoneDetecting(false);
      }
    );
  };

  if (loadingCfg) {
    return (
      <div className="card p-6 flex items-center gap-2 text-text-muted text-sm">
        <Loader2 size={16} className="animate-spin" /> Loading screen settingsΓÇª
      </div>
    );
  }

  return (
    <div className="card p-6 space-y-6">
      {/* Header */}
      <div className="flex items-start justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="icon-box icon-box-primary"><Monitor size={20} /></div>
          <div>
            <h2 className="font-bold text-lg text-text">{t.skrinTitle}</h2>
            <p className="text-sm text-text-muted mt-0.5">{t.skrinDesc}</p>
          </div>
        </div>
        <a
          href="/paparan-masjid"
          target="_blank"
          rel="noopener noreferrer"
          className="flex items-center gap-1.5 text-xs font-semibold text-primary border border-primary/30 rounded-lg px-3 py-2 hover:bg-primary/10 transition whitespace-nowrap"
        >
          <ExternalLink size={13} /> {t.skrinOpenDisplay}
        </a>
      </div>

      {/* Live Preview */}
      <div>
        <label className="text-xs font-bold uppercase tracking-widest text-text-secondary mb-2 block">
          Live Preview
        </label>
        <div
          className="relative overflow-hidden rounded-2xl border border-border bg-black"
          style={{ height: 165 }}
        >
          <iframe
            src="/paparan-masjid"
            className="absolute top-0 left-0 pointer-events-none border-0"
            style={{
              width: "334%",
              height: "334%",
              transform: "scale(0.3)",
              transformOrigin: "top left",
            }}
          />
        </div>
      </div>

      {/* Zone Selector */}
      <div>
        <label className="text-xs font-bold uppercase tracking-widest text-text-secondary mb-1 block">
          {t.skrinZone}
        </label>
        <div className="flex items-center gap-2">
          <input
            type="text"
            value={cfg.zone}
            onChange={(e) => setCfg((prev) => ({ ...prev, zone: e.target.value }))}
            onBlur={() => savePartial({ zone: cfg.zone })}
            placeholder="e.g. WLY01, SGR01"
            className="flex-1 border border-border rounded-xl px-3 py-2 text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none bg-background"
          />
          <button
            onClick={detectZone}
            disabled={zoneDetecting}
            title="Kesan zon dari lokasi anda"
            className="flex items-center gap-1.5 px-3 py-2 rounded-xl border border-border text-sm text-text-secondary hover:border-primary hover:text-primary transition disabled:opacity-50"
          >
            {zoneDetecting ? (
              <Loader2 size={14} className="animate-spin" />
            ) : (
              <LocateFixed size={14} />
            )}
            {zoneDetecting ? "ΓÇª" : "Auto"}
          </button>
        </div>
      </div>

      {/* Module Toggles */}
      <div className="rounded-2xl border border-border overflow-hidden divide-y divide-border">
        {MODULE_LIST.map(({ key, labelKey, descKey }) => {
          const module = cfg[key] as Record<string, unknown>;
          const enabled = Boolean(module?.enabled);
          return (
            <div
              key={key}
              className="flex items-center justify-between p-4 bg-surface"
            >
              <div>
                <p className="text-sm font-semibold text-text">
                  {(t as Record<string, unknown>)[labelKey] as string}
                </p>
                <p className="text-xs text-text-muted mt-0.5">
                  {(t as Record<string, unknown>)[descKey] as string}
                </p>
              </div>
              <button
                onClick={() => toggleModule(key)}
                className={`w-12 h-6 rounded-full flex items-center p-1 transition-colors ${
                  enabled
                    ? "bg-primary justify-end"
                    : "bg-border justify-start"
                }`}
              >
                <div className="w-4 h-4 bg-white rounded-full shadow-sm" />
              </button>
            </div>
          );
        })}
      </div>

      {/* Mosque Photo Upload */}
      {cfg.gambar_masjid.enabled && (
        <div className="space-y-2">
          <label className="text-xs font-bold uppercase tracking-widest text-text-secondary block">
            {t.skrinUploadPhoto}
          </label>
          {cfg.gambar_masjid.url && (
            <img
              src={cfg.gambar_masjid.url}
              alt="Mosque"
              className="w-full h-36 object-cover rounded-xl border border-border"
            />
          )}
          <div className="flex items-center gap-3">
            <label className="flex-1 flex items-center justify-center gap-2 py-2.5 border-2 border-dashed border-border rounded-xl text-sm text-text-muted hover:border-primary hover:text-primary transition cursor-pointer">
              {photoUploading ? (
                <Loader2 size={15} className="animate-spin" />
              ) : (
                <Upload size={15} />
              )}
              {photoUploading ? t.skrinUploading : t.skrinUploadPhoto}
              <input
                type="file"
                accept="image/*"
                className="hidden"
                onChange={(e) => {
                  const f = e.target.files?.[0];
                  if (f) handlePhotoUpload(f);
                }}
              />
            </label>
          </div>
        </div>
      )}

      {/* Iqamat Delay */}
      {cfg.alert_iqamat.enabled && (
        <div>
          <label className="text-xs font-bold uppercase tracking-widest text-text-secondary mb-1 block">
            {t.skrinIqamatDelay}
          </label>
          <div className="flex items-center gap-3">
            <input
              type="number"
              min={1}
              max={60}
              value={iqamatDelay}
              onChange={(e) => setIqamatDelay(Number(e.target.value))}
              className="w-24 border border-border rounded-xl px-3 py-2 text-sm outline-none focus:border-primary bg-background"
            />
            <button
              onClick={() =>
                savePartial({
                  alert_iqamat: {
                    ...cfg.alert_iqamat,
                    delay_minutes: iqamatDelay,
                  },
                })
              }
              className="py-2 px-4 btn-primary text-sm"
            >
              {t.skrinSaveSettings}
            </button>
          </div>
        </div>
      )}

      {/* Panel Waktu Layout */}
      {cfg.panel_waktu.enabled && (
        <div>
          <label className="text-xs font-bold uppercase tracking-widest text-text-secondary mb-2 block">
            {language === "en"
              ? "Prayer Time Panel Layout"
              : "Susun Atur Panel Waktu Solat"}
          </label>
          <div className="flex gap-2">
            {(["horizontal", "vertical"] as const).map((opt) => {
              const active = (cfg.panel_waktu.layout ?? "horizontal") === opt;
              return (
                <button
                  key={opt}
                  onClick={() =>
                    savePartial({
                      panel_waktu: { ...cfg.panel_waktu, layout: opt },
                    })
                  }
                  className={`flex items-center gap-2 flex-1 justify-center py-2.5 rounded-xl border text-sm font-semibold transition ${
                    active
                      ? "bg-primary text-white border-primary"
                      : "border-border text-text-secondary hover:border-primary hover:text-primary"
                  }`}
                >
                  {opt === "horizontal" ? (
                    <LayoutGrid size={15} />
                  ) : (
                    <LayoutList size={15} />
                  )}
                  {opt === "horizontal"
                    ? language === "en"
                      ? "Horizontal"
                      : "Mendatar"
                    : language === "en"
                    ? "Vertical"
                    : "Menegak"}
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* Slideshow Interval */}
      {cfg.slideshow.enabled && (
        <div>
          <label className="text-xs font-bold uppercase tracking-widest text-text-secondary mb-1 block">
            {t.skrinSlideInterval}
          </label>
          <div className="flex items-center gap-3">
            <input
              type="number"
              min={3}
              max={120}
              value={slideInterval}
              onChange={(e) => setSlideInterval(Number(e.target.value))}
              className="w-24 border border-border rounded-xl px-3 py-2 text-sm outline-none focus:border-primary bg-background"
            />
            <button
              onClick={() =>
                savePartial({
                  slideshow: {
                    ...cfg.slideshow,
                    interval_seconds: slideInterval,
                  },
                })
              }
              className="py-2 px-4 btn-primary text-sm"
            >
              {t.skrinSaveSettings}
            </button>
          </div>
        </div>
      )}

      {/* Slide Manager */}
      {cfg.slideshow.enabled && (
        <div className="space-y-3">
          <p className="text-xs font-bold uppercase tracking-widest text-text-secondary">
            {t.skrinSlideshow}
          </p>

          {slides.length === 0 ? (
            <p className="text-sm text-text-muted text-center py-6 rounded-xl border border-dashed border-border">
              {t.skrinNoSlides}
            </p>
          ) : (
            <DndContext
              sensors={sensors}
              collisionDetection={closestCenter}
              onDragEnd={handleDragEnd}
            >
              <SortableContext
                items={slides.map((s) => s.id)}
                strategy={rectSortingStrategy}
              >
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                  {slides.map((slide) => (
                    <SortableSlideItem
                      key={slide.id}
                      slide={slide}
                      onDelete={handleDeleteSlide}
                    />
                  ))}
                </div>
              </SortableContext>
            </DndContext>
          )}

          {/* Upload new slide */}
          <div className="rounded-xl border border-dashed border-border p-4 space-y-3">
            <div className="flex items-center gap-2 mb-1">
              <ImageIcon size={14} className="text-text-muted" />
              <span className="text-xs font-semibold text-text-secondary uppercase tracking-wider">
                {t.skrinUploadSlide}
              </span>
            </div>
            <label className="flex items-center justify-center gap-2 py-2 border border-border rounded-xl text-sm text-text-muted hover:border-primary hover:text-primary transition cursor-pointer w-full">
              <Upload size={14} />
              {slideFile ? slideFile.name : t.skrinUploadSlide}
              <input
                type="file"
                accept="image/*"
                className="hidden"
                onChange={(e) => setSlideFile(e.target.files?.[0] ?? null)}
              />
            </label>
            <input
              type="text"
              value={slideCaption}
              onChange={(e) => setSlideCaption(e.target.value)}
              placeholder={t.skrinSlideCaption}
              className="w-full border border-border rounded-xl px-3 py-2 text-sm outline-none focus:border-primary bg-background"
            />
            <button
              onClick={handleSlideUpload}
              disabled={!slideFile || slideUploading}
              className="w-full py-2.5 btn-primary text-sm flex justify-center gap-2 disabled:opacity-50"
            >
              {slideUploading ? (
                <Loader2 size={15} className="animate-spin" />
              ) : (
                <Upload size={15} />
              )}
              {slideUploading ? t.skrinUploading : t.skrinAddSlide}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

