"use client";

import { MapContainer, TileLayer, Marker, Popup, useMap, useMapEvents } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from "leaflet";
import { useEffect, useState, useMemo, useCallback } from "react";
import { Navigation, X, Plus, Search, Loader2 } from "lucide-react";
import { toast } from "react-hot-toast";

const createCustomIcon = (color: string, pulse = false) => {
  const pulseRing = pulse
    ? `<div style="position:absolute;top:-6px;left:-6px;width:32px;height:32px;border-radius:50%;background:${color}44;animation:mapPulse 1.5s ease-out infinite;"></div>`
    : "";
  return L.divIcon({
    className: "custom-div-icon",
    html: `<div style="position:relative;width:20px;height:20px;">
      ${pulseRing}
      <div style="position:relative;background-color:${color};width:20px;height:20px;border-radius:50%;border:3px solid white;box-shadow:0 0 6px rgba(0,0,0,0.4);z-index:2;"></div>
    </div>
    <style>@keyframes mapPulse{0%{transform:scale(1);opacity:.7}100%{transform:scale(2.2);opacity:0}}</style>`,
    iconSize: [20, 20],
    iconAnchor: [10, 10],
    popupAnchor: [0, -10],
  });
};

const redPulseIcon = createCustomIcon("#DC2626", true);     // Active booths
const yellowPulseIcon = createCustomIcon("#D4A843", true);  // Scheduled booths
const goldIcon = createCustomIcon("#D4A843");               // New counter preview
const bluePulseIcon = createCustomIcon("#3B82F6", true);    // User's physical location

interface Location {
  id: string;
  name: string;
  lat: number;
  lng: number;
  status: "active" | "scheduled" | "expired";
  address: string;
  start_date?: string;
  end_date?: string;
  start_time?: string;
  end_time?: string;
}

function MapUpdater({ center, trigger }: { center: [number, number], trigger: number }) {
  const map = useMap();
  const [prevTrigger, setPrevTrigger] = useState(0);

  useEffect(() => {
    if (trigger > prevTrigger) {
      map.flyTo(center, 15, { animate: true, duration: 1.5 });
      setPrevTrigger(trigger);
    }
  }, [center, map, trigger, prevTrigger]);
  return null;
}

// Component to capture map clicks for pin placement
function MapClickHandler({ onMapClick }: { onMapClick: (lat: number, lng: number) => void }) {
  useMapEvents({
    click(e) {
      onMapClick(e.latlng.lat, e.latlng.lng);
    },
  });
  return null;
}

// Component to search map locations via OpenStreetMap Nominatim
function MapSearchControl() {
  const map = useMap();
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<any[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [showResults, setShowResults] = useState(false);
  const [searchedPin, setSearchedPin] = useState<{ lat: number, lng: number, name: string } | null>(null);

  // Debounced search effect
  useEffect(() => {
    // Only search if user has typed at least 3 characters
    if (query.trim().length < 3) {
      setResults([]);
      // Don't auto-hide if they are just clearing out the box, but if it's empty hide it:
      if (query.trim() === "") setShowResults(false);
      return;
    }

    const delayDebounceFn = setTimeout(async () => {
      setIsSearching(true);
      setShowResults(true);
      try {
        // Nominatim API - note: we add '* ' wildcard or rely on the base behaviour. 
        // Nominatim isn't a perfect autocomplete engine, but q=... will try partial matches of words
        // Appending 'Malaysia' heavily improves local scope results for partial place names like "Masjid Padang Midin"
        const finalQuery = query.toLowerCase().includes('malaysia') ? query : `${query} Malaysia`;
        const res = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(finalQuery)}&limit=8&countrycodes=my`);
        const data = await res.json();
        setResults(data);
      } catch (err) {
        console.error("Search failed", err);
      } finally {
        setIsSearching(false);
      }
    }, 600); // 600ms debounce to respect Nominatim's strict usage policy (1 req/sec)

    return () => clearTimeout(delayDebounceFn);
  }, [query]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    // The useEffect handles the fetching, this just stops page reload on Enter
  };

  const handleSelect = (lat: string, lon: string, name: string) => {
    try {
      if (map) {
        map.flyTo([parseFloat(lat), parseFloat(lon)], 16, { duration: 1.5 });
        setSearchedPin({ lat: parseFloat(lat), lng: parseFloat(lon), name });
      }
    } catch (e) {
      console.warn("Map not ready for flyTo", e);
    }
    setShowResults(false);
    setQuery("");
  };

  return (
    <>
      <div className="absolute top-4 left-1/2 -translate-x-1/2 z-[400] w-[90%] max-w-sm">
        <form onSubmit={handleSearch} className="relative">
          <input
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search world map (e.g. Kuala Lumpur)..."
            className="w-full bg-surface text-sm rounded-full pl-10 pr-4 py-3 shadow-[0_4px_12px_rgba(0,0,0,0.15)] outline-none border border-border focus:ring-2 focus:ring-primary/20 focus:border-primary transition"
          />
          <button type="submit" className="absolute left-3 top-3 text-text-secondary hover:text-primary">
            {isSearching ? <Loader2 size={18} className="animate-spin text-primary" /> : <Search size={18} />}
          </button>
          {query && (
            <button type="button" onClick={() => { setQuery(""); setShowResults(false); }} className="absolute right-3 top-3.5 text-text-muted hover:text-red-500">
              <X size={14} />
            </button>
          )}
        </form>

        {showResults && results.length > 0 && (
          <div className="absolute top-full left-0 w-full mt-2 bg-surface rounded-xl shadow-[0_10px_30px_rgba(0,0,0,0.15)] border border-border overflow-hidden">
            {results.map((r, i) => (
              <button
                key={i}
                type="button"
                onClick={() => handleSelect(r.lat, r.lon, r.display_name)}
                className="w-full text-left px-4 py-3 border-b last:border-0 border-border hover:bg-background flex items-start gap-2 transition"
              >
                <Navigation size={14} className="mt-0.5 text-primary shrink-0" />
                <span className="text-xs text-text-secondary line-clamp-2">{r.display_name}</span>
              </button>
            ))}
          </div>
        )}
      </div>
      {searchedPin && (
        <Marker position={[searchedPin.lat, searchedPin.lng]} icon={goldIcon}>
          <Popup className="text-xs font-bold text-text">
            <div className="flex flex-col gap-2 p-1">
              <span>{searchedPin.name}</span>
              <button
                onClick={() => {
                  try {
                    const addBtn = document.getElementById("admin-add-counter-btn");
                    if (addBtn) addBtn.click();
                    setTimeout(() => {
                      const event = new MouseEvent("click", {
                        view: window,
                        bubbles: true,
                        cancelable: true,
                        clientX: 0,
                        clientY: 0,
                      });
                      // Emulate a map click hook passing these coords if possible,
                      // or we can invoke a global state.
                      // Since we can't easily trigger the map hook manually, let's expose a global window function.
                      if ((window as any).triggerMapAddPin) {
                        (window as any).triggerMapAddPin(searchedPin.lat, searchedPin.lng, searchedPin.name);
                      }
                    }, 50);
                  } catch (e) {
                    console.error(e);
                  }
                }}
                className="bg-primary hover:bg-primary-dark text-white text-[10px] px-2 py-1.5 rounded transition-colors w-full uppercase tracking-widest font-bold"
              >
                Add Counter Here
              </button>
            </div>
          </Popup>
        </Marker>
      )}
    </>
  );
}

// Component to locate user
function LocateControl({ onLocationFound }: { onLocationFound?: (lat: number, lng: number) => void }) {
  const map = useMap();
  const [locating, setLocating] = useState(false);

  const handleLocate = useCallback((e?: React.MouseEvent) => {
    // prevent default so it doesn't trigger map clicks
    if (e) {
      e.stopPropagation();
      e.preventDefault();
    }

    setLocating(true);
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setLocating(false);
          try {
            if (map) {
              map.flyTo([position.coords.latitude, position.coords.longitude], 16, { duration: 1.5 });
            }
          } catch (e) {
            console.warn("Map not ready for flyTo", e);
          }
          onLocationFound?.(position.coords.latitude, position.coords.longitude);
        },
        (error) => {
          setLocating(false);
          // Only alert if they manually clicked the button to avoid annoying popups on load if denied
          if (e) alert("Could not access your location. Please check your browser permissions.");
        },
        { enableHighAccuracy: true }
      );
    } else {
      setLocating(false);
      if (e) alert("Geolocation is not supported by your browser.");
    }
  }, [map, onLocationFound]);

  useEffect(() => {
    // Attempt to locate the user immediately on mount
    handleLocate();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="absolute bottom-6 right-4 z-[400] flex flex-col gap-2">
      <button
        onClick={handleLocate}
        title="My Current Location"
        className="bg-surface text-primary shadow-[0_4px_12px_rgba(0,0,0,0.15)] border border-border p-3 rounded-full hover:bg-background flex items-center justify-center transition-all hover:scale-105 active:scale-95"
      >
        <Navigation size={22} className={locating ? "animate-ping opacity-50" : ""} />
        <span className="ml-2 font-bold text-sm hidden md:inline">My Location</span>
      </button>
    </div>
  );
}

export default function Map({
  locations,
  activeLocationId,
  panTrigger,
  isAdmin,
  onAddCounter,
  onLocationFound,
  userLocationCoords,
}: {
  locations: Location[];
  activeLocationId: string | null;
  panTrigger?: number;
  isAdmin?: boolean;
  onAddCounter?: (loc: Location) => void;
  onLocationFound?: (lat: number, lng: number) => void;
  userLocationCoords?: { lat: number, lng: number } | null;
}) {
  const defaultCenter = useMemo<[number, number]>(() => [3.139, 101.6869], []);
  const activeLocation = locations.find((loc) => loc.id === activeLocationId);
  const center = useMemo(() => activeLocation ? ([activeLocation.lat, activeLocation.lng] as [number, number]) : defaultCenter, [activeLocation, defaultCenter]);

  const [addMode, setAddMode] = useState(false);
  const [pinCoords, setPinCoords] = useState<{ lat: number; lng: number } | null>(null);
  const [formName, setFormName] = useState("");
  const [formAddress, setFormAddress] = useState("");
  const [formPicName, setFormPicName] = useState("");
  const [formStartDate, setFormStartDate] = useState("");
  const [formEndDate, setFormEndDate] = useState("");
  const [formStartTime, setFormStartTime] = useState("");
  const [formEndTime, setFormEndTime] = useState("");

  useEffect(() => {
    (window as any).triggerMapAddPin = (lat: number, lng: number, name: string) => {
      if (!addMode) setAddMode(true);
      setPinCoords({ lat, lng });
      setFormAddress(name); // Auto-fill only the address with the formal search metadata
    };
    return () => {
      delete (window as any).triggerMapAddPin;
    };
  }, [addMode]);

  const handleMapClick = (lat: number, lng: number) => {
    if (!addMode) return;
    setPinCoords({ lat, lng });
  };

  const handleSubmit = () => {
    if (!pinCoords || !formName.trim() || !formStartDate || !formEndDate || !formStartTime || !formEndTime) return;
    
    // Validation: End must be after start
    const startDateTime = new Date(`${formStartDate}T${formStartTime.split('.')[0]}`);
    const endDateTime = new Date(`${formEndDate}T${formEndTime.split('.')[0]}`);
    
    if (endDateTime <= startDateTime) {
      toast.error("End date/time must be strictly after start date/time");
      return;
    }

    const now = new Date();
    
    const yyyy = now.getFullYear();
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const dd = String(now.getDate()).padStart(2, '0');
    const hr = String(now.getHours()).padStart(2, '0');
    const min = String(now.getMinutes()).padStart(2, '0');
    
    const currentDate = `${yyyy}-${mm}-${dd}`;
    const currentTime = `${hr}:${min}`;

    const isFuture = formStartDate > currentDate || (formStartDate === currentDate && formStartTime > currentTime);

    const newLoc: Location = {
      id: `new-${Date.now()}`,
      name: formName,
      lat: pinCoords.lat,
      lng: pinCoords.lng,
      status: isFuture ? "scheduled" : "active",
      address: formAddress || formName, // use typed address, or fallback to name
      start_date: formStartDate,
      end_date: formEndDate,
      start_time: `${formStartTime}:00`,
      end_time: `${formEndTime}:00`,
    };
    onAddCounter?.(newLoc);
    // Reset form
    setAddMode(false);
    setPinCoords(null);
    setFormName("");
    setFormAddress("");
    setFormPicName("");
    setFormStartDate("");
    setFormEndDate("");
    setFormStartTime("");
    setFormEndTime("");
  };

  const cancelAdd = () => {
    setAddMode(false);
    setPinCoords(null);
    setFormName("");
    setFormAddress("");
    setFormPicName("");
    setFormStartDate("");
    setFormEndDate("");
    setFormStartTime("");
    setFormEndTime("");
  };

  return (
    <div className="h-full w-full relative z-0">
      <MapContainer
        center={defaultCenter}
        zoom={13}
        scrollWheelZoom={true}
        style={{ height: "100%", width: "100%", zIndex: 0 }}
      >
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />

        {locations.map((loc) => (
          <Marker
            key={loc.id}
            position={[loc.lat, loc.lng]}
            icon={loc.status === "active" ? redPulseIcon : yellowPulseIcon}
          >
            <Popup>
              <div className="p-1">
                <h3 className="font-bold font-sans text-sm mb-1">{loc.name}</h3>
                <p className="text-xs text-slate-500 mb-3">{loc.address}</p>
                <a
                  href={`https://www.google.com/maps/dir/?api=1&destination=${loc.lat},${loc.lng}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="bg-primary hover:bg-primary-dark text-white w-full py-1.5 rounded flex items-center justify-center gap-1 text-xs transition-colors"
                >
                  <Navigation size={12} />
                  Get Directions
                </a>
              </div>
            </Popup>
          </Marker>
        ))}

        {/* Show pin preview when adding */}
        {pinCoords && (
          <Marker position={[pinCoords.lat, pinCoords.lng]} icon={goldIcon}>
            <Popup>
              <div className="p-1 text-xs text-center text-slate-500">
                ≡ƒôì New counter location
              </div>
            </Popup>
          </Marker>
        )}

        {/* Show user's actual location if known */}
        {userLocationCoords && (
          <Marker position={[userLocationCoords.lat, userLocationCoords.lng]} icon={bluePulseIcon}>
            <Popup>
              <div className="p-1 text-xs text-center font-bold text-blue-600">
                ≡ƒö╡ You are here
              </div>
            </Popup>
          </Marker>
        )}

        <MapUpdater center={center} trigger={panTrigger || 0} />
        {addMode && <MapClickHandler onMapClick={handleMapClick} />}
        <LocateControl onLocationFound={onLocationFound} />
        <MapSearchControl />
      </MapContainer>

      {/* ΓòÉΓòÉΓòÉ Admin: Add Counter button + form ΓòÉΓòÉΓòÉ */}
      {isAdmin && (
        <div className="absolute top-4 right-4 z-[400]">
          {!addMode ? (
            <button
              id="admin-add-counter-btn"
              onClick={() => setAddMode(true)}
              className="bg-surface text-primary shadow-lg border border-border px-4 py-2 rounded-full font-bold text-sm hover:shadow-xl transition-all flex items-center gap-2"
            >
              <Plus size={16} /> Add Counter
            </button>
          ) : (
            <div className="bg-surface rounded-2xl shadow-2xl border border-border w-72 overflow-hidden">
              <div className="hero-gradient px-4 py-3 text-white flex items-center justify-between">
                <span className="font-bold text-sm">Add Zakat Counter</span>
                <button onClick={cancelAdd} className="text-white/60 hover:text-white"><X size={16} /></button>
              </div>
              <div className="p-4 space-y-3">
                <p className="text-xs text-text-muted">
                  {pinCoords
                    ? `≡ƒôì ${pinCoords.lat.toFixed(4)}, ${pinCoords.lng.toFixed(4)}`
                    : "≡ƒæå Click on the map to place a pin"}
                </p>
                <div className="space-y-2 mb-2">
                  <input
                    type="text"
                    placeholder="Booth name (e.g., Masjid Al-Falah)"
                    value={formName}
                    onChange={(e) => setFormName(e.target.value)}
                    className="w-full px-3 py-2 border border-border rounded-lg text-sm focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none bg-background"
                  />
                  <input
                    type="text"
                    placeholder="Address / Location Details"
                    value={formAddress}
                    onChange={(e) => setFormAddress(e.target.value)}
                    className="w-full px-3 py-2 border border-border rounded-lg text-[13px] bg-background outline-none text-text-secondary"
                  />
                </div>
                <div className="grid grid-cols-2 gap-2">
                  <div className="space-y-1">
                    <label className="text-[10px] text-text-muted uppercase font-bold">Start Date</label>
                    <input type="date" min={new Date().toLocaleDateString('en-CA')} value={formStartDate} onChange={e => { setFormStartDate(e.target.value); if (formEndDate < e.target.value) setFormEndDate(e.target.value); }} className="w-full px-2 py-1.5 border border-border rounded-lg text-[13px] bg-background outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] text-text-muted uppercase font-bold">End Date</label>
                    <input type="date" min={formStartDate || new Date().toLocaleDateString('en-CA')} value={formEndDate} onChange={e => setFormEndDate(e.target.value)} className="w-full px-2 py-1.5 border border-border rounded-lg text-[13px] bg-background outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] text-text-muted uppercase font-bold">Start Time</label>
                    <input type="time" value={formStartTime} onChange={e => setFormStartTime(e.target.value)} className="w-full px-2 py-1.5 border border-border rounded-lg text-[13px] bg-background outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] text-text-muted uppercase font-bold">End Time</label>
                    <input type="time" value={formEndTime} onChange={e => setFormEndTime(e.target.value)} className="w-full px-2 py-1.5 border border-border rounded-lg text-[13px] bg-background outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary" />
                  </div>
                </div>
                <button
                  onClick={handleSubmit}
                  disabled={!pinCoords || !formName.trim() || !formStartDate || !formEndDate || !formStartTime || !formEndTime}
                  className="w-full py-2.5 btn-primary text-sm disabled:opacity-40"
                >
                  Save Counter
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Instruction overlay when in add mode */}
      {addMode && !pinCoords && (
        <div className="absolute top-4 left-4 z-[400] bg-slate-800 dark:bg-slate-200 text-white dark:text-slate-900 px-4 py-2 rounded-full text-sm font-medium shadow-lg animate-pulse">
          ≡ƒæå Click anywhere on the map to place the counter
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { createClient } from "@/lib/supabase/client";

export interface FoodEvent {
  id: string;
  name: string;
  total_capacity: number;
  remaining_capacity: number;
  event_date: string;
  start_time: string;
  end_time: string;
  location?: string;
  background_image?: string | null;
  status?: "active" | "scheduled" | "expired";
}

export function useLiveFoodEvents() {
  const [events, setEvents] = useState<FoodEvent[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const supabase = createClient();
    let mounted = true;

    // Safety timeout ΓÇö never show spinner for more than 4s
    // Use a mutable ref or check mounted flag to ensure it doesn't override real data
    const timeout = setTimeout(() => {
      // If we reach here, it hasn't been cleared by fetchEvents
      if (mounted) {
        console.warn("useLiveFoodEvents: timed out");
        setEvents([]);
        setIsLoading(false);
      }
    }, 4000);

    const fetchEvents = async () => {
      try {
        const { data, error } = await supabase
          .from("food_events")
          .select("*")
          .order("event_date", { ascending: true });

        if (!mounted) return;

        if (error) {
          console.error("Failed to fetch food_events:", error.message);
          setEvents([]);
        } else if (!data || data.length === 0) {
          setEvents([]);
        } else {
          const now = new Date();
          const yyyy = now.getFullYear();
          const mm = String(now.getMonth() + 1).padStart(2, '0');
          const dd = String(now.getDate()).padStart(2, '0');
          const hr = String(now.getHours()).padStart(2, '0');
          const min = String(now.getMinutes()).padStart(2, '0');
          const sec = String(now.getSeconds()).padStart(2, '0');

          const currentDate = `${yyyy}-${mm}-${dd}`;
          const currentTime = `${hr}:${min}:${sec}`;

          const parsedEvents = data.map((fe: any) => {
            let computedStatus: "active" | "scheduled" | "expired" = "active";

            if (fe.event_date && fe.start_time && fe.end_time) {
              const cleanStartTime = fe.start_time.split('.')[0];
              const cleanEndTime = fe.end_time.split('.')[0];

              if (fe.event_date < currentDate) {
                computedStatus = "expired";
              } else if (fe.event_date > currentDate) {
                computedStatus = "scheduled";
              } else {
                if (currentTime < cleanStartTime) computedStatus = "scheduled";
                else if (currentTime > cleanEndTime) computedStatus = "expired";
                else computedStatus = "active";
              }
            }

            return { ...fe, status: computedStatus } as FoodEvent;
          });

          // Filter out expired, and sort active on top
          const validEvents = parsedEvents
            .sort((a, b) => a.status === "active" && b.status !== "active" ? -1 : a.status !== "active" && b.status === "active" ? 1 : 0);

          setEvents(validEvents);
        }
      } catch (err) {
        console.error("useLiveFoodEvents error:", err);
        if (mounted) setEvents([]);
      }
      clearTimeout(timeout);
      if (mounted) setIsLoading(false);
    };

    fetchEvents();

    // Subscribe to real-time INSERT and UPDATE events so new events
    // and capacity changes appear instantly without a page refresh.
    const channel = supabase
      .channel("food_events_realtime")
      .on(
        "postgres_changes",
        { event: "INSERT", schema: "public", table: "food_events" },
        (payload) => {
          const newEvent = payload.new as any;
          // Compute status for newly inserted event using the same logic as fetchEvents
          const now = new Date();
          const currentDate = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
          const currentTime = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}:${String(now.getSeconds()).padStart(2, '0')}`;
          let computedStatus: "active" | "scheduled" | "expired" = "active";
          if (newEvent.event_date && newEvent.start_time && newEvent.end_time) {
            const cleanStart = newEvent.start_time.split('.')[0];
            const cleanEnd = newEvent.end_time.split('.')[0];
            if (newEvent.event_date < currentDate) computedStatus = "expired";
            else if (newEvent.event_date > currentDate) computedStatus = "scheduled";
            else if (currentTime < cleanStart) computedStatus = "scheduled";
            else if (currentTime > cleanEnd) computedStatus = "expired";
            else computedStatus = "active";
          }
          if (computedStatus !== "expired") {
            setEvents((prev) => [...prev, { ...newEvent, status: computedStatus }]);
          }
        }
      )
      .on(
        "postgres_changes",
        { event: "UPDATE", schema: "public", table: "food_events" },
        (payload) => {
          const updated = payload.new as FoodEvent;
          setEvents((prev) =>
            prev.map((e) => (e.id === updated.id ? { ...e, ...updated } : e))
          );
        }
      )
      .on(
        "postgres_changes",
        { event: "DELETE", schema: "public", table: "food_events" },
        (payload) => {
          setEvents((prev) => prev.filter((e) => e.id !== payload.old.id));
        }
      )
      .subscribe();

    return () => {
      mounted = false;
      clearTimeout(timeout);
      supabase.removeChannel(channel);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return { events, isLoading };
}

"use client";

import { useEffect, useState } from "react";
import { createClient } from "@/lib/supabase/client";

export interface LiveStats {
  iftarPacksDistributed: number;
  activeVolunteers: number;
  donationsCollected: number;
  zakatCountersLive: number;
  isLoading: boolean;
}

// Seeded fallback values shown while DB is loading or unreachable
const FALLBACK: Omit<LiveStats, "isLoading"> = {
  iftarPacksDistributed: 1200,
  activeVolunteers: 85,
  donationsCollected: 12000,
  zakatCountersLive: 5,
};

export function useLiveStats(): LiveStats {
  const [stats, setStats] = useState<Omit<LiveStats, "isLoading">>(FALLBACK);
  const [isLoading, setIsLoading] = useState(false); // Start false so fallback shows immediately

  useEffect(() => {
    let mounted = true;

    const fetchStats = async () => {
      try {
        const supabase = createClient();

        // Use the SECURE RPC to get aggregated stats
        // This bypasses RLS for the SUM/COUNT while keeping individual rows private.
        const { data: rpcData, error: rpcError } = await supabase.rpc("get_public_stats");

        if (!mounted) return;

        if (rpcError) {
          console.warn("useLiveStats RPC error, using fallbacks:", rpcError.message);
          return;
        }

        if (rpcData && rpcData.length > 0) {
          const row = rpcData[0];
          setStats({
            iftarPacksDistributed: Number(row.iftar_packs_distributed),
            activeVolunteers: Number(row.active_volunteers),
            donationsCollected: Number(row.donations_collected),
            zakatCountersLive: Number(row.zakat_counters_live),
          });
        }
      } catch (err) {
        console.warn("useLiveStats: using fallback values:", err);
      }
    };

    fetchStats();

    // Re-fetch stats on any relevant table change
    const supabase = createClient();
    const channel = supabase
      .channel("live-stats")
      .on("postgres_changes", { event: "*", schema: "public", table: "food_events" }, fetchStats)
      .on("postgres_changes", { event: "*", schema: "public", table: "kupon_claims" }, fetchStats)
      .on("postgres_changes", { event: "*", schema: "public", table: "user_roles" }, fetchStats)
      .on("postgres_changes", { event: "*", schema: "public", table: "donations" }, fetchStats)
      .on("postgres_changes", { event: "*", schema: "public", table: "zakat_counters" }, fetchStats)
      .subscribe();

    return () => {
      mounted = false;
      supabase.removeChannel(channel);
    };
  }, []);

  return { ...stats, isLoading };
}

import { useState, useCallback } from "react";
import { getFirebaseMessaging } from "@/lib/firebase";
import { getToken } from "firebase/messaging";
import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/components/providers/AuthContext";
import toast from "react-hot-toast";

export function usePushNotifications() {
  const { user } = useAuth();
  const [isSubscribing, setIsSubscribing] = useState(false);

  const subscribeToNotifications = useCallback(async () => {
    if (!user) {
      toast.error("You must be logged in to enable notifications");
      return;
    }

    if (!('serviceWorker' in navigator)) {
      toast.error("Notifications are not supported in this browser");
      return;
    }

    setIsSubscribing(true);
    try {
      const permission = await Notification.requestPermission();
      
      if (permission === "granted") {
        const messaging = await getFirebaseMessaging();
        if (!messaging) throw new Error("Messaging not supported");

        // Get FCM Token
        const token = await getToken(messaging, {
          vapidKey: process.env.NEXT_PUBLIC_FIREBASE_VAPID_KEY
        });

        if (token) {
          const supabase = createClient();
          
          // 1. Fetch current tokens
          const { data: profile } = await supabase
            .from("profiles")
            .select("fcm_tokens")
            .eq("id", user.id)
            .single();

          const existingTokens = profile?.fcm_tokens || [];
          
          // 2. Add new token if it doesn't exist
          if (!existingTokens.includes(token)) {
            const { error: updateError } = await supabase
              .from("profiles")
              .update({
                fcm_tokens: [...existingTokens, token],
                updated_at: new Date().toISOString()
              })
              .eq("id", user.id);

            if (updateError) throw updateError;
          }

          toast.success("Notifications enabled successfully!");
          return true;
        } else {
          toast.error("Failed to generate device token");
        }
      } else {
        toast.error("Permission denied for notifications");
      }
    } catch (error: any) {
      console.error("Push notification error:", error);
      toast.error(error.message || "Failed to enable notifications");
    } finally {
      setIsSubscribing(false);
    }
    return false;
  }, [user]);

  const unsubscribeFromNotifications = useCallback(async () => {
    if (!user) return;
    setIsSubscribing(true);
    try {
      const messaging = await getFirebaseMessaging();
      if (!messaging) throw new Error("Messaging not supported");

      const token = await getToken(messaging, {
        vapidKey: process.env.NEXT_PUBLIC_FIREBASE_VAPID_KEY
      });

      if (token) {
        const supabase = createClient();
        const { data: profile } = await supabase
          .from("profiles")
          .select("fcm_tokens")
          .eq("id", user.id)
          .single();

        const existingTokens = profile?.fcm_tokens || [];
        const newTokens = existingTokens.filter((t: string) => t !== token);

        const { error: updateError } = await supabase
          .from("profiles")
          .update({
            fcm_tokens: newTokens,
            updated_at: new Date().toISOString()
          })
          .eq("id", user.id);

        if (updateError) throw updateError;
        toast.success("Notifications disabled");
      }
    } catch (error: any) {
      console.error("Unsubscribe error:", error);
      toast.error(error.message || "Failed to disable notifications");
    } finally {
      setIsSubscribing(false);
    }
  }, [user]);

  return {
    subscribeToNotifications,
    unsubscribeFromNotifications,
    isSubscribing
  };
}

import { createClient } from "@/lib/supabase/client";

interface ClaimResult {
  success: boolean;
  error?: string;
}

// These are the hardcoded fallback IDs used when food_events table is empty.
// Claims for these IDs should be allowed locally without hitting the DB
// (the real rows don't exist in the database, so FK constraint would fail).
const FALLBACK_EVENT_IDS = new Set([
  "11111111-1111-4111-a111-111111111111",
  "22222222-2222-4222-a222-222222222222",
]);

/**
 * Claim a food kupon for the given event.
 * Falls back to local-only claim if DB is unreachable.
 */
export async function claimKupon(
  eventId: string,
  guestUuid: string,
  deviceUuid?: string
): Promise<ClaimResult & { claimId?: string }> {
  try {
    // If this is a fallback/demo event (no real DB row), allow local claim only.
    if (FALLBACK_EVENT_IDS.has(eventId)) {
      console.info("Demo event ΓÇö local claim only (no DB row exists).");
      return { success: true };
    }

    const supabase = createClient();

    const result = await Promise.race([
      supabase.from("kupon_claims").insert({
        event_id: eventId,
        guest_uuid: guestUuid,
        ...(deviceUuid ? { device_uuid: deviceUuid } : {}),
      }).select("id").single().then(r => r),
      new Promise<{ data: any, error: { code: string; message: string } | null }>((resolve) =>
        setTimeout(() => resolve({ data: null, error: { code: "TIMEOUT", message: "Request timed out" } }), 5000)
      ),
    ]);

    if (result.error) {
      if (result.error.code === "23505") {
        // Could be either guest_uuid or device_uuid constraint violation
        return { success: false, error: "A kupon for this event has already been claimed on this device." };
      }
      // Foreign key violation ΓÇö the event_id doesn't exist in food_events
      if (result.error.code === "23503") {
        return { success: false, error: "This event no longer exists. Please refresh the page." };
      }
      // Timeout ΓÇö do NOT silently succeed; ask user to retry
      if (result.error.code === "TIMEOUT") {
        return { success: false, error: "Request timed out. Please check your connection and try again." };
      }
      // RLS / permission error ΓÇö return failure (never fake a successful claim)
      if (result.error.code === "42501" || result.error.message?.includes("policy")) {
        return { success: false, error: "You are not authorized to claim this kupon." };
      }
      return { success: false, error: result.error.message };
    }
    return { success: true, claimId: result.data?.id };
  } catch (err: any) {
    console.error("Kupon claim request failed:", err);
    return { success: false, error: err?.message || "Failed to claim kupon. Please try again." };
  }
}

/**
 * Cancel a food kupon claim for the given event.
 */
export async function cancelKupon(
  claimId: string
): Promise<ClaimResult> {
  try {
    const supabase = createClient();
    const { error } = await supabase.rpc("cancel_kupon", {
      p_claim_id: claimId,
    });

    if (error) {
      return { success: false, error: error.message };
    }
    return { success: true };
  } catch (err: any) {
    console.warn("Kupon cancel request failed:", err);
    return { success: false, error: err?.message || "Failed to cancel kupon" };
  }
}

/**
 * Claim a volunteer gig slot.
 * Uses the claim_gig RPC which enforces time-overlap validation server-side.
 */
export async function claimGig(
  gigId: string,
  guestUuid: string
): Promise<ClaimResult> {
  try {
    const supabase = createClient();

    const result = await Promise.race([
      supabase.rpc('claim_gig', { p_gig_id: gigId, p_guest_uuid: guestUuid }),
      new Promise<{ error: { code: string; message: string } | null }>((resolve) =>
        setTimeout(() => resolve({ error: { code: "TIMEOUT", message: "Request timed out" } }), 5000)
      ),
    ]);

    if (result.error) {
      if ((result.error as any).code === "23505" || (result.error as any).message?.includes('already claimed')) {
        return { success: false, error: "You have already claimed this gig." };
      }
      if ((result.error as any).message?.includes('overlaps')) {
        return { success: false, error: (result.error as any).message };
      }
      if ((result.error as any).code === '23503') {
        return { success: false, error: "This gig no longer exists. Please refresh the page." };
      }
      return { success: false, error: (result.error as any).message };
    }
    return { success: true };
  } catch (err: any) {
    console.error("Gig claim request failed:", err);
    return { success: false, error: err.message || "Failed to claim gig" };
  }
}

/**
 * Cancel / unclaim a volunteer gig slot.
 * Uses .select() so we can detect when RLS silently blocks the DELETE
 * (Supabase returns no error but 0 rows deleted when policy denies it).
 */
export async function cancelGig(
  gigId: string,
  guestUuid: string
): Promise<ClaimResult> {
  try {
    const supabase = createClient();

    const { data, error } = await Promise.race([
      supabase
        .from("gig_claims")
        .delete()
        .eq("gig_id", gigId)
        .eq("guest_uuid", guestUuid)
        .select(), // ΓåÉ crucial: returns deleted rows so we can verify
      new Promise<{ data: null; error: { code: string; message: string } }>((resolve) =>
        setTimeout(
          () => resolve({ data: null, error: { code: "TIMEOUT", message: "Request timed out" } }),
          5000
        )
      ),
    ]);

    if (error) {
      if ((error as any).code === "TIMEOUT") {
        console.warn("Cancel gig timed out.");
        return { success: false, error: "Request timed out. Please try again." };
      }
      console.warn("cancelGig DB error:", (error as any).message);
      return { success: false, error: (error as any).message };
    }

    // If the delete was blocked by RLS, data will be an empty array (no rows deleted)
    if (!data || (data as any[]).length === 0) {
      console.warn("cancelGig: 0 rows deleted ΓÇö RLS policy likely blocked it. Run supabase/fix_cancel_gig_rls.sql in Supabase.");
      return {
        success: false,
        error: "Permission denied. The AJK may need to enable cancellations in Supabase settings.",
      };
    }

    return { success: true };
  } catch (err: any) {
    console.warn("cancelGig exception:", err?.message);
    return { success: false, error: "Unexpected error. Please try again." };
  }
}

/**
 * Scan a kupon claim as an admin.
 */
export async function scanKupon(
  claimInput: string
): Promise<ClaimResult & { remaining?: number }> {
  try {
    const supabase = createClient();

    // The admin scans a truncated ID (first 8 chars of guest_uuid or id).
    // Let's resolve the full claim ID first.
    let resolvedClaimId = claimInput;

    // Instead of querying by UUID (which causes error if input is not a full UUID),
    // we fetch unscanned claims and find the match.
    // (In production with high volume, a dedicated RPC or text casting view is better).
    const { data: claims, error: searchError } = await supabase
      .from("kupon_claims")
      .select("id, guest_uuid")
      .eq("is_scanned", false);

    if (searchError) {
      console.warn("Error searching for claim:", searchError.message);
      return { success: false, error: "Database error while searching for Kupon." };
    }

    if (claims && claims.length > 0) {
      const inputLower = claimInput.toLowerCase();
      const matches = claims.filter(c =>
        c.guest_uuid.toLowerCase().startsWith(inputLower) ||
        c.id.toLowerCase().startsWith(inputLower)
      );

      if (matches.length === 0) {
        return { success: false, error: "Kupon not found or already scanned." };
      }
      if (matches.length > 1) {
        return { success: false, error: "Multiple matching Kupons found. Please provide a more specific ID." };
      }

      resolvedClaimId = matches[0].id;
    }

    // Call the RPC with the resolved full UUID
    const { data, error } = await supabase.rpc("scan_kupon", {
      p_claim_id: resolvedClaimId,
    });

    if (error) {
      // Handle the case where the provided claimId wasn't found in active claims 
      // (e.g. if claims dataset was empty, resolvedClaimId = claimInput)
      if (error.code === "22P02") {
        return { success: false, error: "Invalid Kupon ID format." };
      }
      console.warn("scan_kupon RPC error:", error.message);
      return { success: false, error: error.message };
    }

    if (data && data.success === false) {
      return { success: false, error: data.error };
    }

    return { success: true, remaining: data?.remaining };
  } catch (err: any) {
    console.warn("scanKupon exception:", err?.message);
    return { success: false, error: "Unexpected error. Please try again." };
  }
}

const fs = require('fs');
